final_template:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment (non-infrastructure value)."
  type        = string
  default     = "my-api-env"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk platform solution stack name (static, non-infrastructure configuration value)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.1 running Python 3.12"
}

variable "additional_tags" {
  description = "Optional additional non-infrastructure tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = merge(
    {
      Environment = var.environment_name
      ManagedBy   = "terraform"
    },
    var.additional_tags,
  )
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "eb_ec2_role" })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = merge(local.common_tags, { Name = "eb_ec2_profile" })
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_service_role" {
  name = "eb_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEBAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "eb_service_role" })
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# Networking foundation (greenfield VPC)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "my-api-app-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "my-api-app-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "my-api-app-public-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "my-api-app-public-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security group for the Elastic Beanstalk EC2 instances
# -----------------------------------------------------------------------------

resource "aws_security_group" "eb_instances_sg" {
  name        = "eb-instances-sg"
  description = "Security group for Elastic Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "eb-instances-sg" })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "my_api_app" {
  name        = "my_api_app"
  description = "my_api_app Elastic Beanstalk application"

  tags = merge(local.common_tags, { Name = "my_api_app" })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk environment (WebServer tier, ALB, CPU autoscaling)
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_environment" "my_api_env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.my_api_app.name
  description         = "my_api_app web server environment with CPU-based autoscaling"
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  # --- Autoscaling capacity ---
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  # --- Autoscaling triggers (CPU utilization) ---
  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "MeasureName"
    value     = "CPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Unit"
    value     = "Percent"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Statistic"
    value     = "Average"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperThreshold"
    value     = "70"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperBreachScaleIncrement"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerThreshold"
    value     = "20"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerBreachScaleIncrement"
    value     = "-1"
  }

  # --- IAM wiring ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  # --- Environment / load balancer ---
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  # --- VPC wiring ---
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  # --- Instance security group ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances_sg.id
  }

  tags = merge(local.common_tags, { Name = var.environment_name })

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_instance_profile.eb_ec2_profile,
  ]
}

output "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.my_api_env.name
}

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.my_api_env.endpoint_url
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Registered domain name managed by the Route 53 hosted zone."
  type        = string
  default     = "example.com"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack used by the environment."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.1 running Python 3.11"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  eb_subnet_ids = join(",", [aws_subnet.public_a.id, aws_subnet.public_b.id])
}

# ---------------------------------------------------------------------------
# Route 53 public hosted zone
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Network foundation (greenfield)
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "main-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "main-public-b"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "main-public"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security group for Beanstalk EC2 instances (HTTP from inside VPC only)
# ---------------------------------------------------------------------------

resource "aws_security_group" "eb_instance_sg" {
  name        = "eb-instance-sg"
  description = "Elastic Beanstalk EC2 instances - HTTP ingress from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-instance-sg"
  }
}

# ---------------------------------------------------------------------------
# S3 bucket for Elastic Beanstalk application source bundles
# ---------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_s3_bucket" "examplebucket" {
  bucket = "myapp-eb-${random_id.bucket_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "myapp-eb-source-bundles"
  }
}

resource "aws_s3_bucket_public_access_block" "examplebucket" {
  bucket = aws_s3_bucket.examplebucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "examplebucket" {
  bucket = aws_s3_bucket.examplebucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "examplebucket" {
  bucket = aws_s3_bucket.examplebucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# Application source bundle built entirely in-config
# ---------------------------------------------------------------------------

data "archive_file" "myapp" {
  type        = "zip"
  output_path = "${path.module}/myapp.zip"

  source {
    filename = "application.py"
    content  = <<-EOT
import os

from flask import Flask

application = Flask(__name__)


@application.route("/")
def index():
    return "Hello from myapp running on AWS Elastic Beanstalk!"


@application.route("/health")
def health():
    return "OK"


if __name__ == "__main__":
    application.run(host="0.0.0.0", port=int(os.environ.get("PORT", "8000")))
EOT
  }

  source {
    filename = "requirements.txt"
    content  = "flask==3.0.3\n"
  }
}

resource "aws_s3_object" "examplebucket_object" {
  bucket       = aws_s3_bucket.examplebucket.bucket
  key          = "myapp.zip"
  source       = data.archive_file.myapp.output_path
  etag         = data.archive_file.myapp.output_md5
  content_type = "application/zip"
}

# ---------------------------------------------------------------------------
# IAM role and instance profile for Beanstalk EC2 instances
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "eb_ec2_role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# ---------------------------------------------------------------------------
# Elastic Beanstalk application, version, and environment
# ---------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "myapp Elastic Beanstalk application"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.examplebucket.bucket
  key         = aws_s3_object.examplebucket_object.key
}

resource "aws_elastic_beanstalk_environment" "eb-env" {
  name                = "eb-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = var.solution_stack_name
  cname_prefix        = "eb-env"
  version_label       = aws_elastic_beanstalk_application_version.version.name

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instance_sg.id
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = local.eb_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = local.eb_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
  ]
}

# ---------------------------------------------------------------------------
# Route 53 record directing traffic to the Beanstalk environment
# ---------------------------------------------------------------------------

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${aws_route53_zone.main.name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_elastic_beanstalk_environment.eb-env.cname]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "eb_environment_endpoint" {
  description = "Public endpoint (CNAME) of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eb-env.cname
}

output "app_record_fqdn" {
  description = "FQDN of the Route 53 record that directs traffic to the Beanstalk environment."
  value       = aws_route53_record.app.fqdn
}

output "route53_name_servers" {
  description = "Name servers of the hosted zone; configure these at the domain registrar to delegate DNS."
  value       = aws_route53_zone.main.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environments         = ["production", "staging"]
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24"]
  db_username          = "ebadmin"
  db_name              = "ebdb"
  solution_stack       = "64bit Amazon Linux 2023 v4.0.0 running Python 3.11"
}

# -----------------------------------------------------------------------------
# Network layer
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "eb-vpc"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "eb-internet-gateway"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_subnet" "public" {
  count                   = length(local.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "eb-public-subnet-${count.index}"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "eb-private-subnet-${count.index}"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "eb-public-route-table"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance profile for Beanstalk EC2 instances
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "eb-ec2-role"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_docker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = {
    Name        = "eb_ec2_profile"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# IAM: Beanstalk service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_service_role" {
  name = "eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "elasticbeanstalk.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "eb-service-role"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "eb_service_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealthMonitoring"
}

resource "aws_iam_role_policy_attachment" "eb_service_operations" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

# Ingress is limited to 80/443 because these instances are the public-facing
# web tier; all end-user traffic enters through HTTP/HTTPS only.
resource "aws_security_group" "eb_instances" {
  name        = "eb-instances-sg"
  description = "Elastic Beanstalk EC2 instances - ingress restricted to HTTP/HTTPS (public web tier), unrestricted egress for package downloads and outbound calls"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere - required for the public web tier"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere - required for the public web tier"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "eb-instances-sg"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_security_group" "rds" {
  name        = "eb-rds-sg"
  description = "RDS Postgres instances - ingress limited to 5432 sourced from the Beanstalk instance security group only; the database tier is never exposed publicly"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from Beanstalk instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instances.id]
  }

  tags = {
    Name        = "eb-rds-sg"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-app"
  description = "My application served by the production and staging Elastic Beanstalk environments"

  tags = {
    Name        = "my-app"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# RDS subnet group and database credentials
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "rds" {
  name       = "eb-rds-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name        = "eb-rds-subnet-group"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "random_password" "db_master" {
  for_each         = toset(local.environments)
  length           = 24
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  for_each    = toset(local.environments)
  name        = "eb/${each.key}/db-master-credentials"
  description = "Master credentials for the ${each.key} RDS instance"

  tags = {
    Name        = "eb-${each.key}-db-master-credentials"
    Environment = each.key
    ManagedBy   = "terraform"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  for_each  = toset(local.environments)
  secret_id = aws_secretsmanager_secret.db_master[each.key].id

  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master[each.key].result
  })
}

# -----------------------------------------------------------------------------
# RDS instances
# -----------------------------------------------------------------------------

# NOTE: RDS identifiers cannot contain underscores, so the physical identifiers
# use hyphens while the Terraform resource names remain prod_db / staging_db.
resource "aws_db_instance" "prod_db" {
  identifier                = "prod-db"
  engine                    = "postgres"
  engine_version            = "16"
  instance_class            = "db.t3.medium"
  allocated_storage         = 20
  max_allocated_storage     = 100
  db_name                   = local.db_name
  username                  = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["username"]
  password                  = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["password"]
  db_subnet_group_name      = aws_db_subnet_group.rds.name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  publicly_accessible       = false
  multi_az                  = true
  storage_encrypted         = true
  deletion_protection       = true
  backup_retention_period   = 7
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "prod-db-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "prod_db"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_db_instance" "staging_db" {
  identifier                = "staging-db"
  engine                    = "postgres"
  engine_version            = "16"
  instance_class            = "db.t3.micro"
  allocated_storage         = 20
  db_name                   = local.db_name
  username                  = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["username"]
  password                  = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["password"]
  db_subnet_group_name      = aws_db_subnet_group.rds.name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  publicly_accessible       = false
  multi_az                  = false
  storage_encrypted         = true
  backup_retention_period   = 3
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "staging-db-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "staging_db"
    Environment = "staging"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk environments
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_environment" "production" {
  name                = "production"
  application         = aws_elastic_beanstalk_application.app.name
  cname_prefix        = "production"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VpcId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "2"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.prod_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.prod_db.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.prod_db.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["username"]
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["password"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_docker_tier,
    aws_iam_role_policy_attachment.eb_service_health,
    aws_iam_role_policy_attachment.eb_service_operations,
  ]

  tags = {
    Name        = "production"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_elastic_beanstalk_environment" "staging" {
  name                = "staging"
  application         = aws_elastic_beanstalk_application.app.name
  cname_prefix        = "staging"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VpcId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "SingleInstance"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.micro"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "1"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.staging_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.staging_db.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.staging_db.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["username"]
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["password"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_docker_tier,
    aws_iam_role_policy_attachment.eb_service_health,
    aws_iam_role_policy_attachment.eb_service_operations,
  ]

  tags = {
    Name        = "staging"
    Environment = "staging"
    ManagedBy   = "terraform"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static provider metadata (permitted pure lookups)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  db_master_username = "dbadmin"
  public_subnet_ids  = [aws_subnet.eb_subnet_public_1.id, aws_subnet.eb_subnet_public_2.id]
}

###############################################################################
# Credential generation and uniqueness helpers
###############################################################################

resource "random_password" "shared_rds_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_string" "eb_env_1_suffix" {
  length  = 6
  special = false
  upper   = false
}

resource "random_string" "eb_env_2_suffix" {
  length  = 6
  special = false
  upper   = false
}

###############################################################################
# Networking: VPC, Internet Gateway, public subnets, routing
###############################################################################

resource "aws_vpc" "eb_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "eb_vpc"
  }
}

resource "aws_internet_gateway" "eb_igw" {
  vpc_id = aws_vpc.eb_vpc.id

  tags = {
    Name = "eb_igw"
  }
}

resource "aws_subnet" "eb_subnet_public_1" {
  vpc_id                  = aws_vpc.eb_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb_subnet_public_1"
  }
}

resource "aws_subnet" "eb_subnet_public_2" {
  vpc_id                  = aws_vpc.eb_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb_subnet_public_2"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.eb_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eb_igw.id
  }

  tags = {
    Name = "eb_public_route_table"
  }
}

resource "aws_route_table_association" "eb_subnet_public_1" {
  subnet_id      = aws_subnet.eb_subnet_public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "eb_subnet_public_2" {
  subnet_id      = aws_subnet.eb_subnet_public_2.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "eb_env_sg" {
  name        = "eb_env_sg"
  description = "Security group attached to both Elastic Beanstalk environments (web tier)"
  vpc_id      = aws_vpc.eb_vpc.id

  tags = {
    Name = "eb_env_sg"
  }
}

resource "aws_security_group_rule" "eb_env_sg_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_env_sg.id
}

resource "aws_security_group_rule" "eb_env_sg_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_env_sg.id
}

resource "aws_security_group_rule" "eb_env_sg_egress_all" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_env_sg.id
}

resource "aws_security_group" "shared_rds_sg" {
  name        = "shared_rds_sg"
  description = "Security group for the shared_rds PostgreSQL database, ingress restricted to eb_env_sg"
  vpc_id      = aws_vpc.eb_vpc.id

  tags = {
    Name = "shared_rds_sg"
  }
}

resource "aws_security_group_rule" "shared_rds_sg_ingress_from_eb" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eb_env_sg.id
  security_group_id        = aws_security_group.shared_rds_sg.id
}

###############################################################################
# Secrets Manager: RDS master credentials (never in plaintext/variables/locals)
###############################################################################

resource "aws_secretsmanager_secret" "shared_rds_master" {
  name        = "shared-rds-master-credentials"
  description = "Master credentials for the shared_rds PostgreSQL instance consumed by the Elastic Beanstalk environments"

  tags = {
    Name = "shared_rds_master_credentials"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "shared_rds_master" {
  secret_id = aws_secretsmanager_secret.shared_rds_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.shared_rds_master_password.result
  })
}

###############################################################################
# Shared RDS database
###############################################################################

resource "aws_db_subnet_group" "shared_rds" {
  name        = "shared-rds-subnet-group"
  description = "DB subnet group spanning eb_subnet_public_1 and eb_subnet_public_2 across two AZs"
  subnet_ids  = local.public_subnet_ids

  tags = {
    Name = "shared_rds_subnet_group"
  }
}

resource "aws_db_instance" "shared_rds" {
  identifier     = "shared-rds"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = "shared_rds"
  port     = 5432
  username = jsondecode(aws_secretsmanager_secret_version.shared_rds_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.shared_rds_master.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.shared_rds.name
  vpc_security_group_ids = [aws_security_group.shared_rds_sg.id]
  publicly_accessible    = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = true

  tags = {
    Name = "shared_rds"
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Elastic Beanstalk application and IAM prerequisites
###############################################################################

resource "aws_elastic_beanstalk_application" "eb_app" {
  name        = "shared-rds-app"
  description = "Parent application hosting the two Elastic Beanstalk environments backed by the shared_rds database"

  tags = {
    Name = "shared-rds-app"
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEC2AssumeRole"
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eb-ec2-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "eb-instance-profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_service_linked_role" "eb_service_linked" {
  aws_service_name = "elasticbeanstalk.amazonaws.com"
  description      = "Service-linked role for Elastic Beanstalk"
}

###############################################################################
# Elastic Beanstalk environment 1
###############################################################################

resource "aws_elastic_beanstalk_environment" "eb_env_1" {
  name                = "eb-env-1-${random_string.eb_env_1_suffix.result}"
  description         = "Elastic Beanstalk environment 1 connected to the shared_rds PostgreSQL database"
  application         = aws_elastic_beanstalk_application.eb_app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.0.1 running Python 3.12"
  cname_prefix        = "eb-env-1-${random_string.eb_env_1_suffix.result}"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VpcId"
    value     = aws_vpc.eb_vpc.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_env_sg.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.shared_rds.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.shared_rds.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.shared_rds.db_name
  }

  tags = {
    Name = "eb_env_1"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_service_linked_role.eb_service_linked,
  ]
}

###############################################################################
