###############################################################################

resource "aws_elastic_beanstalk_environment" "eb_env_2" {
  name                = "eb-env-2-${random_string.eb_env_2_suffix.result}"
  description         = "Elastic Beanstalk environment 2 connected to the shared_rds PostgreSQL database"
  application         = aws_elastic_beanstalk_application.eb_app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.0.1 running Python 3.12"
