output "eb_env_1_url" {
  description = "Public DNS name of Elastic Beanstalk environment 1"
  value       = aws_elastic_beanstalk_environment.eb_env_1.cname
}

output "eb_env_2_url" {
  description = "Public DNS name of Elastic Beanstalk environment 2"
  value       = aws_elastic_beanstalk_environment.eb_env_2.cname
}

output "shared_rds_endpoint" {
  description = "Connection endpoint of the shared_rds PostgreSQL instance"
  value       = aws_db_instance.shared_rds.address
}

output "shared_rds_secret_arn" {
