terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Purpose   = "domain-ownership-verification"
      ManagedBy = "terraform"
    }
  }
}

variable "verification_string" {
  description = "Public TXT record value used for domain ownership verification. TXT records are publicly readable by design, so a plain-text default is compliant and this is not a secret."
  type        = string
  default     = "passwordpassword"
}

locals {
  # Route 53 TXT record values must be wrapped in embedded double quotes.
  domain_verification_txt = "\"${var.verification_string}\""
}

resource "aws_route53_zone" "example" {
  name = "example"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "domain_verification" {
  zone_id = aws_route53_zone.example.zone_id
  name    = aws_route53_zone.example.name
  type    = "TXT"
  ttl     = 300

  records = [local.domain_verification_txt]
}

output "hosted_zone_id" {
  description = "Zone ID of the example Route 53 hosted zone."
  value       = aws_route53_zone.example.zone_id
}

output "hosted_zone_name_servers" {
  description = "Delegation name servers assigned to the example hosted zone."
  value       = aws_route53_zone.example.name_servers
}

output "verification_record_fqdn" {
  description = "FQDN of the TXT record used for domain ownership verification."
  value       = aws_route53_record.domain_verification.fqdn
}

output "verification_record_value" {
  description = "TXT value that must be present at the zone apex for domain ownership verification."
  value       = local.domain_verification_txt
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  type        = string
  default     = "my-environment"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk EC2 instances."
  type        = string
  default     = "t3.small"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack (Amazon Linux 2023 running Python 3.12)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.1 running Python 3.12"
}

variable "common_tags" {
  description = "Common tags applied to all tagged resources."
  type        = map(string)
  default = {
    Project   = "elastic-beanstalk-webserver"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  public_subnet_ids = join(",", aws_subnet.public[*].id)
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, { Name = "eb-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, { Name = "eb-igw" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.common_tags, { Name = "eb-public-subnet-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, { Name = "eb-public-route-table" })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "eb_instance_sg" {
  name        = "eb-instance-sg"
  description = "Allow inbound HTTP from within the VPC only, for Elastic Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.common_tags, { Name = "eb-instance-sg" })
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_role" "eb_service_role" {
  name = "eb_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_role_policy" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my_application"
  description = "My Elastic Beanstalk application for a Python web server"

  tags = var.common_tags
}

resource "aws_elastic_beanstalk_environment" "my_environment" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.my_application.name
  tier                = "WebServer"
  solution_stack_name = var.solution_stack_name
  cname_prefix        = "my-app-${random_string.suffix.result}"

  tags = var.common_tags

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instance_sg.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_service_role_policy,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
  ]
}

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk environment."
  value       = "http://${aws_elastic_beanstalk_environment.my_environment.cname}"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "application_environment_name" {
  description = "User-controlled name applied only to resource tags and descriptions."
  type        = string
  default     = "eb-appversion-lifecycle-env"

  validation {
    condition     = length(var.application_environment_name) > 0
    error_message = "The application environment name must not be empty."
  }
}

data "aws_caller_identity" "current" {}

locals {
  environment_name        = var.application_environment_name
  app_version_bucket_name = "eb-app-versions-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket" "app_versions" {
  bucket = local.app_version_bucket_name

  tags = {
    Name        = local.app_version_bucket_name
    Environment = local.environment_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_iam_role" "eb_appversion_lifecycle" {
  name        = "eb-appversion-lifecycle-service-role"
  description = "Service role used by Elastic Beanstalk for application version lifecycle management"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = {
    Environment = local.environment_name
  }
}

resource "aws_iam_policy" "app_version_bucket_access" {
  name        = "eb-appversion-bucket-access"
  description = "Least-privilege S3 access for Elastic Beanstalk application version lifecycle management"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VersionBucketObjectActions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.app_versions.arn}/*"
      },
      {
        Sid      = "VersionBucketListAction"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.app_versions.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "app_version_bucket_access" {
  role       = aws_iam_role.eb_appversion_lifecycle.name
  policy_arn = aws_iam_policy.app_version_bucket_access.arn
}

resource "aws_s3_bucket_policy" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEBServiceRoleObjectActions"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eb_appversion_lifecycle.arn
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.app_versions.arn}/*"
      },
      {
        Sid    = "AllowEBServiceRoleListBucket"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eb_appversion_lifecycle.arn
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.app_versions.arn
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.app_versions]
}

resource "aws_elastic_beanstalk_application" "main" {
  name        = "eb-appversion-lifecycle-app"
  description = "Elastic Beanstalk application with application version lifecycle for environment ${local.environment_name}"

  appversion_lifecycle {
    service_role          = aws_iam_role.eb_appversion_lifecycle.arn
    max_count             = 10
    delete_source_from_s3 = true
  }

  tags = {
    Name        = "eb-appversion-lifecycle-app"
    Environment = local.environment_name
  }

  depends_on = [aws_iam_role_policy_attachment.app_version_bucket_access]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  project_name        = "example-project"
  codebuild_role_name = "example-codebuild-role"
  log_group_name      = "/aws/codebuild/${local.project_name}"
}

resource "aws_iam_role" "codebuild_role" {
  name        = local.codebuild_role_name
  description = "IAM role assumed by the example CodeBuild project"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCodeBuildToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name      = local.codebuild_role_name
    ManagedBy = "terraform"
  }
}

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 30

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name      = local.log_group_name
    ManagedBy = "terraform"
  }
}

resource "aws_iam_role_policy" "codebuild_cloudwatch_logs" {
  name = "example-codebuild-cloudwatch-logs"
  role = aws_iam_role.codebuild_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_codebuild_project" "example_project" {
  name          = local.project_name
  description   = "Example CodeBuild project with no source and no artifacts"
  build_timeout = 10
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "ENVIRONMENT"
      value = "example"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "PROJECT_NAME"
      value = local.project_name
      type  = "PLAINTEXT"
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = aws_cloudwatch_log_group.codebuild_logs.name
      stream_name = "example-build-logs"
      status      = "ENABLED"
    }
  }

  source {
    type      = "NO_SOURCE"
    buildspec = <<-EOT
      version: 0.2

      phases:
        build:
          commands:
            - echo "Running example CodeBuild project with NO_SOURCE"
            - echo "ENVIRONMENT=$ENVIRONMENT"
            - echo "PROJECT_NAME=$PROJECT_NAME"
    EOT
  }

  tags = {
    Name        = local.project_name
    Environment = "example"
    ManagedBy   = "terraform"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Name of the CodeBuild project."
  type        = string
  default     = "example-codebuild-project"
}

variable "environment_tag" {
  description = "Environment tag applied to all resources."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

locals {
  project_slug          = lower(replace(var.project_name, "_", "-"))
  primary_bucket_name   = "${local.project_slug}-${data.aws_caller_identity.current.account_id}-primary-artifacts"
  secondary_bucket_name = "${local.project_slug}-${data.aws_caller_identity.current.account_id}-secondary-artifacts"
  log_group_name        = "/aws/codebuild/${var.project_name}"
  source_location       = "https://github.com/octocat/Hello-World.git"

  common_tags = {
    Environment = var.environment_tag
  }

  buildspec = <<-EOT
    version: 0.2

    phases:
      install:
        runtime-versions:
          python: 3.12
        commands:
          - echo "Install phase completed on $(date)"
      pre_build:
        commands:
          - echo "Pre-build phase completed on $(date)"
      build:
        commands:
          - mkdir -p output/primary output/secondary
          - echo "Primary artifact content" > output/primary/primary.txt
          - echo "Secondary artifact content" > output/secondary/secondary.txt
      post_build:
        commands:
          - echo "Build completed on $(date)"

    artifacts:
      files:
        - '**/*'
      base-directory: output/primary

    secondary-artifacts:
      secondary:
        files:
          - '**/*'
        base-directory: output/secondary
  EOT
}

# ------------------------------------------------------------------------------
# Primary build artifacts bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts_primary" {
  bucket = local.primary_bucket_name

  tags = merge(local.common_tags, {
    Name = local.primary_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts_primary" {
  bucket = aws_s3_bucket.artifacts_primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts_primary" {
  bucket = aws_s3_bucket.artifacts_primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts_primary" {
  bucket = aws_s3_bucket.artifacts_primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Secondary build artifacts bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts_secondary" {
  bucket = local.secondary_bucket_name

  tags = merge(local.common_tags, {
    Name = local.secondary_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts_secondary" {
  bucket = aws_s3_bucket.artifacts_secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts_secondary" {
  bucket = aws_s3_bucket.artifacts_secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts_secondary" {
  bucket = aws_s3_bucket.artifacts_secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Build logs
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

# ------------------------------------------------------------------------------
# CodeBuild IAM role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild_role" {
  name = "${var.project_name}-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-codebuild-role"
  })
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "${var.project_name}-codebuild-policy"
  role = aws_iam_role.codebuild_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ArtifactBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.artifacts_primary.arn,
          aws_s3_bucket.artifacts_secondary.arn,
          "${aws_s3_bucket.artifacts_primary.arn}/*",
          "${aws_s3_bucket.artifacts_secondary.arn}/*",
        ]
      },
      {
        Sid    = "CodeBuildLogAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*",
        ]
      },
    ]
  })
}

# ------------------------------------------------------------------------------
# CodeBuild project
# ------------------------------------------------------------------------------
resource "aws_codebuild_project" "example" {
  name         = var.project_name
  description  = "Example CodeBuild project with primary and secondary S3 artifacts."
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = local.source_location
    buildspec       = local.buildspec
    git_clone_depth = 1
  }

  environment {
    type                        = "LINUX_CONTAINER"
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux-x86_64-standard:5.0"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "ENVIRONMENT"
      value = var.environment_tag
    }
  }

  artifacts {
    type                = "S3"
    artifact_identifier = "primary"
    location            = aws_s3_bucket.artifacts_primary.bucket
    name                = "${var.project_name}-primary"
    encryption_disabled = false
  }

  secondary_artifacts {
    type                = "S3"
    artifact_identifier = "secondary"
    location            = aws_s3_bucket.artifacts_secondary.bucket
    name                = "${var.project_name}-secondary"
    encryption_disabled = false
  }

  logs_config {
    cloudwatch_logs {
      status     = "ENABLED"
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  tags = merge(local.common_tags, {
    Name = var.project_name
  })

  depends_on = [aws_iam_role_policy.codebuild_policy]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a user-controlled tag to every taggable resource."
  type        = string
  default     = "dev"
}

locals {
  bot_name = "ProductOrderingBot"

  common_tags = {
    Name        = local.bot_name
    Environment = var.environment
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_iam_policy_document" "lex_trust" {
  statement {
    sid    = "AllowLexV2AssumeRole"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = ["lexv2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lex_execution_permissions" {
  statement {
    sid    = "LexCreateConversationLogGroup"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lex/${local.bot_name}*",
    ]
  }

  statement {
    sid    = "LexWriteConversationLogStreams"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lex/${local.bot_name}*:log-stream:*",
    ]
  }

  statement {
    sid    = "LexDetectSentiment"
    effect = "Allow"

    actions = [
      "comprehend:DetectSentiment",
    ]

    # Comprehend does not support resource-level permissions for DetectSentiment;
    # the action itself is narrowly scoped to the single supported API operation.
    resources = ["*"]
  }
}

resource "aws_iam_role" "lex_execution" {
  name               = "${local.bot_name}-lex-execution-role"
  description        = "Execution role assumed by the Amazon Lex V2 service for the product ordering bot"
  assume_role_policy = data.aws_iam_policy_document.lex_trust.json

  tags = local.common_tags
}

resource "aws_iam_policy" "lex_execution" {
  name        = "${local.bot_name}-lex-execution-policy"
  description = "Least-privilege CloudWatch Logs and Comprehend permissions for the Lex V2 bot execution role"
  policy      = data.aws_iam_policy_document.lex_execution_permissions.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lex_execution" {
  role       = aws_iam_role.lex_execution.name
  policy_arn = aws_iam_policy.lex_execution.arn
}

resource "aws_lexv2models_bot" "main" {
  name        = local.bot_name
  description = "Product ordering bot that collects order details through multiple elicitation slots"
  role_arn    = aws_iam_role.lex_execution.arn

  data_privacy {
    child_directed = false
  }

  idle_session_ttl_in_seconds = 300

  # Aliases are declared inline as members of the bot resource. The member below
  # targets the first published version: Lex V2 assigns sequential numeric versions
  # starting at 1, and aws_lexv2models_bot_version.prod builds exactly that first
  # version from DRAFT. All member attributes are deterministic user-assigned
  # literals required by the schema — they must not reference any other resource,
  # and they must never change between plans, since the bot carries prevent_destroy.
  members {
    name       = "prod"
    alias_name = "prod"
    alias_id   = "prod"
    id         = "prod"
    version    = "1"
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.lex_execution]

  lifecycle {
    prevent_destroy = true
  }
}

# The en_US draft locale must exist before the slot type, intent, and slots can be
# created inside it. Per the Lex V2 API, locale creation is only permitted against
# the draft version, so bot_version is pinned to "DRAFT". The build that packages
# the complete configuration together is the bot version below, which is explicitly
# ordered after the locale, slot type, intent, and every slot via depends_on.
resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.main.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "English (US) locale for the product ordering bot"
  n_lu_intent_confidence_threshold = 0.7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot_type" "product_category" {
  bot_id      = aws_lexv2models_bot.main.id
  bot_version = "DRAFT"
  locale_id   = "en_US"
  name        = "ProductCategory"
  description = "Closed enumeration of product categories that can be ordered"

  slot_type_values {
    sample_value {
      value = "Electronics"
    }
  }

  slot_type_values {
    sample_value {
      value = "Books"
    }
  }

  slot_type_values {
    sample_value {
      value = "HomeAndKitchen"
    }
  }

  slot_type_values {
    sample_value {
      value = "ToysAndGames"
    }
  }

  value_selection_setting {
    resolution_strategy = "OriginalValue"
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_intent" "order_product" {
  name        = "OrderProduct"
  bot_id      = aws_lexv2models_bot.main.id
  bot_version = "DRAFT"
  locale_id   = "en_US"
  description = "Collects every detail required to place a product order"

  # Fulfillment intentionally has no Lambda code hook: the resolved intent and its
  # slot values are returned directly to the caller, keeping the bot self-contained.
  sample_utterance {
    utterance = "I would like to order a product"
  }

  sample_utterance {
    utterance = "I want to place an order"
  }

  sample_utterance {
    utterance = "Please help me order something"
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_slot_type.product_category,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# Slots are declared in the intended elicitation order:
# OrderDate, Quantity, ProductCategory, ContactPhone.
resource "aws_lexv2models_slot" "order_date" {
  name         = "OrderDate"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = "AMAZON.Date"
  description  = "The date the customer wants the order handled"

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "What date would you like your order for?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot" "quantity" {
  name         = "Quantity"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = "AMAZON.Number"
  description  = "The number of units the customer wants to order"

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "How many units would you like to order?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot" "product_category" {
  name         = "ProductCategory"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = aws_lexv2models_slot_type.product_category.slot_type_id
  description  = "The category of the product the customer wants to order"

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "What category of product would you like to order?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot" "contact_phone" {
  name         = "ContactPhone"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = "AMAZON.PhoneNumber"
  description  = "The phone number used to contact the customer about the order"

  obfuscation_setting {
    obfuscation_setting_type = "DefaultObfuscation"
  }

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "What is the best phone number to reach you about this order?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_bot_version" "prod" {
  bot_id = aws_lexv2models_bot.main.id

  locale_specification = {
    en_US = {
      source_bot_version = "DRAFT"
    }
  }

  description = "Production version of the product ordering bot including all intents and slots"

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_slot_type.product_category,
    aws_lexv2models_intent.order_product,
    aws_lexv2models_slot.order_date,
    aws_lexv2models_slot.quantity,
    aws_lexv2models_slot.product_category,
    aws_lexv2models_slot.contact_phone,
  ]
}

output "bot_id" {
  description = "Identifier of the Amazon Lex V2 bot."
  value       = aws_lexv2models_bot.main.id
}

output "bot_locale_id" {
  description = "Identifier of the en_US bot locale."
  value       = aws_lexv2models_bot_locale.en_us.id
}

output "bot_alias_id" {
  description = "Provider-assigned identifier of the prod alias declared as a bot member."
  value       = one([for member in aws_lexv2models_bot.main.members : member.alias_id])
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "User-controlled project name used as the naming prefix for all Lex, IAM, and CloudWatch resources."
  type        = string
  default     = "pizza-bot"
}

data "aws_caller_identity" "current" {}

locals {
  # Amazon Lex bot, alias, intent, and slot type names only accept letters and
  # underscores, so the project name is normalized to snake_case for Lex names.
  name_prefix    = lower(replace(var.project_name, "-", "_"))
  log_group_name = "/aws/lex/${local.name_prefix}"
  log_group_arn  = "arn:aws:logs:us-east-1:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}"

  tags = {
    Project   = var.project_name
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# IAM: execution role assumed by Amazon Lex for conversation logging
# -----------------------------------------------------------------------------

resource "aws_iam_role" "lex_bot_role" {
  name        = "${local.name_prefix}_lex_bot_role"
  description = "Execution role assumed by Amazon Lex for the ${var.project_name} pizza ordering bot."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLexServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "lex_bot_policy" {
  name = "${local.name_prefix}_lex_bot_policy"
  role = aws_iam_role.lex_bot_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSpeechSynthesisAndSentimentDetection"
        Effect = "Allow"
        Action = [
          "polly:SynthesizeSpeech",
          "comprehend:DetectSentiment",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowConversationLogWrites"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = aws_cloudwatch_log_group.lex_conversation_logs.arn
      },
    ]
  })
}

# -----------------------------------------------------------------------------
# KMS + CloudWatch Logs: encrypted, auditable conversation log storage
# -----------------------------------------------------------------------------

resource "aws_kms_key" "lex_conversation_logs" {
  description             = "Encrypts CloudWatch conversation logs for the ${var.project_name} Lex bot."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe",
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = local.log_group_arn
          }
        }
      },
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "lex_conversation_logs" {
  name          = "alias/${local.name_prefix}_lex_conversation_logs"
  target_key_id = aws_kms_key.lex_conversation_logs.key_id
}

resource "aws_cloudwatch_log_group" "lex_conversation_logs" {
  name              = local.log_group_name
  retention_in_days = 14
  kms_key_id        = aws_kms_key.lex_conversation_logs.arn

  tags = local.tags
}

# -----------------------------------------------------------------------------
# Lex: custom slot types for the pizza domain
# -----------------------------------------------------------------------------

resource "aws_lex_slot_type" "pizza_size" {
  name        = "${local.name_prefix}_pizza_size"
  description = "Pizza sizes offered by the ${var.project_name} menu."

  enumeration_value {
    value    = "Small"
    synonyms = ["personal", "individual", "10 inch"]
  }

  enumeration_value {
    value    = "Medium"
    synonyms = ["regular", "standard", "12 inch"]
  }

  enumeration_value {
    value    = "Large"
    synonyms = ["big", "family size", "14 inch"]
  }

  enumeration_value {
    value    = "X-Large"
    synonyms = ["extra large", "xl", "jumbo", "16 inch"]
  }
}

resource "aws_lex_slot_type" "pizza_crust" {
  name        = "${local.name_prefix}_pizza_crust"
  description = "Pizza crust styles offered by the ${var.project_name} menu."

  enumeration_value {
    value    = "Thin"
    synonyms = ["crispy", "thin crust", "flatbread"]
  }

  enumeration_value {
    value    = "Original"
    synonyms = ["classic", "regular", "hand tossed", "traditional"]
  }

  enumeration_value {
    value    = "Stuffed"
    synonyms = ["stuffed crust", "cheesy crust", "deep dish"]
  }

  enumeration_value {
    value    = "Gluten-Free"
    synonyms = ["gluten free", "gf", "cauliflower crust"]
  }
}

resource "aws_lex_slot_type" "pizza_toppings" {
  name        = "${local.name_prefix}_pizza_toppings"
  description = "Pizza toppings offered by the ${var.project_name} menu."

  enumeration_value {
    value    = "Pepperoni"
    synonyms = ["salami"]
  }

  enumeration_value {
    value    = "Italian Sausage"
    synonyms = ["sausage", "pork sausage"]
  }

  enumeration_value {
    value    = "Mushrooms"
    synonyms = ["mushroom", "portobello"]
  }

  enumeration_value {
    value    = "Onions"
    synonyms = ["onion", "red onion"]
  }

  enumeration_value {
    value    = "Green Peppers"
    synonyms = ["green pepper", "bell pepper"]
  }

  enumeration_value {
    value    = "Black Olives"
    synonyms = ["olives"]
  }

  enumeration_value {
    value    = "Extra Cheese"
    synonyms = ["more cheese", "double cheese"]
  }

  enumeration_value {
    value    = "Bacon"
    synonyms = ["bacon bits", "crispy bacon"]
  }

  enumeration_value {
    value    = "Pineapple"
    synonyms = ["hawaiian"]
  }

  enumeration_value {
    value    = "Grilled Chicken"
    synonyms = ["chicken", "bbq chicken"]
  }
}

resource "aws_lex_slot_type" "order_type" {
  name        = "${local.name_prefix}_order_type"
  description = "How a ${var.project_name} order is fulfilled: delivery or carryout."

  enumeration_value {
    value    = "Delivery"
    synonyms = ["deliver", "delivered", "to my door"]
  }

  enumeration_value {
    value    = "Carryout"
    synonyms = ["carry out", "pickup", "pick up", "takeout", "to go"]
  }
}

# -----------------------------------------------------------------------------
# Lex: intents
# -----------------------------------------------------------------------------

resource "aws_lex_intent" "order_pizza" {
  name        = "${local.name_prefix}_order_pizza"
  description = "Collects size, crust, toppings, and fulfillment type to place a pizza order."

  sample_utterances = [
    "I want to order a pizza",
    "I would like to order a {pizza_size} pizza",
    "Order me a {pizza_size} pizza with {pizza_toppings}",
    "Can I get a pizza for {order_type}",
    "I'd like to place a pizza order",
    "Get me a large pepperoni pizza",
  ]

  slot {
    name            = "pizza_size"
    description     = "The size of the pizza."
    slot_type       = aws_lex_slot_type.pizza_size.name
    priority        = 1
    slot_constraint = "Required"

    value_elicitation_prompt {
      max_attempts = 3
      message {
        content      = "What size pizza would you like? We offer small, medium, large, and X-large."
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  slot {
    name            = "pizza_crust"
    description     = "The crust style of the pizza."
    slot_type       = aws_lex_slot_type.pizza_crust.name
    priority        = 2
    slot_constraint = "Required"

    value_elicitation_prompt {
      max_attempts = 3
      message {
        content      = "What kind of crust would you like? Choose thin, original, stuffed, or gluten-free."
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  slot {
    name            = "pizza_toppings"
    description     = "The toppings for the pizza."
    slot_type       = aws_lex_slot_type.pizza_toppings.name
    priority        = 3
    slot_constraint = "Required"

    value_elicitation_prompt {
      max_attempts = 3
      message {
        content      = "What toppings would you like on your pizza?"
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  slot {
    name            = "order_type"
    description     = "Whether the order is delivery or carryout."
    slot_type       = aws_lex_slot_type.order_type.name
    priority        = 4
    slot_constraint = "Required"

    value_elicitation_prompt {
      max_attempts = 3
      message {
        content      = "Would you like your order delivered, or will you pick it up as a carryout?"
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content      = "Just to confirm: a {pizza_size} pizza with {pizza_toppings} on a {pizza_crust} crust for {order_type}. Shall I place the order?"
      content_type = "PlainText"
      group_number = 1
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I will not place that order. Is there anything else I can help you with?"
      content_type = "PlainText"
      group_number = 1
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "check_order_status" {
  name        = "${local.name_prefix}_check_order_status"
  description = "Looks up the status of an existing pizza order by order number."

  sample_utterances = [
    "Where is my order",
    "What is the status of order {order_number}",
    "Check my order status",
    "Track my order {order_number}",
    "Has my pizza arrived yet",
  ]

  slot {
    name            = "order_number"
    description     = "The order number to look up."
    slot_type       = "AMAZON.Number"
    priority        = 1
    slot_constraint = "Required"

    value_elicitation_prompt {
      max_attempts = 3
      message {
        content      = "Sure, what is your order number?"
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "cancel_order" {
  name        = "${local.name_prefix}_cancel_order"
  description = "Cancels an existing pizza order after explicit user confirmation."

  sample_utterances = [
    "Cancel my order",
    "I want to cancel order {order_number}",
    "Cancel order {order_number}",
    "Please cancel my pizza order",
  ]

  slot {
    name            = "order_number"
    description     = "The order number to cancel."
    slot_type       = "AMAZON.Number"
    priority        = 1
    slot_constraint = "Required"

    value_elicitation_prompt {
      max_attempts = 3
      message {
        content      = "What is the order number you would like to cancel?"
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content      = "Are you sure you want to cancel order {order_number}?"
      content_type = "PlainText"
      group_number = 1
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I will keep your order open. Is there anything else I can help you with?"
      content_type = "PlainText"
      group_number = 1
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "get_menu" {
  name        = "${local.name_prefix}_get_menu"
  description = "Shares the current pizza menu: sizes, crusts, and toppings."

  sample_utterances = [
    "What pizzas do you have",
    "Show me the menu",
    "Can I see your pizza menu",
    "What toppings can I choose from",
    "What sizes do you offer",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "store_hours" {
  name        = "${local.name_prefix}_store_hours"
  description = "Tells the user the store opening and closing hours."

  sample_utterances = [
    "What are your store hours",
    "When are you open",
    "What time do you close",
    "Are you open now",
    "What are your hours today",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

# -----------------------------------------------------------------------------
# Lex: pizza ordering bot and production alias
# -----------------------------------------------------------------------------

resource "aws_lex_bot" "pizza_ordering_bot" {
  name                            = "${local.name_prefix}_ordering_bot"
  description                     = "Conversational bot for ordering pizzas, checking order status, canceling orders, viewing the menu, and asking about store hours."
  locale                          = "en-US"
  child_directed                  = false
  detect_sentiment                = true
  enable_model_improvements       = true
  nlu_intent_confidence_threshold = 0.85
  process_behavior                = "BUILD"
  idle_session_ttl_in_seconds     = 300
  voice_id                        = "Joanna"

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = "$LATEST"
  }

  intent {
    intent_name    = aws_lex_intent.check_order_status.name
    intent_version = "$LATEST"
  }

  intent {
    intent_name    = aws_lex_intent.cancel_order.name
    intent_version = "$LATEST"
  }

  intent {
    intent_name    = aws_lex_intent.get_menu.name
    intent_version = "$LATEST"
  }

  intent {
    intent_name    = aws_lex_intent.store_hours.name
    intent_version = "$LATEST"
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Sorry, I did not quite get that. Could you please rephrase?"
      content_type = "PlainText"
      group_number = 1
    }
    message {
      content      = "I still did not understand. You can say things like I want to order a pizza, or what are your store hours."
      content_type = "PlainText"
      group_number = 2
    }
  }

  abort_statement {
    message {
      content      = "Sorry, I could not help you with that. Please try again later."
      content_type = "PlainText"
      group_number = 1
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot_alias" "production" {
  name        = "production"
  description = "Production alias for the ${var.project_name} pizza ordering bot."
  bot_name    = aws_lex_bot.pizza_ordering_bot.name
  bot_version = aws_lex_bot.pizza_ordering_bot.version

  conversation_logs {
    iam_role_arn = aws_iam_role.lex_bot_role.arn

    log_settings {
      destination  = "CLOUDWATCH_LOGS"
      log_type     = "TEXT"
      resource_arn = aws_cloudwatch_log_group.lex_conversation_logs.arn
    }
  }

  depends_on = [aws_iam_role_policy.lex_bot_policy]
}

# -----------------------------------------------------------------------------
# Outputs for downstream consumers
# -----------------------------------------------------------------------------

output "lex_bot_name" {
  description = "Name of the pizza ordering Lex bot."
  value       = aws_lex_bot.pizza_ordering_bot.name
}

output "lex_bot_arn" {
  description = "ARN of the pizza ordering Lex bot."
  value       = aws_lex_bot.pizza_ordering_bot.arn
}

output "lex_bot_version" {
  description = "Version of the pizza ordering Lex bot."
  value       = aws_lex_bot.pizza_ordering_bot.version
}

output "lex_bot_alias_name" {
  description = "Name of the production Lex bot alias."
  value       = aws_lex_bot_alias.production.name
}

output "lex_bot_alias_arn" {
  description = "ARN of the production Lex bot alias."
  value       = aws_lex_bot_alias.production.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)

  default = {
    Project     = "lex-main-bot"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "polly_synthesize_speech" {
  name = "polly-synthesize-speech"
  role = aws_iam_role.lex_bot_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "polly:SynthesizeSpeech"
        Resource = "*"
      }
    ]
  })
}

resource "aws_lexv2models_bot" "main" {
  name                        = "MainBot"
  description                 = "Main Lex V2 conversational bot managed by Terraform."
  role_arn                    = aws_iam_role.lex_bot_role.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_iam_role_policy.polly_synthesize_speech]
}

resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                            = aws_lexv2models_bot.main.id
  bot_version                       = "DRAFT"
  locale_id                         = "en_US"
  n_lu_intent_confidence_threshold  = 0.40
  description                       = "US English locale for MainBot."

  voice_settings {
    voice_id = "Joanna"
    engine   = "standard"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_intent" "greeting" {
  name        = "GreetingIntent"
  description = "Greets users in response to common greetings."
  bot_id      = aws_lexv2models_bot.main.id
  bot_version = "DRAFT"
  locale_id   = "en_US"

  sample_utterance {
    utterance = "hello"
  }

  sample_utterance {
    utterance = "hi"
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Map of user-defined tags applied to resources whose schema supports tagging."
  type        = map(string)
  default     = {}
}

locals {
  connect_instance_alias = "connect-saml-greenfield"
  lex_intent_name        = "ConnectBotIntent"
  lex_bot_name           = "ConnectBot"
}

resource "aws_connect_instance" "connect_saml" {
  instance_alias           = local.connect_instance_alias
  identity_management_type = "SAML"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_intent" "connect_bot_intent" {
  name        = local.lex_intent_name
  description = "Intent handled by the Amazon Connect Lex bot."

  sample_utterances = [
    "I would like to check my balance",
    "What is my current balance",
    "Check my balance",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot" "connect_bot" {
  name        = local.lex_bot_name
  description = "Lex bot associated with the SAML Amazon Connect instance."

  abort_statement {
    message {
      content      = "Sorry, I was unable to help you with that. Goodbye."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "I did not understand you. What would you like to do?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.connect_bot_intent.name
    intent_version = "$LATEST"
  }

  child_directed   = false
  locale           = "en-US"
  process_behavior = "BUILD"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_connect_bot_association" "connect_bot_assoc" {
  instance_id = aws_connect_instance.connect_saml.id

  lex_bot {
    name       = aws_lex_bot.connect_bot.name
    lex_region = "us-east-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  firehose_stream_name = "customer-events-delivery-stream"
  s3_bucket_name       = "firehose-dp-destination-${data.aws_caller_identity.current.account_id}"

  s3_prefix = "data/customerId=!{partitionKeyFromQuery:customerId}/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/"

  s3_error_prefix = "errors/!{firehose:error-output-type}/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/"
}

variable "tags" {
  description = "Tags applied to the destination S3 bucket, the Firehose IAM role, and the delivery stream."
  type        = map(string)
  default = {
    Project     = "firehose-dynamic-partitioning"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_s3_bucket" "firehose_destination" {
  bucket = local.s3_bucket_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_cloudwatch_log_group" "firehose_delivery_errors" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_stream" "firehose_delivery_errors" {
  name           = "S3Delivery"
  log_group_name = aws_cloudwatch_log_group.firehose_delivery_errors.name
}

resource "aws_iam_role" "firehose_delivery_role" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "firehose.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "firehose_delivery_policy" {
  name = "firehose-delivery-least-privilege"
  role = aws_iam_role.firehose_delivery_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FirehoseS3BucketLevel"
        Effect   = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.firehose_destination.arn
      },
      {
        Sid      = "FirehoseS3ObjectLevel"
        Effect   = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:AbortMultipartUpload"
        ]
        Resource = "${aws_s3_bucket.firehose_destination.arn}/*"
      },
      {
        Sid      = "FirehoseErrorLogging"
        Effect   = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.firehose_delivery_errors.arn}:*"
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "customer_events" {
  name        = local.firehose_stream_name
  destination = "extended_s3"

  server_side_encryption {
    enabled  = true
    key_type = "AWS_OWNED_CMK"
  }

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_delivery_role.arn
    bucket_arn          = aws_s3_bucket.firehose_destination.arn
    prefix              = local.s3_prefix
    error_output_prefix = local.s3_error_prefix
    compression_format  = "GZIP"
    buffering_size      = 64
    buffering_interval  = 60

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_delivery_errors.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_delivery_errors.name
    }

    dynamic_partitioning_configuration {
      enabled        = true
      retry_duration = 300
    }

    processing_configuration {
      enabled = true

      processors {
        type = "MetadataExtraction"

        parameters {
          parameter_name  = "metadataExtractionQuery"
          parameter_value = "{customerId:.customerId}"
        }

        parameters {
          parameter_name  = "jsonParsingEngine"
          parameter_value = "JQ-1.6"
        }
      }
    }
  }

  tags = var.tags

  depends_on = [aws_iam_role_policy.firehose_delivery_policy]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (user-controlled, non-infrastructure values only)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project/environment name used for resource naming and tags."
  type        = string
  default     = "acme-observability"
}

variable "splunk_hec_endpoint_url" {
  description = "HTTPS URL of the Splunk HEC endpoint that receives Firehose events."
  type        = string
  default     = "https://http-inputs-observability.splunkcloud.com:8088"

  validation {
    condition     = can(regex("^https://", var.splunk_hec_endpoint_url))
    error_message = "The Splunk HEC endpoint URL must use HTTPS."
  }
}

# -----------------------------------------------------------------------------
# Locals: naming, tag defaults, and the shared least-privilege policy document
# -----------------------------------------------------------------------------

locals {
  name_prefix          = replace(lower(var.project_name), "/[^a-z0-9-]/", "-")
  delivery_stream_name = "${local.name_prefix}-splunk-delivery"
  backup_bucket_name   = "${local.name_prefix}-splunk-failed-events"

  default_tags = {
    Project     = var.project_name
    Environment = var.project_name
    ManagedBy   = "Terraform"
  }

  firehose_permissions_policy = {
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3FailedEventObjectActions"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:AbortMultipartUpload",
          "s3:GetObject",
        ]
        Resource = "${aws_s3_bucket.splunk_backup.arn}/*"
      },
      {
        Sid    = "S3FailedEventBucketActions"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
        ]
        Resource = aws_s3_bucket.splunk_backup.arn
      },
      {
        Sid    = "FirehoseCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose.arn,
          "${aws_cloudwatch_log_group.firehose.arn}:${aws_cloudwatch_log_stream.splunk_delivery.name}",
        ]
      },
      {
        Sid      = "FirehoseSplunkHecSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = aws_secretsmanager_secret.splunk_hec_token.arn
      },
      {
        Sid    = "FirehoseStreamKmsEncryption"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = aws_kms_key.firehose.arn
      },
    ]
  }
}

# -----------------------------------------------------------------------------
# KMS key for delivery stream at-rest encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "firehose" {
  description         = "Customer managed key encrypting the ${local.delivery_stream_name} Firehose delivery stream at rest."
  enable_key_rotation = true

  tags = merge(local.default_tags, { Name = "${local.name_prefix}-firehose-cmk" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "firehose" {
  name          = "alias/${local.name_prefix}-firehose-cmk"
  target_key_id = aws_kms_key.firehose.key_id
}

# -----------------------------------------------------------------------------
# S3 backup bucket for failed events
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "splunk_backup" {
  bucket = local.backup_bucket_name

  tags = merge(local.default_tags, { Name = local.backup_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  rule {
    id     = "cleanup-failed-event-backups"
    status = "Enabled"

    filter {
      prefix = "failed-events/"
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

# -----------------------------------------------------------------------------
# CloudWatch logging for Firehose delivery diagnostics
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  retention_in_days = 14

  tags = merge(local.default_tags, { Name = "/aws/kinesisfirehose/${local.delivery_stream_name}" })
}

resource "aws_cloudwatch_log_stream" "splunk_delivery" {
  name           = "SplunkDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

# -----------------------------------------------------------------------------
# Secrets Manager: Splunk HEC token (retrieved by Firehose at runtime)
#
# The secret value is machine-generated at apply time (random_password) and is
# referenced solely by its Terraform address — it never appears as a plaintext
# literal in configuration, defaults, or locals. Because Firehose reads the
# secret's CURRENT value at runtime via secrets_manager_configuration,
# operators must replace this deployment-generated placeholder with the real
# Splunk-issued HEC token out-of-band in AWS Secrets Manager after deployment;
# rotating the value requires no Terraform change and no redeploy of the stream.
# -----------------------------------------------------------------------------

resource "random_password" "hec_token_seed" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "splunk_hec_token" {
  name        = "${local.name_prefix}-splunk-hec-token"
  description = "Splunk HEC token used by the Firehose Splunk destination. Firehose reads this secret's current value at runtime. The initial value is a deployment-generated placeholder (random_password.hec_token_seed); operators must replace it with the Splunk-issued HEC token out-of-band in AWS Secrets Manager. Rotation requires no Terraform change and no redeploy of the delivery stream."

  tags = merge(local.default_tags, { Name = "${local.name_prefix}-splunk-hec-token" })
}

resource "aws_secretsmanager_secret_version" "splunk_hec_token" {
  secret_id     = aws_secretsmanager_secret.splunk_hec_token.id
  secret_string = random_password.hec_token_seed.result
}

# -----------------------------------------------------------------------------
# IAM role for Firehose
# -----------------------------------------------------------------------------

resource "aws_iam_role" "firehose" {
  name        = "${local.name_prefix}-firehose-role"
  description = "Assume role for the Kinesis Data Firehose Splunk delivery stream."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowFirehoseServiceAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.default_tags, { Name = "${local.name_prefix}-firehose-role" })
}

resource "aws_iam_role_policy" "firehose_inline_policy" {
  name   = "${local.name_prefix}-firehose-inline"
  role   = aws_iam_role.firehose.name
  policy = jsonencode(local.firehose_permissions_policy)
}

resource "aws_iam_policy" "firehose_policy" {
  name        = "${local.name_prefix}-firehose-policy"
  description = "Least-privilege permissions for the Firehose Splunk delivery stream."
  policy      = jsonencode(local.firehose_permissions_policy)
}

resource "aws_iam_role_policy_attachment" "firehose_policy_attachment" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream with Splunk destination
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "to_splunk" {
  name        = local.delivery_stream_name
  destination = "splunk"

  server_side_encryption {
    enabled  = true
    key_type = "CUSTOMER_MANAGED_CMK"
    key_arn  = aws_kms_key.firehose.arn
  }

  splunk_configuration {
    hec_endpoint               = var.splunk_hec_endpoint_url
    hec_endpoint_type          = "Raw"
    hec_acknowledgment_timeout = 300
    retry_duration             = 300
    s3_backup_mode             = "FailedEventsOnly"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.splunk_delivery.name
    }

    secrets_manager_configuration {
      enabled    = true
      secret_arn = aws_secretsmanager_secret.splunk_hec_token.arn
      role_arn   = aws_iam_role.firehose.arn
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose.arn
      bucket_arn         = aws_s3_bucket.splunk_backup.arn
      prefix             = "failed-events/"
      buffering_size     = 10
      buffering_interval = 300
      compression_format = "GZIP"
    }
  }

  depends_on = [
    aws_secretsmanager_secret_version.splunk_hec_token,
    aws_iam_role_policy.firehose_inline_policy,
    aws_iam_role_policy_attachment.firehose_policy_attachment,
  ]

  tags = merge(local.default_tags, { Name = local.delivery_stream_name })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.to_splunk.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.to_splunk.arn
}

output "backup_bucket_name" {
  description = "Name of the S3 bucket used for failed-event backups."
  value       = aws_s3_bucket.splunk_backup.id
}

output "firehose_iam_role_arn" {
  description = "ARN of the IAM role assumed by the Firehose delivery stream."
  value       = aws_iam_role.firehose.arn
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables - only user-controlled values, with defaults for unattended apply
###############################################################################

variable "environment" {
  description = "Environment name used to prefix all resource names."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged onto every tagged resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources - static, well-known lookups only
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix          = "${var.environment}-firehose-os"
  opensearch_index     = "logs"
  backup_bucket_name   = "${local.name_prefix}-backup-${data.aws_caller_identity.current.account_id}"
  delivery_stream_name = "${local.name_prefix}-stream"
  log_group_name       = "/aws/kinesisfirehose/${local.name_prefix}"

  common_tags = merge(
    {
      Component   = "firehose-os"
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "firehose_os_private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a", Tier = "private" })
}

resource "aws_subnet" "firehose_os_private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b", Tier = "private" })
}

###############################################################################
# Security groups - the two groups reference each other, so the cross-referencing
# rules are declared as standalone rule resources to avoid a dependency cycle.
###############################################################################

resource "aws_security_group" "opensearch" {
  name        = "${local.name_prefix}-opensearch-sg"
  description = "OpenSearch domain nodes; accepts HTTPS only from Firehose ENIs"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-opensearch-sg" })
}

resource "aws_security_group" "firehose" {
  name        = "${local.name_prefix}-firehose-sg"
  description = "Firehose VPC ENIs; no ingress, egress limited to HTTPS toward OpenSearch"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-firehose-sg" })
}

# Inbound TCP 443 to OpenSearch is allowed ONLY from the Firehose security group
# (security-group-to-security-group reference; no CIDR ingress anywhere).
resource "aws_vpc_security_group_ingress_rule" "opensearch_from_firehose" {
  security_group_id            = aws_security_group.opensearch.id
  referenced_security_group_id = aws_security_group.firehose.id
  description                  = "HTTPS from Firehose delivery ENIs"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

# Firehose ENIs may only send TCP 443 to the OpenSearch security group.
resource "aws_vpc_security_group_egress_rule" "firehose_to_opensearch" {
  security_group_id            = aws_security_group.firehose.id
  referenced_security_group_id = aws_security_group.opensearch.id
  description                  = "HTTPS to OpenSearch domain nodes"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

# OpenSearch nodes require unrestricted egress for inter-node and AWS service traffic.
resource "aws_vpc_security_group_egress_rule" "opensearch_all" {
  security_group_id = aws_security_group.opensearch.id
  cidr_ipv4         = "0.0.0.0/0"
  description       = "Allow all egress from OpenSearch nodes"
  ip_protocol       = "-1"
  from_port         = 0
  to_port           = 0
}

###############################################################################
# KMS key for OpenSearch encryption at rest
###############################################################################

resource "aws_kms_key" "firehose_os" {
  description             = "Encryption at rest for the ${local.name_prefix} OpenSearch domain"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-opensearch-kms" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "firehose_os" {
  name          = "alias/${local.name_prefix}-opensearch"
  target_key_id = aws_kms_key.firehose_os.key_id
}

###############################################################################
# S3 backup bucket for Firehose backup / failed documents
###############################################################################

resource "aws_s3_bucket" "firehose_os_backup" {
  bucket = local.backup_bucket_name

  tags = merge(local.common_tags, { Name = local.backup_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_os_backup" {
  bucket = aws_s3_bucket.firehose_os_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_os_backup" {
  bucket = aws_s3_bucket.firehose_os_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_os_backup" {
  bucket = aws_s3_bucket.firehose_os_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# CloudWatch log group for Firehose delivery error logging
###############################################################################

resource "aws_cloudwatch_log_group" "firehose_os_delivery" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = local.log_group_name })
}

###############################################################################
# IAM role assumed by Firehose, with least-privilege inline policies
###############################################################################

data "aws_iam_policy_document" "firehose_os_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose" {
  name               = "${local.name_prefix}-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_os_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-delivery-role" })
}

resource "aws_iam_role_policy" "firehose_os_opensearch_access" {
  name = "opensearch-http-access"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["es:ESHttp*"]
        Resource = [
          aws_opensearch_domain.firehose_os.arn,
          "${aws_opensearch_domain.firehose_os.arn}/*",
        ]
      },
    ]
  })
}

# These EC2 actions do not support resource-level permissions.
resource "aws_iam_role_policy" "firehose_os_vpc_eni" {
  name = "vpc-network-interface-management"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy" "firehose_os_s3_backup" {
  name = "s3-backup-access"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:AbortMultipartUpload", "s3:GetObject"]
        Resource = [
          aws_s3_bucket.firehose_os_backup.arn,
          "${aws_s3_bucket.firehose_os_backup.arn}/*",
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy" "firehose_os_cloudwatch_logs" {
  name = "cloudwatch-delivery-logs"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          aws_cloudwatch_log_group.firehose_os_delivery.arn,
          "${aws_cloudwatch_log_group.firehose_os_delivery.arn}:*",
        ]
      },
    ]
  })
}

###############################################################################
# OpenSearch domain inside the VPC
###############################################################################

resource "aws_opensearch_domain" "firehose_os" {
  domain_name    = local.name_prefix
  engine_version = "OpenSearch_2.11"

  cluster_config {
    instance_type          = "t3.small.search"
    instance_count         = 2
    zone_awareness_enabled = true
  }

  vpc_options {
    subnet_ids         = [aws_subnet.firehose_os_private_a.id, aws_subnet.firehose_os_private_b.id]
    security_group_ids = [aws_security_group.opensearch.id]
  }

  encrypt_at_rest {
    enabled    = true
    kms_key_id = aws_kms_key.firehose_os.arn
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  # Fine-grained access control: the Firehose delivery role is the master user,
  # so no plaintext master password or out-of-band backend-role mapping is needed.
  advanced_security_options {
    enabled                        = true
    internal_user_database_enabled = false

    master_user_options {
      master_user_arn = aws_iam_role.firehose.arn
    }
  }

  tags = merge(local.common_tags, { Name = local.name_prefix })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Domain access policy: grants ONLY the Firehose role ESHttpPost/ESHttpPut
###############################################################################

resource "aws_opensearch_domain_policy" "firehose_os_access" {
  domain_name = aws_opensearch_domain.firehose_os.domain_name

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose.arn
        }
        Action   = ["es:ESHttpPost", "es:ESHttpPut"]
        Resource = [
          aws_opensearch_domain.firehose_os.arn,
          "${aws_opensearch_domain.firehose_os.arn}/*",
        ]
      },
    ]
  })
}

###############################################################################
# Kinesis Firehose delivery stream with OpenSearch (VPC) destination
###############################################################################

# A stream with no kinesis_source_configuration block is a DirectPut stream.
resource "aws_kinesis_firehose_delivery_stream" "firehose_os" {
  name        = local.delivery_stream_name
  destination = "opensearch"

  opensearch_configuration {
    domain_arn            = aws_opensearch_domain.firehose_os.arn
    role_arn              = aws_iam_role.firehose.arn
    index_name            = local.opensearch_index
    index_rotation_period = "OneDay"
    s3_backup_mode        = "FailedDocumentsOnly"
    buffering_size        = 5
    buffering_interval    = 300
    retry_duration        = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_os_delivery.name
      log_stream_name = "OpenSearch-Delivery"
    }

    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.firehose_os_backup.arn
      prefix              = "backup/"
      error_output_prefix = "errors/!{firehose:error-output-type}/"
      buffering_size      = 5
      buffering_interval  = 300
      compression_format  = "GZIP"

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose_os_delivery.name
        log_stream_name = "S3-Backup-Delivery"
      }
    }
  }

  tags = merge(local.common_tags, { Name = local.delivery_stream_name })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "opensearch_domain_endpoint" {
  description = "OpenSearch domain endpoint (VPC-internal)."
  value       = aws_opensearch_domain.firehose_os.endpoint
}

output "opensearch_domain_arn" {
  description = "ARN of the OpenSearch domain."
  value       = aws_opensearch_domain.firehose_os.arn
}

output "delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.firehose_os.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.firehose_os.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "application_name" {
  description = "Name of the Kinesis Data Analytics application; also used as the name prefix for related resources."
  type        = string
  default     = "basic-kinesis-analytics"
}

variable "shard_count" {
  description = "Number of provisioned shards for each Kinesis data stream."
  type        = number
  default     = 1
}

variable "environment" {
  description = "Environment name applied to the Environment tag on every resource."
  type        = string
  default     = "dev"
}

variable "additional_tags" {
  description = "Additional tags applied to every tagged resource."
  type        = map(string)
  default     = {}
}

locals {
  source_stream_name      = "${var.application_name}-source-stream"
  destination_stream_name = "${var.application_name}-destination-stream"
  log_group_name          = "/aws/kinesis-analytics/${var.application_name}"
  log_stream_name         = "${var.application_name}-application-logs"
  role_name               = "${var.application_name}-app-role"
  role_policy_name        = "${var.application_name}-app-policy"

  common_tags = merge(
    var.additional_tags,
    {
      Application = var.application_name
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  )
}

resource "aws_kinesis_stream" "source" {
  name             = local.source_stream_name
  shard_count      = var.shard_count
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kinesis_stream" "destination" {
  name             = local.destination_stream_name
  shard_count      = var.shard_count
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

resource "aws_iam_role" "kinesis_analytics_app" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKinesisAnalyticsAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kinesis_analytics_app" {
  name = local.role_policy_name
  role = aws_iam_role.kinesis_analytics_app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadFromSourceStream"
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:GetShardIterator",
          "kinesis:GetRecords",
          "kinesis:ListShards"
        ]
        Resource = aws_kinesis_stream.source.arn
      },
      {
        Sid    = "WriteToDestinationStream"
        Effect = "Allow"
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecordBatch"
        ]
        Resource = aws_kinesis_stream.destination.arn
      },
      {
        Sid    = "WriteApplicationLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.kinesis_analytics.arn,
          aws_cloudwatch_log_stream.kinesis_analytics.arn
        ]
      },
      {
        Sid      = "PublishApplicationMetrics"
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kinesis_analytics_application" "basic_app" {
  name        = var.application_name
  description = "Basic SQL application forwarding records from the source stream to the destination stream."

  code = <<-SQL
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (
      "event_id"   VARCHAR(64),
      "event_type" VARCHAR(64),
      "payload"    VARCHAR(2048)
    );

    CREATE OR REPLACE PUMP "FORWARD_PUMP" AS
      INSERT INTO "DESTINATION_SQL_STREAM"
      SELECT STREAM "event_id", "event_type", "payload"
      FROM "SOURCE_SQL_STREAM_001";
  SQL

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics_app.arn
  }

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    parallelism {
      count = 1
    }

    kinesis_stream {
      resource_arn = aws_kinesis_stream.source.arn
      role_arn     = aws_iam_role.kinesis_analytics_app.arn
    }

    schema {
      record_encoding = "UTF-8"

      record_columns {
        name     = "event_id"
        mapping  = "$.event_id"
        sql_type = "VARCHAR(64)"
      }

      record_columns {
        name     = "event_type"
        mapping  = "$.event_type"
        sql_type = "VARCHAR(64)"
      }

      record_columns {
        name     = "payload"
        mapping  = "$.payload"
        sql_type = "VARCHAR(2048)"
      }

      record_format {
        record_format_type = "JSON"

        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }
    }
  }

  outputs {
    name = "DESTINATION_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.destination.arn
      role_arn     = aws_iam_role.kinesis_analytics_app.arn
    }

    schema {
      record_format_type = "JSON"
    }
  }

  start_application = true

  tags = local.common_tags

  depends_on = [aws_iam_role_policy.kinesis_analytics_app]

  lifecycle {
    prevent_destroy = true
  }
}

output "application_arn" {
  description = "ARN of the Kinesis Data Analytics application."
  value       = aws_kinesis_analytics_application.basic_app.arn
}

output "application_name" {
  description = "Name of the Kinesis Data Analytics application."
  value       = aws_kinesis_analytics_application.basic_app.name
}

output "source_stream_name" {
  description = "Name of the source Kinesis data stream consumed by the application."
  value       = aws_kinesis_stream.source.name
}

output "source_stream_arn" {
  description = "ARN of the source Kinesis data stream consumed by the application."
  value       = aws_kinesis_stream.source.arn
}

output "destination_stream_name" {
  description = "Name of the destination Kinesis data stream written to by the application."
  value       = aws_kinesis_stream.destination.name
}

output "destination_stream_arn" {
  description = "ARN of the destination Kinesis data stream written to by the application."
  value       = aws_kinesis_stream.destination.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  kendra_logs_arn_prefix = "arn:aws:logs:*:*:log-group:/aws/kendra*"
}

variable "seed_urls" {
  description = "Seed URLs where the Kendra web crawler starts crawling."
  type        = list(string)
  default     = ["https://docs.aws.amazon.com/kendra/"]

  validation {
    condition     = length(var.seed_urls) > 0
    error_message = "At least one seed URL must be provided."
  }
}

variable "web_crawler_mode" {
  description = "Scope of the web crawl. One of HOST_ONLY, SUBDOMAINS, or EVERYTHING."
  type        = string
  default     = "SUBDOMAINS"

  validation {
    condition     = contains(["HOST_ONLY", "SUBDOMAINS", "EVERYTHING"], var.web_crawler_mode)
    error_message = "web_crawler_mode must be one of: HOST_ONLY, SUBDOMAINS, EVERYTHING."
  }
}

variable "url_inclusion_patterns" {
  description = "Regular expressions restricting the crawl to desired content paths."
  type        = list(string)
  default     = ["^https://docs\\.aws\\.amazon\\.com/kendra/.*"]

  validation {
    condition     = length(var.url_inclusion_patterns) > 0
    error_message = "At least one URL inclusion pattern must be provided."
  }
}

variable "url_exclusion_patterns" {
  description = "Regular expressions excluding binary and static assets from the crawl."
  type        = list(string)
  default     = ["\\.(jpg|jpeg|png|gif|css|js|zip|mp4|pdf)$"]

  validation {
    condition     = length(var.url_exclusion_patterns) > 0
    error_message = "At least one URL exclusion pattern must be provided."
  }
}

variable "default_tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project     = "kendra-web-crawler"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "kendra" {
  description             = "Customer managed key encrypting the Amazon Kendra index at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = var.default_tags
}

resource "aws_iam_role" "kendra_index_role" {
  name        = "kendra-index-role"
  description = "Role assumed by Amazon Kendra to create and operate the index"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.default_tags
}

resource "aws_iam_role_policy" "kendra_index_policy" {
  name = "kendra-index-policy"
  role = aws_iam_role.kendra_index_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "KendraCloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid    = "KendraCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = local.kendra_logs_arn_prefix
      },
      {
        Sid    = "KendraKmsKey"
        Effect = "Allow"
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = aws_kms_key.kendra.arn
      }
    ]
  })
}

resource "aws_kendra_index" "kendra_index" {
  name        = "kendra_web_index"
  edition     = "DEVELOPER_EDITION"
  role_arn    = aws_iam_role.kendra_index_role.arn
  description = "Amazon Kendra index encrypted with a customer managed KMS key"

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra.arn
  }

  tags = var.default_tags

  depends_on = [aws_iam_role_policy.kendra_index_policy]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "kendra_data_source_role" {
  name        = "kendra-web-crawler-role"
  description = "Role assumed by Amazon Kendra for the WEBCRAWLER data source"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.default_tags
}

resource "aws_iam_role_policy" "kendra_data_source_policy" {
  name = "kendra-web-crawler-policy"
  role = aws_iam_role.kendra_data_source_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "KendraWebCrawlerCloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid    = "KendraWebCrawlerCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = local.kendra_logs_arn_prefix
      }
    ]
  })
}

resource "aws_kendra_data_source" "web_crawler" {
  index_id      = aws_kendra_index.kendra_index.id
  name          = "web_crawler"
  type          = "WEBCRAWLER"
  role_arn      = aws_iam_role.kendra_data_source_role.arn
  description   = "Web crawler data source with URL inclusion and exclusion patterns"
  language_code = "en"
  tags          = var.default_tags

  configuration {
    web_crawler_configuration {
      url_inclusion_patterns = var.url_inclusion_patterns
      url_exclusion_patterns = var.url_exclusion_patterns

      crawl_depth                    = 2
      max_links_per_page             = 50
      max_urls_per_minute_crawl_rate = 30

      urls {
        seed_url_configuration {
          seed_urls        = var.seed_urls
          web_crawler_mode = var.web_crawler_mode
        }
      }
    }
  }

  depends_on = [aws_iam_role_policy.kendra_data_source_policy]

  lifecycle {
    prevent_destroy = true
  }
}

output "kendra_index_id" {
  description = "Identifier of the Amazon Kendra index."
  value       = aws_kendra_index.kendra_index.id
}

output "kendra_data_source_id" {
  description = "Identifier of the Kendra WEBCRAWLER data source."
  value       = aws_kendra_data_source.web_crawler.data_source_id
}

output "kendra_data_source_arn" {
  description = "ARN of the Kendra WEBCRAWLER data source."
  value       = aws_kendra_data_source.web_crawler.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag value applied to Route 53 resources."
  type        = string
  default     = "production"
}

variable "target_ipv4" {
  description = "IPv4 address the www A record points to (documentation IP by default)."
  type        = string
  default     = "203.0.113.10"

  validation {
    condition     = can(cidrnetmask("${var.target_ipv4}/32"))
    error_message = "target_ipv4 must be a valid IPv4 address."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_route53_zone" "example53_com" {
  name = "example53.com"

  tags = merge(
    local.common_tags,
    {
      Name = "example53.com"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "example_record" {
  zone_id = aws_route53_zone.example53_com.zone_id
  name    = "www.${aws_route53_zone.example53_com.name}"
  type    = "A"
  ttl     = 300
  records = [var.target_ipv4]
}

output "zone_name_servers" {
  description = "Name servers to configure at the registrar to delegate example53.com to this hosted zone."
  value       = aws_route53_zone.example53_com.name_servers
}

output "zone_id" {
  description = "ID of the example53.com hosted zone."
  value       = aws_route53_zone.example53_com.zone_id
}

output "record_fqdn" {
  description = "Fully qualified domain name of the www A record."
  value       = aws_route53_record.example_record.fqdn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name   = "foobar"
  region = "us-east-1"

  common_tags = {
    Name      = local.name
    ManagedBy = "terraform"
  }
}

resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = local.name
  alarm_description   = "Average EC2 CPU utilization at or above threshold"
  namespace           = "AWS/EC2"
  metric_name         = "CPUUtilization"
  statistic           = "Average"
  period              = 120
  evaluation_periods  = 2
  threshold           = 80
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "missing"

  tags = local.common_tags
}

resource "aws_route53_health_check" "foobar" {
  type = "CLOUDWATCH_METRIC"

  cloudwatch_alarm_name           = aws_cloudwatch_metric_alarm.foobar.alarm_name
  cloudwatch_alarm_region         = local.region
  insufficient_data_health_status = "Healthy"

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster and base name for all related resources"
  type        = string
  default     = "greenfield-eks-cluster"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Name        = var.cluster_name
    Environment = "greenfield"
    ManagedBy   = "terraform"
  }

  eks_subnet_tags = {
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    local.eks_subnet_tags,
    {
      Name = "${var.cluster_name}-public-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_iam_role" "eks_cluster" {
  name = "${var.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-cluster-role"
    }
  )
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    endpoint_public_access  = true
    endpoint_private_access = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_service_policy,
  ]

  provisioner "local-exec" {
    command = "aws eks update-kubeconfig --region us-east-1 --name ${var.cluster_name}"
  }

  provisioner "local-exec" {
    when = destroy
    command = <<-EOT
      kubectl config delete-cluster ${self.name} || true
      kubectl config delete-context ${self.name} || true
    EOT
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.cluster_name
    }
  )
}

output "cluster_name" {
  description = "Name of the EKS cluster"
  value       = aws_eks_cluster.main.name
}

output "cluster_endpoint" {
  description = "API server endpoint of the EKS cluster"
  value       = aws_eks_cluster.main.endpoint
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Default tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "example"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  name = "example"
  tags = merge(var.tags, { Name = local.name })
}

# -----------------------------------------------------------------------------
# Networking prerequisites
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name}-vpc" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name                                  = "${local.name}-public-a"
    "kubernetes.io/role/elb"              = "1"
    "kubernetes.io/cluster/${local.name}" = "shared"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name                                  = "${local.name}-public-b"
    "kubernetes.io/role/elb"              = "1"
    "kubernetes.io/cluster/${local.name}" = "shared"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name}-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.name}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EKS cluster control plane role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster" {
  name = "${local.name}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.tags, { Name = "${local.name}-eks-cluster-role" })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

# -----------------------------------------------------------------------------
# KMS key for Kubernetes secrets envelope encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "eks_secrets" {
  description             = "CMK used for EKS Kubernetes secrets envelope encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${local.name}-eks-secrets-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "eks_cluster_kms_secrets" {
  name = "${local.name}-eks-cluster-kms-secrets"
  role = aws_iam_role.eks_cluster.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EKSSecretsEnvelopeEncryption"
        Effect = "Allow"
        Action = [
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:ReEncrypt*"
        ]
        Resource = aws_kms_key.eks_secrets.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM: Access entry principal role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "access_entry_principal" {
  name = "${local.name}-access-entry-principal"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.tags, { Name = "${local.name}-access-entry-principal" })
}

# -----------------------------------------------------------------------------
# EKS cluster
# -----------------------------------------------------------------------------

resource "aws_eks_cluster" "example" {
  name     = local.name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = [aws_subnet.public_a.id, aws_subnet.public_b.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks_secrets.arn
    }
  }

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  tags = local.tags

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy.eks_cluster_kms_secrets
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# EKS access entry
# -----------------------------------------------------------------------------

resource "aws_eks_access_entry" "example" {
  cluster_name      = aws_eks_cluster.example.name
  principal_arn     = aws_iam_role.access_entry_principal.arn
  type              = "STANDARD"
  kubernetes_groups = ["platform-admins", "engineering"]

  tags = local.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Networking foundation (greenfield)
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name                            = "example-vpc"
    "kubernetes.io/cluster/example" = "shared"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name                            = "example-public-${count.index}"
    "kubernetes.io/cluster/example" = "shared"
    "kubernetes.io/role/elb"        = "1"
  }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 100)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "example-private-${count.index}"
    "kubernetes.io/cluster/example"   = "shared"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"

  tags = {
    Name = "example-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 2
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "example-nat-${count.index}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-public-rt"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-private-rt-${count.index}"
  }
}

resource "aws_route" "private_nat" {
  count                  = 2
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# EKS cluster IAM role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cluster" {
  name               = "example-eks-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = {
    Name = "example-eks-cluster-role"
  }
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "cluster_vpc_resource_controller" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

# ---------------------------------------------------------------------------
# Fargate pod execution IAM role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "fargate_pod_execution_assume_role" {
  statement {
    sid     = "FargatePodExecutionAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks-fargate-pods.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "example" {
  name               = "example"
  assume_role_policy = data.aws_iam_policy_document.fargate_pod_execution_assume_role.json

  tags = {
    Name = "example"
  }
}

resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
}

# ---------------------------------------------------------------------------
# EKS cluster
# ---------------------------------------------------------------------------

resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids              = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.cluster_vpc_resource_controller,
  ]

  tags = {
    Name                            = "example"
    "kubernetes.io/cluster/example" = "shared"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# EKS Fargate profile
# ---------------------------------------------------------------------------

resource "aws_eks_fargate_profile" "example" {
  cluster_name           = aws_eks_cluster.example.name
  fargate_profile_name   = "example"
  pod_execution_role_arn = aws_iam_role.example.arn
  subnet_ids             = aws_subnet.private[*].id

  selector {
    namespace = "example"
  }

  depends_on = [
    aws_iam_role_policy_attachment.example,
  ]

  tags = {
    Name = "example"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "pod_identity_namespace" {
  description = "Kubernetes namespace targeted by the EKS Pod Identity association."
  type        = string
  default     = "example-namespace"
}

variable "pod_identity_service_account" {
  description = "Kubernetes service account targeted by the EKS Pod Identity association."
  type        = string
  default     = "example-service-account"
}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name = "example"
  tags = {
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# IAM: EKS Pod Identity trust policy, scoped to the current AWS account
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "example" {
  statement {
    sid    = "AllowEKSPodIdentityAssumeRole"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
      "sts:TagSession",
    ]

    principals {
      type        = "Service"
      identifiers = ["pods.eks.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "example" {
  name               = local.name
  assume_role_policy = data.aws_iam_policy_document.example.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

# ---------------------------------------------------------------------------
# IAM: EKS cluster execution role
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "AllowEKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "example-eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# ---------------------------------------------------------------------------
# Network: VPC, internet gateway, public route table, and two AZ subnets
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "example-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "example-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "example-public-rt" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.tags, { Name = "example-public-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.tags, { Name = "example-public-b" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# CloudWatch log group for the EKS control plane (created before the cluster
# so the control plane never auto-creates a never-expiring log group)
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "example" {
  name              = "/aws/eks/${local.name}/cluster"
  retention_in_days = 7

  tags = merge(local.tags, { Name = "example-eks-cluster-logs" })
}

# ---------------------------------------------------------------------------
# EKS cluster
# ---------------------------------------------------------------------------
resource "aws_eks_cluster" "example" {
  name     = local.name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = [aws_subnet.public_a.id, aws_subnet.public_b.id]
    endpoint_private_access = false
    endpoint_public_access  = true
  }

  enabled_cluster_log_types = ["api", "audit"]

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster,
    aws_cloudwatch_log_group.example,
    aws_route_table_association.public_a,
    aws_route_table_association.public_b,
  ]

  lifecycle {
    prevent_destroy = true
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------
# EKS Pod Identity Agent add-on (required for Pod Identity to function)
# ---------------------------------------------------------------------------
resource "aws_eks_addon" "pod_identity_agent" {
  cluster_name = aws_eks_cluster.example.name
  addon_name   = "eks-pod-identity-agent"

  tags = local.tags
}

# ---------------------------------------------------------------------------
# EKS Pod Identity association: binds the IAM role to a namespace/service account
# ---------------------------------------------------------------------------
resource "aws_eks_pod_identity_association" "example" {
  cluster_name    = aws_eks_cluster.example.name
  namespace       = var.pod_identity_namespace
  service_account = var.pod_identity_service_account
  role_arn        = aws_iam_role.example.arn

  tags = local.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "eks-cluster"
}

variable "kubernetes_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = "1.30"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }

  cluster_subnet_tags = {
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-vpc"
    }
  )
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    local.cluster_subnet_tags,
    {
      Name = "${var.cluster_name}-subnet-a"
    }
  )
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    local.cluster_subnet_tags,
    {
      Name = "${var.cluster_name}-subnet-b"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "subnet_b" {
  subnet_id      = aws_subnet.subnet_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "eks-cluster"
    }
  )
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.cluster_name
  version  = var.kubernetes_version
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
    endpoint_private_access = false
    endpoint_public_access  = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]

  tags = merge(
    local.common_tags,
    {
      Name = var.cluster_name
    }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "sample" {
  bucket = "sample"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "sample" {
  bucket                = aws_s3_bucket.sample.id
  expected_bucket_owner = data.aws_caller_identity.current.account_id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "sample" {
  bucket = aws_s3_bucket.sample.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sample" {
  bucket                = aws_s3_bucket.sample.id
  expected_bucket_owner = data.aws_caller_identity.current.account_id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "sample" {
  bucket = aws_s3_bucket.sample.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "example_bucket" {
  bucket              = "example-bucket"
  object_lock_enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "example_bucket" {
  bucket = aws_s3_bucket.example_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_object_lock_configuration" "example_bucket" {
  bucket = aws_s3_bucket.example_bucket.id

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = 90
    }
  }

  depends_on = [aws_s3_bucket_versioning.example_bucket]
}

resource "aws_s3_bucket_public_access_block" "example_bucket" {
  bucket = aws_s3_bucket.example_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "example_bucket" {
  bucket = aws_s3_bucket.example_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_suffix" {
  description = "Suffix used to construct unique, S3-compliant bucket names."
  type        = string
  default     = "test"
}

variable "order_data_source_path" {
  description = "Local file path of the order_data2.csv file to upload to the web data bucket."
  type        = string
  default     = "./order_data2.csv"
}

locals {
  cloudgoat_data_bucket_name = "cloudgoat-data-${var.bucket_suffix}"
  web_data_bucket_name       = "web-data-${var.bucket_suffix}"
}

# ------------------------------------------------------------------------------
# CloudGoat data storage bucket (private)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "cloudgoat_data" {
  bucket = local.cloudgoat_data_bucket_name

  tags = {
    Name = local.cloudgoat_data_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "cloudgoat_data" {
  bucket = aws_s3_bucket.cloudgoat_data.id

  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket_acl" "cloudgoat_data" {
  bucket = aws_s3_bucket.cloudgoat_data.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.cloudgoat_data]
}

resource "aws_s3_bucket_public_access_block" "cloudgoat_data" {
  bucket = aws_s3_bucket.cloudgoat_data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudgoat_data" {
  bucket = aws_s3_bucket.cloudgoat_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudgoat_data" {
  bucket = aws_s3_bucket.cloudgoat_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Web data storage bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "web_data" {
  bucket = local.web_data_bucket_name

  tags = {
    Name = local.web_data_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "web_data" {
  bucket = aws_s3_bucket.web_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "web_data" {
  bucket = aws_s3_bucket.web_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "order_data" {
  bucket       = aws_s3_bucket.web_data.id
  key          = "order_data2.csv"
  source       = var.order_data_source_path
  content_type = "text/csv"
}

# block_public_policy is intentionally false so the public PutObject bucket
# policy below can be attached without an apply-time failure.
resource "aws_s3_bucket_public_access_block" "web_data" {
  bucket = aws_s3_bucket.web_data.id

  block_public_acls       = true
  block_public_policy     = false
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "web_data" {
  bucket = aws_s3_bucket.web_data.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowPublicPutObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.web_data.arn}/*"
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.web_data]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name. The AWS account ID is appended to guarantee a globally unique bucket name so terraform apply runs unattended."
  type        = string
  default     = "terraform-s3-kms-sse-encrypted-bucket"
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name = "${var.bucket_name_prefix}-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    ManagedBy   = "terraform"
    Project     = "s3-kms-server-side-encryption"
    Environment = "production"
  }
}

# KMS key used for S3 server-side encryption
resource "aws_kms_key" "s3_bucket_encryption_key" {
  description             = "S3 bucket server-side encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(
    local.common_tags,
    {
      Name = "s3-bucket-server-side-encryption-key"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Friendly alias for the KMS key
resource "aws_kms_alias" "s3_bucket_encryption_key" {
  name          = "alias/s3-bucket-server-side-encryption-key"
  target_key_id = aws_kms_key.s3_bucket_encryption_key.key_id
}

# S3 bucket protected by the KMS key
resource "aws_s3_bucket" "encrypted_bucket" {
  bucket = local.bucket_name

  tags = merge(
    local.common_tags,
    {
      Name = local.bucket_name
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Disable ACLs in favor of object ownership enforcement
resource "aws_s3_bucket_ownership_controls" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Enable versioning for the stateful bucket
resource "aws_s3_bucket_versioning" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption using the KMS key with the aws:kms algorithm
resource "aws_s3_bucket_server_side_encryption_configuration" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_bucket_encryption_key.arn
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Globally unique name of the S3 bucket to create."
  type        = string
  default     = "my-app-bucket"
}

resource "aws_s3_bucket" "main" {
  bucket = var.bucket_name

  tags = {
    Name        = var.bucket_name
    ManagedBy   = "terraform"
    Environment = "production"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

output "bucket_id" {
  description = "The ID (name) of the created S3 bucket."
  value       = aws_s3_bucket.main.id
}

output "bucket_arn" {
  description = "The ARN of the created S3 bucket."
  value       = aws_s3_bucket.main.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "management_cidr" {
  description = "CIDR block permitted to reach the instances over SSH (TCP 22)"
  type        = string
  default     = "10.0.0.0/8"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "selected" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  name_prefix = "custom-vpc"
  environment = "dev"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ssh" {
  name        = "${local.name_prefix}-ssh-sg"
  description = "Allow inbound SSH from the management CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from management CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.management_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssh-sg"
  })
}

resource "aws_instance" "app_a" {
  ami                         = data.aws_ami.selected.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_a.id
  vpc_security_group_ids      = [aws_security_group.ssh.id]
  associate_public_ip_address = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-a"
  })
}

resource "aws_instance" "app_b" {
  ami                         = data.aws_ami.selected.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_b.id
  vpc_security_group_ids      = [aws_security_group.ssh.id]
  associate_public_ip_address = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-b"
  })
}

resource "aws_ebs_volume" "data_a" {
  availability_zone = aws_subnet.public_a.availability_zone
  size              = 50
  type              = "gp3"
  encrypted         = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-data-a"
  })
}

resource "aws_ebs_volume" "data_b" {
  availability_zone = aws_subnet.public_b.availability_zone
  size              = 50
  type              = "gp3"
  encrypted         = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-data-b"
  })
}

resource "aws_volume_attachment" "data_a" {
  device_name = "/dev/sdf"
  volume_id   = aws_ebs_volume.data_a.id
  instance_id = aws_instance.app_a.id
}

resource "aws_volume_attachment" "data_b" {
  device_name = "/dev/sdf"
  volume_id   = aws_ebs_volume.data_b.id
  instance_id = aws_instance.app_b.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_type" {
  description = "EC2 instance type for the cluster nodes (must support cluster placement groups)."
  type        = string
  default     = "c5.large"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  name_prefix = "cluster_workload"

  public_subnet_cidrs  = [cidrsubnet(var.vpc_cidr, 8, 1), cidrsubnet(var.vpc_cidr, 8, 2)]
  private_subnet_cidrs = [cidrsubnet(var.vpc_cidr, 8, 101), cidrsubnet(var.vpc_cidr, 8, 102)]

  common_tags = {
    Project   = local.name_prefix
    ManagedBy = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_public_subnet_${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_subnet_${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_nat_eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_nat_gateway"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_public_route_table"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_route_table"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_placement_group" "cluster" {
  name     = "${local.name_prefix}_placement_group"
  strategy = "cluster"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_placement_group"
  })
}

resource "aws_security_group" "cluster_nodes" {
  name        = "${local.name_prefix}_cluster_nodes_sg"
  description = "Security group for clustered EC2 nodes: HTTP/HTTPS from anywhere, unrestricted intra-cluster traffic."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_cluster_nodes_sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.cluster_nodes.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.cluster_nodes.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

resource "aws_vpc_security_group_ingress_rule" "cluster_internal" {
  security_group_id            = aws_security_group.cluster_nodes.id
  referenced_security_group_id = aws_security_group.cluster_nodes.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_egress_rule" "allow_all_egress" {
  security_group_id = aws_security_group.cluster_nodes.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

resource "aws_instance" "cluster_node" {
  count = 3

  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public[0].id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.cluster_nodes.id]
  placement_group             = aws_placement_group.cluster.id
  monitoring                  = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted             = true
    volume_size           = 20
    volume_type           = "gp3"
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name    = "${local.name_prefix}_cluster_node_${count.index + 1}"
    Cluster = local.name_prefix
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)

  default = {
    Project     = "elasticache-iam-auth"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  elasticache_user_id       = "app_cache_iam_user"
  elasticache_user_name     = "app_cache_iam_user"
  cache_client_role_name    = "elasticache-iam-auth-client"
  cache_connect_policy_name = "elasticache-connect-app-cache-user"
}

# ------------------------------------------------------------------------------
# ElastiCache user authenticated via IAM (SigV4), no password material managed.
# Descriptive context is carried via tags because aws_elasticache_user has no
# description argument in the provider schema.
# ------------------------------------------------------------------------------
resource "aws_elasticache_user" "app_cache" {
  user_id       = local.elasticache_user_id
  user_name     = local.elasticache_user_name
  engine        = "redis"
  access_string = "on ~app:* -@all +@read +@write +@slow"

  authentication_mode {
    type = "iam"
  }

  tags = merge(
    var.common_tags,
    {
      Description = "Application cache user authenticated via IAM (SigV4)"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM role assumed by client workloads (EC2 service principal only)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "cache_client_trust" {
  statement {
    sid    = "AllowEC2ToAssumeCacheClientRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cache_client" {
  name               = local.cache_client_role_name
  description        = "Role assumed by client workloads to connect to ElastiCache with IAM authentication."
  assume_role_policy = data.aws_iam_policy_document.cache_client_trust.json

  tags = var.common_tags
}

# ------------------------------------------------------------------------------
# IAM policy granting only elasticache:Connect on the ElastiCache user ARN
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "cache_connect" {
  statement {
    sid       = "AllowElastiCacheConnect"
    effect    = "Allow"
    actions   = ["elasticache:Connect"]
    resources = [aws_elasticache_user.app_cache.arn]
  }
}

resource "aws_iam_policy" "cache_connect" {
  name        = local.cache_connect_policy_name
  description = "Permits elasticache:Connect only against the application ElastiCache user."
  policy      = data.aws_iam_policy_document.cache_connect.json

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "cache_connect" {
  role       = aws_iam_role.cache_client.name
  policy_arn = aws_iam_policy.cache_connect.arn
}

# ------------------------------------------------------------------------------
# Outputs for client workloads
# ------------------------------------------------------------------------------
output "elasticache_user_id" {
  description = "ID of the ElastiCache user used for IAM-authenticated cache connections."
  value       = aws_elasticache_user.app_cache.id
}

output "elasticache_user_arn" {
  description = "ARN of the ElastiCache user."
  value       = aws_elasticache_user.app_cache.arn
}

output "cache_client_role_arn" {
  description = "ARN of the IAM role that client workloads assume for IAM-authenticated cache access."
  value       = aws_iam_role.cache_client.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  aws_region_name            = "us-east-1"
  master_username            = "redshiftadmin"
  data_bucket_name           = "redshift-analytics-data-${random_id.bucket_suffix.hex}"
  s3_gateway_service_name    = "com.amazonaws.${local.aws_region_name}.s3"
  kms_interface_service_name = "com.amazonaws.${local.aws_region_name}.kms"

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Project     = "redshift-analytics"
    },
    var.tags,
  )
}

# -----------------------------------------------------------------------------
# Network foundation (private-only: no internet gateway, no public subnets)
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "redshift-analytics-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "redshift-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "redshift-private-b" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "redshift-private-route-table" })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# VPC endpoints so the enhanced-vpc-routed cluster can reach S3 and KMS
# without any internet gateway.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = local.s3_gateway_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, { Name = "redshift-s3-gateway-endpoint" })
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "redshift-vpc-endpoints-sg"
  description = "Allow HTTPS from the VPC to interface VPC endpoints."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "redshift-vpc-endpoints-sg" })
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = local.kms_interface_service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "redshift-kms-interface-endpoint" })
}

# -----------------------------------------------------------------------------
# Cluster security group
# -----------------------------------------------------------------------------
resource "aws_security_group" "redshift" {
  name        = "redshift-analytics-cluster-sg"
  description = "Restrict access to the Redshift cluster to TCP 5439 from within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS egress for AWS service access through VPC endpoints"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "redshift-analytics-cluster-sg" })
}

# -----------------------------------------------------------------------------
# Master credentials (no plaintext values)
# -----------------------------------------------------------------------------
resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "redshift/${var.environment}/redshift-analytics-cluster/master"
  description = "Master credentials for the redshift-analytics-cluster Redshift cluster."

  tags = merge(local.common_tags, { Name = "redshift-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# S3 data bucket for COPY/UNLOAD
# -----------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "redshift_data" {
  bucket = local.data_bucket_name

  tags = merge(local.common_tags, { Name = local.data_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "redshift_data" {
  bucket                  = aws_s3_bucket.redshift_data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "redshift_data" {
  bucket = aws_s3_bucket.redshift_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "redshift_data" {
  bucket = aws_s3_bucket.redshift_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM role for the cluster (least-privilege read access to the data prefix)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "redshift_assume_role" {
  statement {
    sid     = "AllowRedshiftAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "redshift_s3_copy" {
  name               = "redshift-analytics-s3-copy-role"
  assume_role_policy = data.aws_iam_policy_document.redshift_assume_role.json

  tags = merge(local.common_tags, { Name = "redshift-analytics-s3-copy-role" })
}

data "aws_iam_policy_document" "redshift_s3_read" {
  statement {
    sid       = "ListDataPrefix"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.redshift_data.arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["data/*"]
    }
  }

  statement {
    sid       = "ReadDataObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.redshift_data.arn}/data/*"]
  }
}

resource "aws_iam_policy" "redshift_s3_read" {
  name        = "redshift-analytics-s3-read-policy"
  description = "Read-only access to the redshift data bucket prefix for COPY operations."
  policy      = data.aws_iam_policy_document.redshift_s3_read.json

  tags = merge(local.common_tags, { Name = "redshift-analytics-s3-read-policy" })
}

resource "aws_iam_role_policy_attachment" "redshift_s3_read" {
  role       = aws_iam_role.redshift_s3_copy.name
  policy_arn = aws_iam_policy.redshift_s3_read.arn
}

# -----------------------------------------------------------------------------
# Redshift subnet group and parameter group
# -----------------------------------------------------------------------------
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-analytics-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "redshift-analytics-subnet-group" })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "redshift-analytics-parameters"
  family = "redshift-2.0"

  parameter {
    name  = "ssl"
    value = "true"
  }

  tags = merge(local.common_tags, { Name = "redshift-analytics-parameters" })
}

# -----------------------------------------------------------------------------
# Single-node Redshift cluster
# -----------------------------------------------------------------------------
resource "aws_redshift_cluster" "main" {
  cluster_identifier = "redshift-analytics-cluster"
  database_name      = "analyticsdb"
  cluster_type       = "single-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 1
  port               = 5439

  master_username = jsondecode(aws_secretsmanager_secret_version.redshift_master.secret_string)["username"]
  master_password = jsondecode(aws_secretsmanager_secret_version.redshift_master.secret_string)["password"]

  encrypted            = true
  publicly_accessible  = false
  enhanced_vpc_routing = true

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  iam_roles                    = [aws_iam_role.redshift_s3_copy.arn]

  automated_snapshot_retention_period = 7

  skip_final_snapshot       = false
  final_snapshot_identifier = "redshift-analytics-cluster-final-snapshot"

  tags = merge(local.common_tags, { Name = "redshift-analytics-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "cluster_endpoint" {
  description = "Connection endpoint for the Redshift cluster."
  value       = aws_redshift_cluster.main.endpoint
}

output "cluster_database_name" {
  description = "Default database created on the Redshift cluster."
  value       = aws_redshift_cluster.main.database_name
}

output "data_bucket_name" {
  description = "S3 bucket used for Redshift COPY and UNLOAD data."
  value       = aws_s3_bucket.redshift_data.bucket
}

output "master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.redshift_master.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc"
    }
  )
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc-private-a"
    }
  )
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc-private-b"
    }
  )
}

resource "aws_redshift_subnet_group" "main" {
  name        = "main-redshift-subnet-group"
  description = "Redshift subnet group spanning two availability zones for high availability"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = "main-redshift-subnet-group"
    }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      ManagedBy = "terraform"
      Project   = "redshift-analytics"
    }
  }
}

# ------------------------------------------------------------------
# Networking (greenfield - created here, never looked up)
# ------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "redshift-main-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-private-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-private-b"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-main-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = {
    Name = "redshift-main-subnet-group"
  }
}

# ------------------------------------------------------------------
# Security group - ingress restricted to Redshift port from VPC CIDR only
# ------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "redshift-main-sg"
  description = "Restrict Redshift access to TCP 5439 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "redshift-main-sg"
  }
}

# ------------------------------------------------------------------
# Encryption - KMS key with rotation enabled
# ------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption and master credentials secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "redshift-main-kms"
  }
}

# ------------------------------------------------------------------
# Master credentials - generated, never plaintext in configuration
# ------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%^*()-_=+[]{}<>?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "redshift-main-master-credentials"
  description = "Master credentials for the redshift-main Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = {
    Name = "redshift-main-master-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = "redshift_admin"
    password = random_password.redshift_master.result
  })
}

# ------------------------------------------------------------------
# IAM role - trusts only the Redshift service principal
# ------------------------------------------------------------------

resource "aws_iam_role" "redshift_access" {
  name = "redshift-main-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRedshiftServiceToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "redshift-main-access-role"
  }
}

# ------------------------------------------------------------------
# Redshift cluster - private, encrypted, 2-node
# ------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "redshift-main"
  database_name      = "analytics"
  cluster_type       = "multi-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 2

  master_username = "redshift_admin"
  master_password = random_password.redshift_master.result

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]

  encrypted = true
  kms_key_id = aws_kms_key.redshift.arn

  publicly_accessible = false
  port                = 5439

  automated_snapshot_retention_period = 7

  skip_final_snapshot       = false
  final_snapshot_identifier = "redshift-main-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "redshift-main"
  }
}

# ------------------------------------------------------------------
# Resource policy - grants the IAM role explicit access to this cluster,
# scoped to the cluster's namespace ARN (computed attribute)
# ------------------------------------------------------------------

resource "aws_redshift_resource_policy" "main" {
  resource_arn = aws_redshift_cluster.main.cluster_namespace_arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGetClusterCredentialsFromAccessRole"
        Effect = "Allow"
        Principal = {
          AWS = [aws_iam_role.redshift_access.arn]
        }
        Action = [
          "redshift:GetClusterCredentials"
        ]
        Resource = [
          aws_redshift_cluster.main.cluster_namespace_arn
        ]
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "local_file" "lambda_handler" {
  filename = "${path.module}/lambda_function.py"
  content  = <<-EOF
    import json

    def lambda_handler(event, context):
        return {
            "statusCode": 200,
            "body": json.dumps({
                "message": "success",
                "input": event
            })
        }
    EOF
}

data "archive_file" "lambda_package" {
  type        = "zip"
  source_file = local_file.lambda_handler.filename
  output_path = "${path.module}/lambda_function_payload.zip"

  depends_on = [local_file.lambda_handler]
}

resource "aws_iam_role" "example_lambda_role" {
  name = "example_lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "example_lambda_logs" {
  name              = "/aws/lambda/example_lambda"
  retention_in_days = 14
}

resource "aws_iam_policy" "example_lambda_logging" {
  name        = "example_lambda_logging_policy"
  description = "Least-privilege CloudWatch Logs policy for the example_lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.example_lambda_logs.arn,
          "${aws_cloudwatch_log_group.example_lambda_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example_lambda_logging" {
  role       = aws_iam_role.example_lambda_role.name
  policy_arn = aws_iam_policy.example_lambda_logging.arn
}

resource "aws_lambda_function" "example_lambda" {
  function_name    = "example_lambda"
  filename         = data.archive_file.lambda_package.output_path
  source_code_hash = data.archive_file.lambda_package.output_base64sha256
  role             = aws_iam_role.example_lambda_role.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  memory_size      = 128
  timeout          = 10

  depends_on = [
    aws_iam_role_policy_attachment.example_lambda_logging,
    aws_cloudwatch_log_group.example_lambda_logs
  ]
}

resource "aws_lambda_invocation" "example_lambda_invoke" {
  function_name = aws_lambda_function.example_lambda.function_name

  input = jsonencode({
    key1 = "value1"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for resource tagging."
  type        = string
  default     = "scheduled-job"
}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  function_name = "scheduled-job"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Lambda source code: write the Python handler to disk, then package it as a zip
# -----------------------------------------------------------------------------

resource "local_file" "lambda_handler" {
  filename = "${path.module}/src/main.py"
  content = <<-EOT
    import json


    def lambda_handler(event, context):
        print("Scheduled job invoked with event: " + json.dumps(event))

        return {
            "statusCode": 200,
            "body": json.dumps({"message": "scheduled job executed successfully"}),
        }
  EOT
  file_permission = "0644"
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  source_dir  = "${path.module}/src"
  output_path = "${path.module}/scheduled_job.zip"

  depends_on = [local_file.lambda_handler]
}

# -----------------------------------------------------------------------------
# IAM execution role trusting only the Lambda service principal
# -----------------------------------------------------------------------------

resource "aws_iam_role" "lambda_exec" {
  name = "${local.function_name}-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Pre-provisioned CloudWatch log group with explicit retention (cost control)
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${local.function_name}"
  retention_in_days = 14

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Least-privilege inline logging policy scoped to the function's log group
# -----------------------------------------------------------------------------

resource "aws_iam_role_policy" "lambda_logs" {
  name = "${local.function_name}-logs"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          trimsuffix(aws_cloudwatch_log_group.lambda_logs.arn, ":*"),
          aws_cloudwatch_log_group.lambda_logs.arn,
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Lambda function
# -----------------------------------------------------------------------------

resource "aws_lambda_function" "scheduled_job" {
  function_name = local.function_name
  description   = "Job invoked by EventBridge every 15 minutes."

  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  runtime          = "python3.12"
  handler          = "main.lambda_handler"

  memory_size = 128
  timeout     = 30

  role = aws_iam_role.lambda_exec.arn

  tags = merge(local.common_tags, {
    Name = local.function_name
  })

  depends_on = [
    aws_cloudwatch_log_group.lambda_logs,
    aws_iam_role_policy.lambda_logs,
  ]
}

# -----------------------------------------------------------------------------
# EventBridge schedule: rate(15 minutes) -> Lambda target
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "every_15_minutes" {
  name                = "${local.function_name}-every-15-minutes"
  description         = "Invokes the ${local.function_name} Lambda every 15 minutes."
  schedule_expression = "rate(15 minutes)"

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "scheduled_job" {
  rule      = aws_cloudwatch_event_rule.every_15_minutes.name
  target_id = "${local.function_name}-target"
  arn       = aws_lambda_function.scheduled_job.arn

  depends_on = [aws_lambda_permission.allow_eventbridge]
}

resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.scheduled_job.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.every_15_minutes.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Single user-controlled input: project name prefix, used consistently for
# resource names, alarm names, and tags.
# ------------------------------------------------------------------------------

variable "project_name" {
  description = "Project name prefix applied to resource names, alarm names, and tags."
  type        = string
  default     = "app-prod"
}

locals {
  name_prefix      = var.project_name
  log_group_name   = "/${var.project_name}/application/logs"
  metric_namespace = "${var.project_name}/Application"

  common_tags = {
    Environment = var.project_name
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Current account ID - used only to delegate KMS key administration back to the
# account root principal (standard KMS practice; no hardcoded account IDs).
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Customer-managed KMS key for SNS server-side encryption.
# ------------------------------------------------------------------------------

resource "aws_kms_key" "alarm_notifications" {
  description             = "Customer-managed key for server-side encryption of the ${local.name_prefix} alarm notification SNS topic."
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:CreateAlias",
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:DeleteAlias",
          "kms:DescribeKey",
          "kms:DisableKey",
          "kms:DisableKeyRotation",
          "kms:EnableKey",
          "kms:EnableKeyRotation",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:ListGrants",
          "kms:ListResourceTags",
          "kms:PutKeyPolicy",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:RetireGrant",
          "kms:RevokeGrant",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:UpdateAlias",
          "kms:UpdateKeyDescription",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchAndSNSToUseKey"
        Effect = "Allow"
        Principal = {
          Service = [
            "cloudwatch.amazonaws.com",
            "sns.amazonaws.com",
          ]
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
        ]
        Resource = "*"
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alarm-notifications-key"
  })
}

# ------------------------------------------------------------------------------
# SNS topic receiving notifications from all alarms.
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "alarm_notifications" {
  name              = "${local.name_prefix}-alarm-notifications"
  display_name      = "${local.name_prefix}-alarm-notifications"
  kms_master_key_id = aws_kms_key.alarm_notifications.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alarm-notifications"
  })
}

# ------------------------------------------------------------------------------
# Topic policy: confused-deputy protection for CloudWatch alarm publishes.
# ------------------------------------------------------------------------------

resource "aws_sns_topic_policy" "alarm_notifications" {
  arn = aws_sns_topic.alarm_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountRootTopicAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "sns:*"
        Resource = aws_sns_topic.alarm_notifications.arn
      },
      {
        Sid    = "AllowCloudWatchAlarmsToPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.alarm_notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = [
              aws_cloudwatch_metric_alarm.application_errors.arn,
              aws_cloudwatch_metric_alarm.log_incoming_bytes.arn,
              aws_cloudwatch_composite_alarm.application.arn,
            ]
          }
        }
      },
    ]
  })
}

# ------------------------------------------------------------------------------
# Self-contained metric source: log group + metric filter.
# Note: aws_cloudwatch_log_metric_filter does not support resource tagging at
# the AWS API level; tagging consistency is preserved via its prefix-derived
# name and its association with the tagged log group below.
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "application" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-application-logs"
  })
}

resource "aws_cloudwatch_log_metric_filter" "application_errors" {
  name           = "${local.name_prefix}-error-count-metric-filter"
  log_group_name = aws_cloudwatch_log_group.application.name
  pattern        = "?ERROR"

  metric_transformation {
    name          = "ErrorCount"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

# ------------------------------------------------------------------------------
# Child alarm 1: application error count (custom metric from the filter).
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "application_errors" {
  alarm_name          = "${local.name_prefix}-application-errors"
  alarm_description   = "ALARM when the application logs more than 10 errors per minute for 3 consecutive minutes."
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 3
  metric_name         = aws_cloudwatch_log_metric_filter.application_errors.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.application_errors.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 10
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.alarm_notifications.arn]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-application-errors-alarm"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Child alarm 2: log ingestion volume (AWS/Logs IncomingBytes).
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "log_incoming_bytes" {
  alarm_name          = "${local.name_prefix}-log-incoming-bytes"
  alarm_description   = "ALARM when log ingestion volume for the application log group exceeds 10 MiB per 5-minute period for 3 consecutive periods."
  comparison_operator = "GreaterThanThreshold"
  namespace           = "AWS/Logs"
  metric_name         = "IncomingBytes"
  dimensions = {
    LogGroupName = aws_cloudwatch_log_group.application.name
  }
  evaluation_periods = 3
  period             = 300
  statistic          = "Sum"
  threshold          = 10485760
  treat_missing_data = "notBreaching"
  alarm_actions      = [aws_sns_topic.alarm_notifications.arn]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-log-incoming-bytes-alarm"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Composite alarm: fires when either child alarm is in ALARM state.
# Creation is implicitly ordered after both child alarms (via alarm_rule) and
# after the SNS topic / KMS key (via alarm_actions references).
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_composite_alarm" "application" {
  alarm_name        = "${local.name_prefix}-application-composite"
  alarm_description = "Composite ALARM when either the application error count alarm or the log ingestion volume alarm is in the ALARM state."
  alarm_rule        = "ALARM(\"${aws_cloudwatch_metric_alarm.application_errors.alarm_name}\") OR ALARM(\"${aws_cloudwatch_metric_alarm.log_incoming_bytes.alarm_name}\")"

  alarm_actions             = [aws_sns_topic.alarm_notifications.arn]
  ok_actions                = [aws_sns_topic.alarm_notifications.arn]
  insufficient_data_actions = [aws_sns_topic.alarm_notifications.arn]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-application-composite-alarm"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs for downstream consumers.
# ------------------------------------------------------------------------------

output "composite_alarm_arn" {
  description = "The ARN of the composite CloudWatch alarm."
  value       = aws_cloudwatch_composite_alarm.application.arn
}

output "application_errors_alarm_name" {
  description = "The name of the application error count metric alarm."
  value       = aws_cloudwatch_metric_alarm.application_errors.alarm_name
}

output "application_errors_alarm_arn" {
  description = "The ARN of the application error count metric alarm."
  value       = aws_cloudwatch_metric_alarm.application_errors.arn
}

output "log_incoming_bytes_alarm_name" {
  description = "The name of the log ingestion volume metric alarm."
  value       = aws_cloudwatch_metric_alarm.log_incoming_bytes.alarm_name
}

output "log_incoming_bytes_alarm_arn" {
  description = "The ARN of the log ingestion volume metric alarm."
  value       = aws_cloudwatch_metric_alarm.log_incoming_bytes.arn
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic that receives alarm notifications."
  value       = aws_sns_topic.alarm_notifications.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment tag applied to all DynamoDB tables"
  type        = string
  default     = "dev"
}

provider "aws" {
  alias  = "east"
  region = "us-east-1"
}

provider "aws" {
  alias  = "west1"
  region = "us-west-1"
}

