  }
}

resource "aws_dynamodb_table" "table_west2" {
  provider     = aws.west2
  name         = "app-data-us-west-2"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = "app-data-us-west-2"
  })

