terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Default provider: primary (source) region of the global table.
provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

# Aliased provider for the us-west-2 region; required to create the regional
# multi-Region KMS replica key in that region.
provider "aws" {
  alias  = "west"
  region = "us-west-2"

  default_tags {
    tags = var.tags
  }
}

# Aliased provider for the eu-west-1 region; required to create the regional
# multi-Region KMS replica key in that region.
provider "aws" {
  alias  = "eu"
  region = "eu-west-1"

  default_tags {
    tags = var.tags
  }
}

variable "table_name" {
  description = "Name of the DynamoDB global table."
  type        = string
  default     = "app_global_table"
}

variable "tags" {
  description = "User-controlled (non-infrastructure) tags applied to all resources for consistent tagging."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
    Owner       = "platform-team"
  }
}

locals {
  # Replica table and stream ARNs are derived from the primary table ARN by
  # substituting the region segment; the DynamoDB ARN format is deterministic.
  replica_usw2_table_arn  = replace(aws_dynamodb_table.main.arn, "us-east-1", "us-west-2")
  replica_euw1_table_arn  = replace(aws_dynamodb_table.main.arn, "us-east-1", "eu-west-1")
  replica_usw2_stream_arn = "${local.replica_usw2_table_arn}/stream/*"
  replica_euw1_stream_arn = "${local.replica_euw1_table_arn}/stream/*"
}

# Multi-Region customer managed key so the same key material protects every
# replica of the global table.
resource "aws_kms_key" "table" {
  description             = "Multi-Region CMK for the ${var.table_name} DynamoDB global table"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  multi_region            = true

  tags = var.tags
}

# Regional replica keys of the multi-Region key, one per replica region.
resource "aws_kms_replica_key" "usw2" {
  provider                = aws.west
  description             = "us-west-2 replica key for the ${var.table_name} DynamoDB global table"
  primary_key_arn         = aws_kms_key.table.arn
  deletion_window_in_days = 30

  tags = var.tags
}

resource "aws_kms_replica_key" "euw1" {
  provider                = aws.eu
  description             = "eu-west-1 replica key for the ${var.table_name} DynamoDB global table"
  primary_key_arn         = aws_kms_key.table.arn
  deletion_window_in_days = 30

  tags = var.tags
}

# Primary (source) table of the DynamoDB global table.
#
# Replicas are declared as inline replica blocks on the table resource (the
# only mechanism supported by the hashicorp/aws provider). Referencing each
# regional aws_kms_replica_key ARN inside its replica block creates an implicit
# dependency so the regional multi-Region key exists before the replica table
# is provisioned. There is no circular dependency, because each
# aws_kms_replica_key depends only on aws_kms_key.table.
#
# deletion_protection_enabled is a top-level argument of aws_dynamodb_table
# and applies to the primary table; per-replica deletion protection is not
# an expressible argument of the replica block in this provider version.
resource "aws_dynamodb_table" "main" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  # Streams are a mandatory prerequisite for DynamoDB global tables.
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.table.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = var.tags

  # Replica in us-west-2.
  replica {
    region_name            = "us-west-2"
    kms_key_arn            = aws_kms_replica_key.usw2.arn
    point_in_time_recovery = true
    propagate_tags         = true
  }

  # Replica in eu-west-1.
  replica {
    region_name            = "eu-west-1"
    kms_key_arn            = aws_kms_replica_key.euw1.arn
    point_in_time_recovery = true
    propagate_tags         = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege application access scoped strictly to the global table,
# its replicas, and their streams.
resource "aws_iam_policy" "app_global_table_access" {
  name        = "${var.table_name}-application-access"
  description = "Least-privilege application access to the ${var.table_name} DynamoDB global table, its replicas, and their streams"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GlobalTableDataPlaneAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:ConditionCheckItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:UpdateItem",
        ]
        Resource = [
          aws_dynamodb_table.main.arn,
          local.replica_usw2_table_arn,
          local.replica_euw1_table_arn,
        ]
      },
      {
        Sid    = "GlobalTableStreamAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeStream",
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:ListStreams",
        ]
        Resource = [
          aws_dynamodb_table.main.stream_arn,
          local.replica_usw2_stream_arn,
          local.replica_euw1_stream_arn,
        ]
      },
    ]
  })

  tags = var.tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Environment tag value applied to the DynamoDB table."
  default     = "dev"
}

variable "table_name" {
  type        = string
  description = "Name of the DynamoDB table."
  default     = "app-data"
}

locals {
  common_tags = {
    Name        = var.table_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "sagemaker-studio"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "${var.project}-${var.environment}"

  common_tags = {
    Environment = var.environment
    Project     = var.project
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ----------------------------------------------------------------------------
# Networking
# ----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "sagemaker" {
  name        = "${local.name_prefix}-sagemaker-sg"
  description = "SageMaker Studio apps - HTTPS ingress from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Self-referencing rule for traffic between SageMaker apps sharing this security group"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-sg"
  })
}

# ----------------------------------------------------------------------------
# S3 bucket for SageMaker notebook artifacts
# ----------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_data" {
  bucket = "${local.name_prefix}-data-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-data"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "sagemaker_data_tls" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.sagemaker_data.arn,
      "${aws_s3_bucket.sagemaker_data.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id
  policy = data.aws_iam_policy_document.sagemaker_data_tls.json

  depends_on = [aws_s3_bucket_public_access_block.sagemaker_data]
}

# ----------------------------------------------------------------------------
# SageMaker execution IAM role
# ----------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_assume_role" {
  statement {
    sid    = "AllowSageMakerToAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sagemaker_exec" {
  name               = "${local.name_prefix}-sagemaker-exec"
  description        = "Execution role for SageMaker Studio JupyterServer apps"
  assume_role_policy = data.aws_iam_policy_document.sagemaker_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-exec-role"
  })
}

resource "aws_iam_role_policy" "sagemaker_exec" {
  name = "${local.name_prefix}-sagemaker-exec-policy"
  role = aws_iam_role.sagemaker_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SageMakerDataBucketAccess"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [aws_s3_bucket.sagemaker_data.arn, "${aws_s3_bucket.sagemaker_data.arn}/*"]
      },
      {
        Sid      = "SageMakerCloudWatchLogs"
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*"
      },
      {
        Sid      = "SageMakerDescribeAccess"
        Effect   = "Allow"
        Action   = ["sagemaker:Describe*"]
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------------
# SageMaker Studio domain (hard prerequisite of the JupyterServer app)
# ----------------------------------------------------------------------------

resource "aws_sagemaker_domain" "studio" {
  domain_name             = "${local.name_prefix}-domain"
  auth_mode               = "IAM"
  app_network_access_type = "VpcOnly"
  vpc_id                  = aws_vpc.main.id
  subnet_ids              = aws_subnet.private[*].id

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_exec.arn
    security_groups = [aws_security_group.sagemaker.id]

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "ml.t3.medium"
      }
    }
  }

  retention_policy {
    home_efs_file_system = "Retain"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-domain"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------
# SageMaker user profile (owner of the JupyterServer app)
# ----------------------------------------------------------------------------

resource "aws_sagemaker_user_profile" "studio_user" {
  domain_id         = aws_sagemaker_domain.studio.id
  user_profile_name = "studio-user"

  user_settings {
    execution_role = aws_iam_role.sagemaker_exec.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-user-profile"
  })
}

# ----------------------------------------------------------------------------
# SageMaker JupyterServer app
# ----------------------------------------------------------------------------

resource "aws_sagemaker_app" "jupyter_server" {
  domain_id         = aws_sagemaker_domain.studio.id
  user_profile_name = aws_sagemaker_user_profile.studio_user.user_profile_name
  app_type          = "JupyterServer"
  app_name          = "default"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-jupyter-server"
  })
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------

output "jupyter_server_app_arn" {
  description = "ARN of the SageMaker JupyterServer app."
  value       = aws_sagemaker_app.jupyter_server.arn
}

output "sagemaker_domain_id" {
  description = "ID of the SageMaker Studio domain hosting the JupyterServer app."
  value       = aws_sagemaker_domain.studio.id
}

output "sagemaker_user_profile_name" {
  description = "User profile name that owns the JupyterServer app."
  value       = aws_sagemaker_user_profile.studio_user.user_profile_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "User-controlled environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

variable "project" {
  description = "User-controlled project name applied as a tag to all resources."
  type        = string
  default     = "sagemaker-notebooks"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "terraform"
  }
}

resource "random_string" "suffix" {
  length  = 8
  upper   = false
  special = false
}

# ------------------------------------------------------------------
# IAM execution role for the SageMaker notebook instance
# ------------------------------------------------------------------
resource "aws_iam_role" "sagemaker_notebook_execution" {
  name        = "sagemaker-notebook-execution-${random_string.suffix.result}"
  description = "Execution role assumed by the SageMaker service for the notebook instance."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# ------------------------------------------------------------------
# Least-privilege SageMaker + S3 permissions policy
# ------------------------------------------------------------------
resource "aws_iam_policy" "sagemaker_notebook_execution" {
  name        = "sagemaker-notebook-execution-policy-${random_string.suffix.result}"
  description = "Least-privilege SageMaker and S3 permissions for the notebook instance execution role."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageThisNotebookInstance"
        Effect = "Allow"
        Action = [
          "sagemaker:DescribeNotebookInstance",
          "sagemaker:StartNotebookInstance",
          "sagemaker:StopNotebookInstance",
          "sagemaker:UpdateNotebookInstance",
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListTags"
        ]
        Resource = "arn:aws:sagemaker:us-east-1:*:notebook-instance/*"
      },
      {
        Sid      = "ListNotebookArtifactBucket"
        Effect   = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = aws_s3_bucket.notebook_artifacts.arn
      },
      {
        Sid    = "ReadWriteNotebookArtifacts"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.notebook_artifacts.arn}/*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_notebook_execution" {
  role       = aws_iam_role.sagemaker_notebook_execution.name
  policy_arn = aws_iam_policy.sagemaker_notebook_execution.arn
}

# ------------------------------------------------------------------
# Dedicated private S3 bucket for notebook artifacts
# ------------------------------------------------------------------
resource "aws_s3_bucket" "notebook_artifacts" {
  bucket = "sagemaker-notebook-artifacts-${random_string.suffix.result}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------
# Customer managed KMS key for the notebook ML storage volume
# ------------------------------------------------------------------
resource "aws_kms_key" "notebook_volume" {
  description             = "Encrypts the ML storage volume attached to the SageMaker notebook instance."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "notebook_volume" {
  name          = "alias/sagemaker-notebook-volume-${random_string.suffix.result}"
  target_key_id = aws_kms_key.notebook_volume.key_id
}

# ------------------------------------------------------------------
# SageMaker notebook instance (AWS-managed networking mode:
# subnet_id and security_group_ids intentionally omitted)
# ------------------------------------------------------------------
resource "aws_sagemaker_notebook_instance" "ml_t2_medium_notebook" {
  name          = "ml-t2-medium-notebook-${random_string.suffix.result}"
  role_arn      = aws_iam_role.sagemaker_notebook_execution.arn
  instance_type = "ml.t2.medium"
  kms_key_id    = aws_kms_key.notebook_volume.arn
  root_access   = "Disabled"

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.sagemaker_notebook_execution]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

variable "tags" {
  description = "Consistent tags applied to every tagged resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

locals {
  model_name             = "sklearn-model"
  endpoint_name          = "sklearn-endpoint"
  endpoint_config_name   = "sklearn-endpoint-config"
  iam_role_name          = "sagemaker-sklearn-execution"
  artifacts_bucket_name  = "sagemaker-model-artifacts-${data.aws_caller_identity.current.account_id}"
  model_artifact_key     = "models/sklearn/model.tar.gz"
  model_data_url         = "s3://${aws_s3_bucket.model_artifacts.bucket}/${local.model_artifact_key}"
  # Public SageMaker prebuilt scikit-learn inference image (ECR Public alias — no
  # region-specific numeric AWS account IDs are hardcoded in the registry path).
  model_image             = "public.ecr.aws/sagemaker/sagemaker-scikit-learn:0.23-1-cpu-py3"
  endpoint_log_group_name = "/aws/sagemaker/Endpoints/${local.endpoint_name}"
}

# ------------------------------------------------------------------------------
# S3 bucket for model artifacts
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "model_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = merge(var.tags, { Name = local.artifacts_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.model_artifacts.arn,
          "${aws_s3_bucket.model_artifacts.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.model_artifacts]
}

# ------------------------------------------------------------------------------
# IAM execution role for SageMaker
# ------------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_execution" {
  name = local.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = local.iam_role_name })
}

resource "aws_iam_role_policy" "s3_model_artifacts_read" {
  name = "s3-model-artifacts-read"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListArtifactsBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.model_artifacts.arn]
      },
      {
        Sid      = "ReadModelArtifacts"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.model_artifacts.arn}/models/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecr_image_pull" {
  name = "ecr-image-pull"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        # ecr:GetAuthorizationToken is not resource-scopable, and the published
        # SageMaker framework images live in AWS-managed repositories outside
        # this account, so repository-level ARN scoping is not possible here.
        # Only narrowly-scoped retrieval actions are granted.
        Sid    = "PullSageMakerInferenceImages"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_endpoint_logs" {
  name = "cloudwatch-endpoint-logs"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteEndpointLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = ["${aws_cloudwatch_log_group.endpoint_logs.arn}:*"]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CloudWatch log group for endpoint invocation logs
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "endpoint_logs" {
  name              = local.endpoint_log_group_name
  retention_in_days = 30

  tags = merge(var.tags, { Name = local.endpoint_log_group_name })
}

# ------------------------------------------------------------------------------
# SageMaker model, endpoint configuration, and endpoint
# ------------------------------------------------------------------------------

resource "aws_sagemaker_model" "sklearn_model" {
  name               = local.model_name
  execution_role_arn = aws_iam_role.sagemaker_execution.arn

  enable_network_isolation = true

  primary_container {
    image          = local.model_image
    model_data_url = local.model_data_url
  }

  tags = merge(var.tags, { Name = local.model_name })
}

resource "aws_sagemaker_endpoint_configuration" "sklearn_config" {
  name = local.endpoint_config_name

  production_variants {
    variant_name           = "sklearn-variant"
    model_name             = aws_sagemaker_model.sklearn_model.name
    initial_instance_count = 1
    instance_type          = "ml.m5.large"
  }

  tags = merge(var.tags, { Name = local.endpoint_config_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sagemaker_endpoint" "sklearn_endpoint" {
  name                 = local.endpoint_name
  endpoint_config_name = aws_sagemaker_endpoint_configuration.sklearn_config.name

  tags = merge(var.tags, { Name = local.endpoint_name })

  depends_on = [aws_cloudwatch_log_group.endpoint_logs]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (user-controlled values only, all with unattended-apply defaults)
# -----------------------------------------------------------------------------

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_type" {
  description = "EC2 instance type for the Amazon Linux 2 server."
  type        = string
  default     = "t3.micro"
}

variable "project_name" {
  description = "Value used for the Name tag and resource naming."
  type        = string
  default     = "amazon-linux-2-server"
}

variable "environment" {
  description = "Environment tag value (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static/well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-vpc"
    }
  )
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-public-subnet"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-public-route-table"
    }
  )
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security group (least-privilege ingress, unrestricted egress)
# -----------------------------------------------------------------------------

resource "aws_security_group" "ec2_sg" {
  name        = "${var.project_name}-ec2-sg"
  description = "Allow SSH only from within the VPC; allow all outbound traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic (package updates, SSM agent)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-ec2-sg"
    }
  )
}

# -----------------------------------------------------------------------------
# SSH key material (generated, never hardcoded)
# -----------------------------------------------------------------------------

resource "tls_private_key" "ec2_ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "ec2_ssh" {
  key_name   = "${var.project_name}-keypair"
  public_key = tls_private_key.ec2_ssh.public_key_openssh

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-keypair"
    }
  )
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name        = "${var.project_name}/ssh/private-key"
  description = "Private key material for the ${var.project_name} EC2 SSH key pair."

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-ssh-private-key"
    }
  )
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.ec2_ssh.private_key_pem
}

# -----------------------------------------------------------------------------
# IAM (SSM-based administration)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ssm_role" {
  name = "${var.project_name}-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-ssm-role"
    }
  )
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ssm_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm_profile" {
  name = "${var.project_name}-ssm-instance-profile"
  role = aws_iam_role.ssm_role.name
}

# -----------------------------------------------------------------------------
# EC2 instance (latest Amazon Linux 2)
# -----------------------------------------------------------------------------

resource "aws_instance" "al2_server" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.ec2_sg.id]
  key_name                    = aws_key_pair.ec2_ssh.key_name
  iam_instance_profile        = aws_iam_instance_profile.ssm_profile.name
  associate_public_ip_address = true

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 20
    encrypted             = true
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  tags = merge(
    local.common_tags,
    {
      Name        = var.project_name
      AmiId       = data.aws_ami.amazon_linux_2.id
      Description = "Amazon Linux 2 server using the latest AMI resolved dynamically"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "instance_id" {
  description = "ID of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.al2_server.id
}

output "public_ip" {
  description = "Public IP address of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.al2_server.public_ip
}

output "private_ip" {
  description = "Private IP address of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.al2_server.private_ip
}

output "latest_amazon_linux_2_ami_id" {
  description = "Latest Amazon Linux 2 AMI ID resolved by the aws_ami data source."
  value       = data.aws_ami.amazon_linux_2.id
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the generated SSH private key."
  value       = aws_secretsmanager_secret.ssh_private_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Short project prefix used for resource names and tags."
  type        = string
  default     = "al2023-efs-shared"
}

variable "environment" {
  description = "Environment name applied to the Environment tag of every resource."
  type        = string
  default     = "dev"
}

variable "instance_type" {
  description = "EC2 instance type for the two private Amazon Linux 2023 instances."
  type        = string
  default     = "t3.micro"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${data.aws_availability_zones.available.names[0]}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_security_group" "ec2" {
  name        = "${local.name_prefix}-ec2-sg"
  description = "Private EC2 instances; no inbound access, administration via AWS Systems Manager only"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-sg"
  })
}

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs-sg"
  description = "EFS mount targets; NFS restricted to the EC2 instance security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "NFS from EC2 instances only"
    from_port       = 2049
    to_port         = 2049
    protocol        = "tcp"
    security_groups = [aws_security_group.ec2.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-sg"
  })
}

resource "aws_efs_file_system" "main" {
  creation_token   = "${local.name_prefix}-efs"
  performance_mode = "generalPurpose"
  throughput_mode  = "elastic"
  encrypted        = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "main" {
  count = 2

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm" {
  name               = "${local.name_prefix}-ssm-role"
  description        = "Role assumed by the private instances for AWS Systems Manager access"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.ssm.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-profile"
  })
}

resource "aws_instance" "app" {
  count = 2

  ami                         = data.aws_ami.al2023.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private[count.index].id
  vpc_security_group_ids      = [aws_security_group.ec2.id]
  iam_instance_profile        = aws_iam_instance_profile.ssm.name
  associate_public_ip_address = false

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  user_data = base64encode(<<-USER_DATA
    #!/bin/bash
    set -euxo pipefail

    dnf install -y nfs-utils amazon-efs-utils

    EFS_DNS_NAME="${aws_efs_file_system.main.dns_name}"
    MOUNT_POINT="/mnt/efs"

    mkdir -p "$MOUNT_POINT"

    for attempt in $(seq 1 30); do
      if mount -t efs -o tls "$EFS_DNS_NAME":/ "$MOUNT_POINT"; then
        echo "$EFS_DNS_NAME":/ "$MOUNT_POINT" efs tls,_netdev 0 0 >> /etc/fstab
        echo "EFS successfully mounted at $MOUNT_POINT"
        exit 0
      fi
      echo "EFS mount attempt $attempt failed; retrying in 10 seconds"
      sleep 10
    done

    echo "Failed to mount EFS after 30 attempts" >&2
    exit 1
  USER_DATA
  )

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-${data.aws_availability_zones.available.names[count.index]}"
  })

  depends_on = [aws_efs_mount_target.main]
}

output "instance_ids" {
  description = "IDs of the two private Amazon Linux 2023 instances."
  value       = aws_instance.app[*].id
}

output "instance_private_ips" {
  description = "Private IP addresses of the two instances, one per AZ."
  value       = aws_instance.app[*].private_ip
}

output "efs_file_system_id" {
  description = "ID of the shared encrypted EFS file system."
  value       = aws_efs_file_system.main.id
}

output "efs_dns_name" {
  description = "DNS name of the shared EFS file system mounted on every instance."
  value       = aws_efs_file_system.main.dns_name
}

output "efs_mount_targets" {
  description = "Per-AZ identity of the EFS mount targets (mount target ID and IP mapped to the AZ of its private subnet)."
  value = [
    for i in range(2) : {
      mount_target_id   = aws_efs_mount_target.main[i].id
      ip_address        = aws_efs_mount_target.main[i].ip_address
      availability_zone = aws_subnet.private[i].availability_zone
    }
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (non-infrastructure values only, all defaulted for unattended apply)
# ---------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "cache-app"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (safe, well-known data sources)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  name       = "${var.project_name}-${var.environment}"
  snake_name = replace(local.name, "-", "_")
  vpc_cidr   = "10.42.0.0/16"
  redis_port = 6379

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Network: dedicated VPC with two private subnets across the first two AZs
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_elasticache_subnet_group" "main" {
  name        = "${local.name}-cache-subnets"
  description = "Private subnets for the ${local.name} ElastiCache cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-subnets"
  })
}

resource "aws_security_group" "cache" {
  name        = "${local.name}-cache-sg"
  description = "ElastiCache ingress restricted to the VPC CIDR on TCP 6379 only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from within the VPC only"
    from_port   = local.redis_port
    to_port     = local.redis_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound responses"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-sg"
  })
}

# ---------------------------------------------------------------------------
# ElastiCache RBAC user authenticated via IAM (no passwords anywhere)
# ---------------------------------------------------------------------------

resource "aws_elasticache_user" "iam_user" {
  engine        = "redis"
  user_id       = "${local.snake_name}_iam_user"
  user_name     = "${local.snake_name}_client"
  access_string = "on ~app:* -@all +@read +@write"

  authentication_mode {
    type = "iam"
  }

  tags = merge(local.common_tags, {
    Name = "${local.snake_name}_iam_user"
  })
}

resource "aws_elasticache_user_group" "main" {
  engine        = "redis"
  user_group_id = "${local.name}-user-group"
  user_ids      = [aws_elasticache_user.iam_user.user_id]

  tags = merge(local.common_tags, {
    Name = "${local.name}-user-group"
  })
}

# ---------------------------------------------------------------------------
# Redis OSS replication group wired to the IAM-authenticated user group
# ---------------------------------------------------------------------------

resource "aws_elasticache_replication_group" "cache" {
  replication_group_id = "${local.name}-redis"
  description          = "Redis 7 replication group using IAM-authenticated RBAC users"
  engine               = "redis"
  engine_version       = "7.0"
  node_type            = "cache.t3.medium"
  parameter_group_name = "default.redis7"

  num_cache_clusters         = 2
  automatic_failover_enabled = true
  multi_az_enabled           = true

  subnet_group_name  = aws_elasticache_subnet_group.main.name
  security_group_ids = [aws_security_group.cache.id]
  user_group_ids     = [aws_elasticache_user_group.main.id]

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true

  snapshot_retention_limit = 7
  snapshot_window          = "02:00-04:00"
  maintenance_window       = "sun:04:30-sun:06:30"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-redis"
  })
}

# ---------------------------------------------------------------------------
# IAM: least-privilege elasticache:Connect policy and assumable client role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "cache_client_assume" {
  statement {
    sid     = "AllowSameAccountClientsToAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

data "aws_iam_policy_document" "cache_connect" {
  statement {
    sid       = "ElastiCacheIamAuthConnect"
    effect    = "Allow"
    actions   = ["elasticache:Connect"]
    resources = [
      aws_elasticache_replication_group.cache.arn,
      aws_elasticache_user.iam_user.arn,
    ]
  }

  statement {
    sid       = "ElastiCacheReplicationGroupDiscovery"
    effect    = "Allow"
    actions   = ["elasticache:DescribeReplicationGroups"]
    resources = [aws_elasticache_replication_group.cache.arn]
  }
}

resource "aws_iam_policy" "cache_connect" {
  name        = "${local.name}-cache-connect"
  description = "Least-privilege IAM authentication access to the ${local.name} ElastiCache cluster"
  policy      = data.aws_iam_policy_document.cache_connect.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-connect"
  })
}

resource "aws_iam_role" "cache_client" {
  name               = "${local.name}-cache-client"
  description        = "Role assumed by client applications for ElastiCache IAM authentication"
  assume_role_policy = data.aws_iam_policy_document.cache_client_assume.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-client"
  })
}

resource "aws_iam_role_policy_attachment" "cache_client_connect" {
  role       = aws_iam_role.cache_client.name
  policy_arn = aws_iam_policy.cache_connect.arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "cache_client_role_arn" {
  description = "IAM role that client applications assume to sign ElastiCache connect requests."
  value       = aws_iam_role.cache_client.arn
}

output "cache_iam_user_id" {
  description = "ElastiCache user ID to use as the Redis username for IAM-authenticated connections."
  value       = aws_elasticache_user.iam_user.user_id
}

output "cache_primary_endpoint" {
  description = "Primary endpoint of the Redis replication group."
  value       = aws_elasticache_replication_group.cache.primary_endpoint_address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = length(var.environment) > 0
    error_message = "environment must be a non-empty string."
  }

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]{0,14}[a-z0-9])?$", var.environment)) && !can(regex("--", var.environment))
    error_message = "environment may contain only lowercase letters, digits, and single hyphens (1-16 characters), starting and ending with a letter or digit."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "dax-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_security_group" "dax" {
  name        = "${local.name_prefix}-dax-sg"
  description = "DAX cluster endpoint access restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "DAX endpoint (TCP 8111) from within the VPC"
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Controlled egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-dax-sg"
  })
}

resource "aws_dynamodb_table" "main" {
  name         = "${local.name_prefix}-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"

  attribute {
    name = "pk"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-table"
  })

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "dax_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["dax.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "dax" {
  name               = "${local.name_prefix}-role"
  assume_role_policy = data.aws_iam_policy_document.dax_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-role"
  })
}

data "aws_iam_policy_document" "dax_dynamodb" {
  statement {
    sid    = "DaxDynamoDBTableAccess"
    effect = "Allow"

    actions = [
      "dynamodb:GetItem",
      "dynamodb:BatchGetItem",
      "dynamodb:Query",
      "dynamodb:Scan",
      "dynamodb:PutItem",
      "dynamodb:BatchWriteItem",
      "dynamodb:DescribeTable",
      "dynamodb:ConditionCheckItem",
    ]

    resources = [
      aws_dynamodb_table.main.arn,
      "${aws_dynamodb_table.main.arn}/index/*",
    ]
  }
}

resource "aws_iam_role_policy" "dax_dynamodb" {
  name   = "${local.name_prefix}-dynamodb-access"
  role   = aws_iam_role.dax.name
  policy = data.aws_iam_policy_document.dax_dynamodb.json
}

resource "aws_dax_subnet_group" "main" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_dax_cluster" "main" {
  cluster_name       = substr(local.name_prefix, 0, 20)
  iam_role_arn       = aws_iam_role.dax.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  availability_zones = [data.aws_availability_zones.available.names[0]]
  subnet_group_name  = aws_dax_subnet_group.main.name
  security_group_ids = [aws_security_group.dax.id]

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = local.name_prefix
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "dax_cluster_arn" {
  description = "ARN of the DAX cluster."
  value       = aws_dax_cluster.main.arn
}

output "dax_configuration_endpoint" {
  description = "Configuration endpoint (host:port) of the DAX cluster."
  value       = aws_dax_cluster.main.configuration_endpoint
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "environment" {
  description = "Environment name applied to resource names and tags."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "msk-${var.environment}"

  common_tags = {
    Project     = "msk-kafka"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "broker" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route_table_association" "broker" {
  count = 3

  subnet_id      = aws_subnet.broker[count.index].id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "MSK broker ingress: TLS 9094 and IAM SASL 9098 from VPC CIDR only, inter-broker 9092 from within this group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TLS client traffic on 9094 from within the VPC only"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "IAM-authenticated SASL client traffic on 9098 from within the VPC only"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Inter-broker traffic on 9092 restricted to this security group only"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.name_prefix}/brokers"
  retention_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_resource_policy" "msk_log_delivery" {
  policy_name = "${local.name_prefix}-msk-log-delivery"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "MskCloudWatchLogDelivery"
        Effect    = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.msk_broker_logs.arn,
          "${aws_cloudwatch_log_group.msk_broker_logs.arn}:log-stream:*"
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-msk-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${local.name_prefix}-key"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_msk_cluster" "main" {
  cluster_name           = "${local.name_prefix}-cluster"
  kafka_version          = "3.7.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.broker[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of broker endpoints for SASL/IAM clients (port 9098)."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_cloudwatch_log_group_name" {
  description = "CloudWatch log group receiving MSK broker logs."
  value       = aws_cloudwatch_log_group.msk_broker_logs.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "environment" {
  description = "Environment name used for naming and tagging (non-infrastructure metadata only)."
  type        = string
  default     = "production"
}

variable "tags" {
  description = "Additional metadata tags applied to all resources (non-infrastructure metadata only)."
  type        = map(string)
  default = {
    Project   = "msk-open-monitoring"
    ManagedBy = "terraform"
  }
}

locals {
  name_prefix = "msk-${var.environment}"
  common_tags = merge(var.tags, {
    Environment = var.environment
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-brokers"
  description = "Restrict access to MSK broker ports from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client/broker port 9092"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka TLS client/broker port 9094"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka IAM client/broker port 9098"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "ZooKeeper port 2181"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All egress within the VPC for Kafka inter-broker traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers"
  })
}

resource "aws_kms_key" "msk" {
  description             = "At-rest encryption key for MSK broker storage"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${local.name_prefix}-kafka"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${var.environment}"
  retention_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_msk_cluster" "kafka" {
  cluster_name           = "${local.name_prefix}-kafka"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.private[0].id,
      aws_subnet.private[1].id,
      aws_subnet.private[2].id,
    ]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  enhanced_monitoring = "PER_BROKER"

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  broker_hosts = [
    for endpoint in split(",", aws_msk_cluster.kafka.bootstrap_brokers_tls) : split(":", endpoint)[0]
  ]

  jmx_scrape_targets  = [for host in local.broker_hosts : "${host}:11001"]
  node_scrape_targets = [for host in local.broker_hosts : "${host}:11002"]
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.kafka.arn
}

output "bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints (host:9094, comma separated)."
  value       = aws_msk_cluster.kafka.bootstrap_brokers_tls
}

output "zookeeper_connect_string" {
  description = "ZooKeeper connect string for the MSK cluster."
  value       = aws_msk_cluster.kafka.zookeeper_connect_string
}

output "prometheus_scrape_endpoints" {
  description = "Prometheus open-monitoring discovery info: JMX exporter on port 11001 and node exporter on port 11002 for each broker host."
  value = {
    jmx_exporter_port   = 11001
    node_exporter_port  = 11002
    jmx_scrape_targets  = local.jmx_scrape_targets
    node_scrape_targets = local.node_scrape_targets
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-2"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC"
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  kafka_topic_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:topic/${aws_msk_serverless_cluster.main.cluster_name}/*"

  kafka_group_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:group/${aws_msk_serverless_cluster.main.cluster_name}/*"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "msk-serverless-vpc-${var.environment}"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "msk-serverless-private-a-${var.environment}"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "msk-serverless-private-b-${var.environment}"
  })
}

resource "aws_security_group" "msk_clients" {
  name        = "msk-serverless-clients-${var.environment}"
  description = "Restrict ingress to IAM-authenticated Kafka traffic (TCP 9098) from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka SASL/IAM bootstrap and broker traffic from within the VPC"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "msk-serverless-clients-${var.environment}"
  })
}

resource "aws_msk_serverless_cluster" "main" {
  cluster_name = "msk-serverless-${var.environment}"

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  vpc_config {
    subnet_ids = [
      aws_subnet.private_a.id,
      aws_subnet.private_b.id,
    ]
    security_group_ids = [aws_security_group.msk_clients.id]
  }

  tags = merge(local.common_tags, {
    Name = "msk-serverless-${var.environment}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "kafka_client" {
  name        = "msk-serverless-kafka-client-${var.environment}"
  description = "Assumed by Kafka client workloads to authenticate to the MSK Serverless cluster via AWS IAM"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kafka_client_cluster" {
  name = "msk-serverless-cluster-access"
  role = aws_iam_role.kafka_client.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "MSKServerlessClusterAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:DescribeCluster",
          "kafka-cluster:DescribeClusterV2"
        ]
        Resource = [aws_msk_serverless_cluster.main.arn]
      }
    ]
  })
}

resource "aws_iam_policy" "kafka_client_data" {
  name        = "msk-serverless-kafka-data-${var.environment}"
  description = "Least-privilege Kafka topic and consumer group access scoped to the MSK Serverless cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KafkaTopicAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:CreateTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:AlterTopic",
          "kafka-cluster:WriteData",
          "kafka-cluster:ReadData"
        ]
        Resource = [local.kafka_topic_arn_pattern]
      },
      {
        Sid    = "KafkaConsumerGroupAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:AlterGroup",
          "kafka-cluster:DescribeGroup"
        ]
        Resource = [local.kafka_group_arn_pattern]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "kafka_client_data" {
  role       = aws_iam_role.kafka_client.name
  policy_arn = aws_iam_policy.kafka_client_data.arn
}

output "bootstrap_brokers_sasl_iam" {
  description = "IAM-authenticated (SASL over TLS, port 9098) bootstrap broker endpoints for the MSK Serverless cluster"
  value       = aws_msk_serverless_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_cluster_arn" {
  description = "ARN of the MSK Serverless cluster"
  value       = aws_msk_serverless_cluster.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (user-controlled, non-infrastructure values only)
###############################################################################

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "aurora-demo"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{2,29}$", var.project_name))
    error_message = "Project name must be 3-30 characters: lowercase letters, digits, or hyphens, starting with a letter."
  }
}

variable "environment_name" {
  description = "Environment name (e.g. dev, staging, prod) used for naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment_name)
    error_message = "Environment name must be one of: dev, staging, prod."
  }
}

variable "allowed_ingress_cidr" {
  description = "Private CIDR block allowed to connect to the Aurora cluster on port 3306."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.allowed_ingress_cidr)) && var.allowed_ingress_cidr != "0.0.0.0/0"
    error_message = "allowed_ingress_cidr must be a valid CIDR block and must not be 0.0.0.0/0."
  }
}

###############################################################################
# Locals and static provider metadata
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.project_name}-${var.environment_name}"

  vpc_cidr             = "10.0.0.0/16"
  all_subnet_cidrs     = cidrsubnets(local.vpc_cidr, 8, 8, 8, 8)
  private_subnet_cidrs = slice(local.all_subnet_cidrs, 0, 2)
  public_subnet_cidrs  = slice(local.all_subnet_cidrs, 2, 4)

  master_username = "admin"
  database_name   = "appdb"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment_name
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Networking foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# Private subnets: host the Aurora cluster; never publicly routable.
resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "database"
  })
}

# Public subnets: keep the internet gateway functional for the VPC.
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

# Private route table has no internet route: database subnets stay isolated.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Database subnet group (requires subnets in at least two AZs)
###############################################################################

resource "aws_db_subnet_group" "aurora_mysql" {
  name        = "${local.name_prefix}-aurora-subnet-group"
  description = "Private subnets for the ${local.name_prefix} Aurora MySQL cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-subnet-group"
  })
}

###############################################################################
# Security group: ingress restricted to MySQL on 3306 from a private CIDR only
###############################################################################

resource "aws_security_group" "aurora_mysql" {
  name        = "${local.name_prefix}-aurora-mysql-sg"
  description = "Restrict MySQL access to the ${local.name_prefix} Aurora MySQL cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the allowed private CIDR only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ingress_cidr]
  }

  egress {
    description = "Outbound restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-sg"
  })
}

###############################################################################
# KMS encryption key for the cluster
###############################################################################

resource "aws_kms_key" "aurora_mysql" {
  description             = "Customer managed key for the ${local.name_prefix} Aurora MySQL cluster"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cluster parameter group (Aurora MySQL 8.0 family, utf8mb4 defaults)
###############################################################################

resource "aws_rds_cluster_parameter_group" "aurora_mysql" {
  name        = "${local.name_prefix}-aurora-mysql-params"
  family      = "aurora-mysql8.0"
  description = "Cluster parameter group for the ${local.name_prefix} Aurora MySQL 8.0 cluster"

  parameter {
    name  = "character_set_client"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_connection"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_database"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_filesystem"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_results"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "collation_connection"
    value = "utf8mb4_general_ci"
  }

  parameter {
    name  = "collation_server"
    value = "utf8mb4_general_ci"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-params"
  })
}

###############################################################################
# Aurora MySQL cluster (credentials managed by RDS via Secrets Manager)
###############################################################################

resource "aws_rds_cluster" "aurora_mysql" {
  cluster_identifier  = "${local.name_prefix}-aurora-mysql"
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.08.0"
  database_name       = local.database_name
  master_username     = local.master_username
  manage_master_user_password = true
  port                = 3306

  db_subnet_group_name            = aws_db_subnet_group.aurora_mysql.name
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.aurora_mysql.name
  vpc_security_group_ids          = [aws_security_group.aurora_mysql.id]

  storage_encrypted = true
  kms_key_id        = aws_kms_key.aurora_mysql.arn

  backup_retention_period      = 14
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot        = true
  deletion_protection          = true
  skip_final_snapshot          = false
  final_snapshot_identifier    = "${local.name_prefix}-aurora-mysql-final"

  enabled_cloudwatch_logs_exports = ["error", "general", "slowquery"]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cluster instances: exactly two, one per private subnet AZ
###############################################################################

resource "aws_rds_cluster_instance" "aurora_mysql_1" {
  identifier           = "${local.name_prefix}-aurora-mysql-1"
  cluster_identifier   = aws_rds_cluster.aurora_mysql.id
  engine               = "aurora-mysql"
  engine_version       = aws_rds_cluster.aurora_mysql.engine_version
  instance_class       = "db.r6g.large"
  db_subnet_group_name = aws_db_subnet_group.aurora_mysql.name
  availability_zone    = data.aws_availability_zones.available.names[0]
  publicly_accessible  = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "aurora_mysql_2" {
  identifier           = "${local.name_prefix}-aurora-mysql-2"
  cluster_identifier   = aws_rds_cluster.aurora_mysql.id
  engine               = "aurora-mysql"
  engine_version       = aws_rds_cluster.aurora_mysql.engine_version
  instance_class       = "db.r6g.large"
  db_subnet_group_name = aws_db_subnet_group.aurora_mysql.name
  availability_zone    = data.aws_availability_zones.available.names[1]
  publicly_accessible  = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "aurora_writer_endpoint" {
  description = "Writer endpoint for the Aurora MySQL cluster."
  value       = aws_rds_cluster.aurora_mysql.endpoint
}

output "aurora_reader_endpoint" {
  description = "Reader endpoint for the Aurora MySQL cluster."
  value       = aws_rds_cluster.aurora_mysql.reader_endpoint
}

output "aurora_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Aurora master credentials."
  value       = aws_rds_cluster.aurora_mysql.master_user_secret[0].secret_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_identifier      = "mysql-db"
  db_master_username = "dbadmin"
  db_name            = "appdb"
  db_port            = 3306
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "mysql-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "mysql-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "mysql-private-route-table"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "mysql" {
  name       = "mysql-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "mysql-db-subnet-group"
  }
}

# ---------------------------------------------------------------------------
# Database security group
# ---------------------------------------------------------------------------

resource "aws_security_group" "mysql" {
  name        = "mysql-db-sg"
  description = "Allow MySQL traffic from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL traffic within the VPC (e.g. replication)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "mysql-db-sg"
  }
}

# ---------------------------------------------------------------------------
# Master credentials
# ---------------------------------------------------------------------------

resource "random_password" "mysql_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "mysql" {
  name                    = "mysql-master-credentials"
  description             = "Master credentials for the MySQL RDS instance"
  recovery_window_in_days = 7

  tags = {
    Name = "mysql-master-credentials"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "mysql" {
  secret_id = aws_secretsmanager_secret.mysql.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.mysql_master.result
    engine   = "mysql"
    port     = local.db_port
    dbname   = local.db_name
  })
}

# ---------------------------------------------------------------------------
# Parameter group
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "mysql" {
  name   = "mysql-params"
  family = "mysql8.0"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "collation_server"
    value = "utf8mb4_unicode_ci"
  }

  parameter {
    name  = "character_set_client"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_connection"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_results"
    value = "utf8mb4"
  }
}

# ---------------------------------------------------------------------------
# MySQL instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "mysql" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0.35"
  instance_class = "db.t3.medium"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.db_name
  port     = local.db_port
  username = jsondecode(aws_secretsmanager_secret_version.mysql.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.mysql.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]
  parameter_group_name   = aws_db_parameter_group.mysql.name

  multi_az                   = true
  publicly_accessible        = false
  auto_minor_version_upgrade = true

  backup_retention_period   = 7
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "mysql-final-snapshot"

  tags = {
    Name = local.db_identifier
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "db_endpoint" {
  description = "Connection endpoint (host:port) of the MySQL instance"
  value       = aws_db_instance.mysql.endpoint
}

output "db_address" {
  description = "Hostname of the MySQL instance"
  value       = aws_db_instance.mysql.address
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials"
  value       = aws_secretsmanager_secret.mysql.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied to the DynamoDB table"
  type        = string
  default     = "dev"
}

resource "aws_dynamodb_table" "main" {
  name                        = "app-data"
  billing_mode                = "PAY_PER_REQUEST"
  hash_key                    = "id"
  deletion_protection_enabled = true

  attribute {
    name = "id"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = {
    Name        = "app-data"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table"
  value       = aws_dynamodb_table.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag value applied to the DAX parameter group."
  type        = string
  default     = "production"
}

variable "project" {
  description = "Project tag value applied to the DAX parameter group."
  type        = string
  default     = "dax-query-tuning"
}

locals {
  parameter_group_name = "dax-query-tuning-params"
}

resource "aws_dax_parameter_group" "dax_params" {
  name = local.parameter_group_name

  description = "Managed by Terraform - project: ${var.project} (${var.environment})"

  parameters {
    name  = "query-ttl-millis"
    value = "100000"
  }

  parameters {
    name  = "query-timeout-millis"
    value = "100000"
  }

  parameters {
    name  = "max-query-results"
    value = "1500"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = local.region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "environment" {
  description = "Deployment environment name (e.g. dev, staging, prod) used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]*[a-z0-9])?$", var.environment))
    error_message = "Environment must be lowercase alphanumeric, optionally separated by hyphens."
  }
}

variable "additional_tags" {
  description = "Additional tags merged into the default tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

locals {
  region     = "us-east-1"
  table_name = "dynamodb-table-${var.environment}"

  default_tags = {
    Name        = local.table_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  tags = merge(local.default_tags, var.additional_tags)
}

resource "aws_kms_key" "dynamodb" {
  description             = "Customer-managed KMS key used to encrypt the ${local.table_name} DynamoDB table at rest."
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMPermissionsForAccount"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowDynamoDBViaService"
        Effect    = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "dynamodb.${local.region}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = merge(local.tags, { Name = "kms-dynamodb-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dynamodb" {
  name          = "alias/dynamodb-table-encryption"
  target_key_id = aws_kms_key.dynamodb.key_id
}

resource "aws_dynamodb_table" "main" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_name" {
  description = "Name of the encrypted DynamoDB table."
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the encrypted DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

output "dynamodb_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the DynamoDB table."
  value       = aws_kms_key.dynamodb.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources"
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name used as the Name tag prefix for all resources"
  type        = string
  default     = "egress-only-vpc"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = true

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_egress_only_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eigw"
  })
}

resource "aws_subnet" "egress" {
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[0]

  cidr_block      = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  ipv6_cidr_block = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)

  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-egress"
  })
}

resource "aws_route_table" "egress" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt-egress"
  })
}

resource "aws_route" "egress_only_ipv6" {
  route_table_id              = aws_route_table.egress.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main.id
}

resource "aws_route_table_association" "egress" {
  subnet_id      = aws_subnet.egress.id
  route_table_id = aws_route_table.egress.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "destination_cidr_block" {
  description = "Specific destination CIDR block routed through the Internet Gateway. Must not be the default route 0.0.0.0/0."
  type        = string
  default     = "10.100.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.destination_cidr_block)) && var.destination_cidr_block != "0.0.0.0/0"
    error_message = "destination_cidr_block must be a valid IPv4 CIDR block and must not be 0.0.0.0/0."
  }
}

locals {
  name_prefix = "main-vpc"
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-rt"
    }
  )
}

resource "aws_route" "specific_cidr" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = var.destination_cidr_block
  gateway_id             = aws_internet_gateway.main.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "neptune-demo"

  common_tags = {
    Project     = local.name_prefix
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# ----------------------------------------------------------------------------
# Networking: dedicated VPC with DNS enabled, two private subnets in two AZs
# ----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "neptune_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "neptune_subnet_a" {
  vpc_id                  = aws_vpc.neptune_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.neptune_vpc.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-a"
  })
}

resource "aws_subnet" "neptune_subnet_b" {
  vpc_id                  = aws_vpc.neptune_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.neptune_vpc.cidr_block, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-b"
  })
}

# ----------------------------------------------------------------------------
# Security group: ingress restricted to TCP 8182 from the two private subnets
# ----------------------------------------------------------------------------
resource "aws_security_group" "neptune_sg" {
  name        = "${local.name_prefix}-sg"
  description = "Allow Neptune engine traffic (TCP 8182) only from the two private subnets"
  vpc_id      = aws_vpc.neptune_vpc.id

  ingress {
    description = "Neptune engine port from private subnet A"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.neptune_subnet_a.cidr_block]
  }

  ingress {
    description = "Neptune engine port from private subnet B"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.neptune_subnet_b.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

# ----------------------------------------------------------------------------
# Custom parameter groups (neptune1.3 family) - no default groups used
# ----------------------------------------------------------------------------
resource "aws_neptune_cluster_parameter_group" "neptune_cluster_params" {
  family      = "neptune1.3"
  name        = "${local.name_prefix}-cluster-params"
  description = "Custom cluster parameter group for the ${local.name_prefix} Neptune cluster"

  parameter {
    name  = "neptune_enable_audit_logs"
    value = "0"
  }
}

resource "aws_neptune_parameter_group" "neptune_instance_params" {
  family      = "neptune1.3"
  name        = "${local.name_prefix}-instance-params"
  description = "Custom instance parameter group for the ${local.name_prefix} Neptune cluster"

  parameter {
    name  = "neptune_query_timeout"
    value = "120000"
  }
}

# ----------------------------------------------------------------------------
# Neptune subnet group spanning exactly the two private subnets (two AZs)
# ----------------------------------------------------------------------------
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group spanning two AZs for the ${local.name_prefix} Neptune cluster"
  subnet_ids  = [aws_subnet.neptune_subnet_a.id, aws_subnet.neptune_subnet_b.id]

  tags = local.common_tags
}

# ----------------------------------------------------------------------------
# Neptune cluster (encrypted, deletion protected) and single writer instance
# ----------------------------------------------------------------------------
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                   = "${local.name_prefix}-cluster"
  engine                               = "neptune"
  engine_version                       = "1.3.2.0"
  port                                 = 8182
  neptune_subnet_group_name            = aws_neptune_subnet_group.neptune_subnet_group.name
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.neptune_cluster_params.name
  vpc_security_group_ids               = [aws_security_group.neptune_sg.id]

  storage_encrypted         = true
  deletion_protection       = true
  backup_retention_period   = 7
  preferred_backup_window   = "03:00-04:00"
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-cluster-final"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_neptune_cluster_instance" "neptune_writer" {
  identifier                   = "${local.name_prefix}-writer"
  cluster_identifier           = aws_neptune_cluster.neptune_cluster.cluster_identifier
  engine                       = "neptune"
  instance_class               = "db.r6g.large"
  neptune_parameter_group_name = aws_neptune_parameter_group.neptune_instance_params.name
  neptune_subnet_group_name    = aws_neptune_subnet_group.neptune_subnet_group.name
  promotion_tier               = 1
  auto_minor_version_upgrade   = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

