terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "redshift-example"

  tags = {
    Project   = local.name_prefix
    ManagedBy = "terraform"
  }
}

###############################################################################
# Static provider metadata: Availability Zone selection (never hardcoded)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Network foundation: VPC with DNS enabled + one subnet per AZ
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "redshift_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-subnet-a"
  })
}

resource "aws_subnet" "redshift_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-subnet-b"
  })
}

###############################################################################
# Redshift subnet group spanning both Availability Zones
###############################################################################

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group for the Redshift cluster and managed endpoint access"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = local.tags
}

###############################################################################
# Security group: Redshift port reachable only from inside the VPC
###############################################################################

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Allows Redshift (5439) only from within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "redshift" {
  security_group_id = aws_security_group.redshift.id
  description       = "Redshift port 5439 from the VPC CIDR only"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 5439
  to_port           = 5439
}

resource "aws_vpc_security_group_egress_rule" "redshift" {
  security_group_id = aws_security_group.redshift.id
  description       = "Outbound traffic restricted to the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

###############################################################################
# Redshift cluster (single-node RA3, credentials managed by Secrets Manager)
###############################################################################

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = "exampledb"
  cluster_type       = "single-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 1
  port               = 5439

  # Master credentials are generated and stored by Amazon Redshift in AWS
  # Secrets Manager; no plaintext password exists anywhere in this configuration.
  master_username        = "admin"
  manage_master_password = true

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  enhanced_vpc_routing      = true

  encrypted = true

  automated_snapshot_retention_period = 7

  skip_final_snapshot = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Redshift-managed VPC endpoint access bound to the cluster
###############################################################################

resource "aws_redshift_endpoint_access" "main" {
  endpoint_name          = "${local.name_prefix}-endpoint"
  cluster_identifier     = aws_redshift_cluster.main.id
  subnet_group_name      = aws_redshift_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.redshift.id]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# User-controlled values (all defaulted so terraform apply runs non-interactively)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "example"
}

variable "environment" {
  description = "Environment name (e.g. dev, staging, prod) used for naming and tagging."
  type        = string
  default     = "dev"
}

variable "master_username" {
  description = "Master username for the Redshift cluster (non-secret)."
  type        = string
  default     = "admin"
}

variable "number_of_nodes" {
  description = "Number of compute nodes in the multi-node Redshift cluster."
  type        = number
  default     = 2

  validation {
    condition     = var.number_of_nodes >= 2 && var.number_of_nodes <= 128
    error_message = "A multi-node Redshift cluster requires between 2 and 128 compute nodes."
  }
}

variable "common_tags" {
  description = "Common tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Team      = "data-platform"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata (AZ selection) and locals
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  tags = merge(
    var.common_tags,
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "redshift_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.tags, { Name = "${local.name_prefix}-redshift-az1" })
}

resource "aws_subnet" "redshift_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.tags, { Name = "${local.name_prefix}-redshift-az2" })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group spanning two distinct AZs for the example Redshift cluster."
  subnet_ids  = [aws_subnet.redshift_az1.id, aws_subnet.redshift_az2.id]

  tags = local.tags
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Allows Redshift engine access on TCP 5439 from within the VPC only."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-redshift-sg" })
}

resource "aws_security_group_rule" "redshift_ingress_5439" {
  type              = "ingress"
  from_port         = 5439
  to_port           = 5439
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.redshift.id
}

# -----------------------------------------------------------------------------
# Encryption and master password
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Dedicated KMS key for at-rest encryption of the example Redshift cluster."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

resource "random_password" "redshift_master" {
  length      = 32
  special     = false
  min_upper   = 1
  min_lower   = 1
  min_numeric = 1
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}/redshift/master-password"
  description = "Master password for the example Redshift cluster."
  kms_key_id  = aws_kms_key.redshift.arn

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "redshift" {
  secret_id     = aws_secretsmanager_secret.redshift_master.id
  secret_string = random_password.redshift_master.result
}

# -----------------------------------------------------------------------------
# Example parameter group
# -----------------------------------------------------------------------------

resource "aws_redshift_parameter_group" "example" {
  name        = "${local.name_prefix}-param-group"
  family      = "redshift-1.0"
  description = "Example Redshift parameter group with hardened and demonstration settings."

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  parameter {
    name  = "statement_timeout"
    value = "7200000"
  }

  parameter {
    name = "wlm_json_configuration"
    value = jsonencode([
      {
        query_concurrency = 5
        user_group        = ["etl_users"]
      },
      {
        query_concurrency = 15
        query_group       = ["reporting"]
      },
      {
        auto_wlm = true
      }
    ])
  }

  tags = local.tags
}

# -----------------------------------------------------------------------------
# Redshift cluster
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "example" {
  cluster_identifier                  = "${local.name_prefix}-cluster"
  database_name                       = "exampledb"
  master_username                     = var.master_username
  master_password                     = aws_secretsmanager_secret_version.redshift.secret_string
  node_type                           = "ra3.xlplus"
  cluster_type                        = "multi-node"
  number_of_nodes                     = var.number_of_nodes
  port                                = 5439
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name        = aws_redshift_parameter_group.example.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  publicly_accessible                 = false
  encrypted                           = true
  kms_key_id                          = aws_kms_key.redshift.arn
  automated_snapshot_retention_period = 7
  allow_version_upgrade               = true
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-cluster-final"

  tags = merge(local.tags, { Name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Event notifications for the parameter group
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "redshift_events" {
  name = "${local.name_prefix}-redshift-events"

  tags = local.tags
}

data "aws_iam_policy_document" "redshift_events" {
  statement {
    sid     = "AllowRedshiftServiceToPublish"
    effect  = "Allow"
    actions = ["SNS:Publish"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }

    resources = [aws_sns_topic.redshift_events.arn]
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.redshift_events.json
}

resource "aws_redshift_event_subscription" "parameter_group_events" {
  name          = "${local.name_prefix}-parameter-group-events"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster-parameter-group"
  source_ids    = [aws_redshift_parameter_group.example.name]
  severity      = "INFO"
  enabled       = true

  tags = local.tags

  depends_on = [aws_sns_topic_policy.redshift_events]
}

# -----------------------------------------------------------------------------
# Outputs (non-sensitive only)
# -----------------------------------------------------------------------------

output "cluster_endpoint_address" {
  description = "Connection endpoint address (hostname) of the Redshift cluster, derived from the combined host:port endpoint."
  value       = split(":", aws_redshift_cluster.example.endpoint)[0]
}

output "cluster_endpoint_port" {
  description = "Connection endpoint port of the Redshift cluster."
  value       = aws_redshift_cluster.example.port
}

output "parameter_group_name" {
  description = "Name of the Redshift parameter group attached to the cluster."
  value       = aws_redshift_parameter_group.example.name
}

output "redshift_events_sns_topic_arn" {
  description = "ARN of the SNS topic receiving Redshift parameter group event notifications."
  value       = aws_sns_topic.redshift_events.arn
}

output "redshift_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redshift master password (the secret value itself is never exposed)."
  value       = aws_secretsmanager_secret.redshift_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"
}

variable "additional_tags" {
  description = "Additional tags applied to all tagged resources."
  type        = map(string)
  default     = {}
}

locals {
  username    = "terraform-ssh-user"
  secret_name = "iam/${local.username}/ssh-private-key"

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Purpose     = "ssh-authentication"
    },
    var.additional_tags
  )
}

# Generate the SSH key pair in-configuration so no key material is hardcoded.
resource "tls_private_key" "ssh_user_key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_iam_user" "ssh_user" {
  name = local.username
  path = "/"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# The SSH public key is the sole credential for this IAM user.
resource "aws_iam_user_ssh_key" "ssh_user_key" {
  username   = aws_iam_user.ssh_user.name
  encoding   = "SSH"
  public_key = tls_private_key.ssh_user_key.public_key_openssh
}

resource "aws_secretsmanager_secret" "ssh_user_private_key" {
  name        = local.secret_name
  description = "Private SSH key for IAM user ${local.username}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "ssh_user_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_user_private_key.id
  secret_string = tls_private_key.ssh_user_key.private_key_pem
}

# Least-privilege inline policy: the user may read only its own private key
# from Secrets Manager. No wildcard Action/Resource combinations.
resource "aws_iam_user_policy" "ssh_user_read_own_key" {
  name = "read-own-ssh-private-key"
  user = aws_iam_user.ssh_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadOwnSshPrivateKey"
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.ssh_user_private_key.arn
      }
    ]
  })
}

output "iam_user_name" {
  description = "Name of the IAM user."
  value       = aws_iam_user.ssh_user.name
}

output "iam_user_arn" {
  description = "ARN of the IAM user."
  value       = aws_iam_user.ssh_user.arn
}

output "ssh_key_fingerprint" {
  description = "MD5 fingerprint of the SSH public key uploaded to the IAM user."
  value       = aws_iam_user_ssh_key.ssh_user_key.fingerprint
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the SSH private key."
  value       = aws_secretsmanager_secret.ssh_user_private_key.arn
  sensitive   = true
}

