terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Source bucket: the bucket whose storage class analytics will be analyzed.
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "my_bucket" {
  bucket = "mybucket"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# Destination bucket: receives the storage class analytics export reports.
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "analytics_destination" {
  bucket = "mybucket-analytics-destination"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "analytics_destination" {
  bucket = aws_s3_bucket.analytics_destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "analytics_destination" {
  bucket = aws_s3_bucket.analytics_destination.id

  # SSE-S3 (AES256), not SSE-KMS, so the S3 analytics export can write
  # report objects without requiring a KMS key grant.
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "analytics_destination" {
  bucket = aws_s3_bucket.analytics_destination.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# Bucket policy on the destination bucket allowing the S3 service principal
# to deliver analytics export reports. Permission is limited to s3:PutObject
# and is scoped with the source bucket ARN and the bucket-owner-full-control
# ACL condition required by AWS for analytics exports.
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "analytics_destination" {
  bucket = aws_s3_bucket.analytics_destination.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServiceAnalyticsExportPutObject"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = aws_s3_bucket.analytics_destination.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.my_bucket.arn
          }
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.analytics_destination,
  ]
}

# ---------------------------------------------------------------------------
# Storage class analytics covering the ENTIRE source bucket (no filter block)
# with CSV reports exported to the destination bucket, referenced by its
# Terraform resource address (never a hardcoded bucket-name string).
# Export nesting follows the provider schema:
#   storage_class_analysis -> data_export -> destination -> s3_bucket_destination
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_analytics_configuration" "entire_bucket" {
  bucket = aws_s3_bucket.my_bucket.bucket
  name   = "entire-bucket"

  # No filter block: the analysis covers the entire bucket.

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          format     = "CSV"
          bucket_arn = aws_s3_bucket.analytics_destination.arn
          prefix     = "analytics"
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket.analytics_destination,
    aws_s3_bucket_public_access_block.analytics_destination,
    aws_s3_bucket_server_side_encryption_configuration.analytics_destination,
    aws_s3_bucket_policy.analytics_destination,
  ]
}

