}

locals {
  website_origin   = "https://domain.com"
  bucket_name_base = "domain-com-website-assets"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "website_assets" {
  bucket = "${local.bucket_name_base}-${random_id.bucket_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "website_assets" {
  bucket = aws_s3_bucket.website_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "website_assets" {
  bucket = aws_s3_bucket.website_assets.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "website_assets" {
  bucket = aws_s3_bucket.website_assets.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "website_assets" {
  bucket = aws_s3_bucket.website_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_cors_configuration" "website_assets" {
  bucket = aws_s3_bucket.website_assets.id

  cors_rule {
    allowed_methods = ["GET", "POST"]
    allowed_origins = [local.website_origin]
    allowed_headers = ["*"]
    expose_headers  = ["ETag", "Content-Length", "Content-Type"]
    max_age_seconds = 3000
  }

  depends_on = [
    aws_s3_bucket_public_access_block.website_assets,
    aws_s3_bucket_ownership_controls.website_assets,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
