provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Non-sensitive tags applied to all payment configuration resources."
  type        = map(string)
  default = {
    Environment = "example"
    ManagedBy   = "terraform"
    Purpose     = "payment-configuration"
  }
}

locals {
  bucket_name        = "payment-config-${random_id.suffix.hex}"
  payment_config_key = "configs/payment-config.json"

  # Example payment configuration document.
  # Contains non-sensitive values only; credentials are referenced by secret ARN,
  # never by value.
  payment_config = {
    gateway_provider           = "acme-payments"
    environment                = "sandbox"
    supported_currencies       = ["USD", "EUR", "GBP"]
    gateway_api_key_secret_arn = aws_secretsmanager_secret.payment_gateway.arn
  }

  common_tags = merge(var.tags, {
    Component = "payment-configuration"
  })
}

resource "random_id" "suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# S3 bucket storing payment configuration files
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "payment_config_bucket" {
  bucket = local.bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "payment_config_bucket" {
  bucket = aws_s3_bucket.payment_config_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "payment_config_bucket" {
  bucket = aws_s3_bucket.payment_config_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "payment_config_bucket" {
  bucket = aws_s3_bucket.payment_config_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "payment_config_bucket" {
  bucket = aws_s3_bucket.payment_config_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Example payment configuration object
# -----------------------------------------------------------------------------
resource "aws_s3_object" "payment_config" {
  bucket       = aws_s3_bucket.payment_config_bucket.id
  key          = local.payment_config_key
  content      = jsonencode(local.payment_config)
  content_type = "application/json"
  tags         = local.common_tags

  depends_on = [
    aws_s3_bucket_public_access_block.payment_config_bucket,
    aws_s3_bucket_ownership_controls.payment_config_bucket,
    aws_s3_bucket_server_side_encryption_configuration.payment_config_bucket,
    aws_s3_bucket_versioning.payment_config_bucket,
  ]
}

# -----------------------------------------------------------------------------
# Payment gateway credentials secret
# NOTE: the version below holds a placeholder value only. Real credentials must
# be injected out-of-band via a secure mechanism; no plaintext secret values are
# referenced by any other resource in this configuration.
# -----------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "payment_gateway" {
  name = "payment-gateway-credentials-${random_id.suffix.hex}"
  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "payment_gateway" {
  secret_id = aws_secretsmanager_secret.payment_gateway.id

  secret_string = jsonencode({
    api_key = "REPLACE_WITH_SECURE_VALUE"
  })
}

# -----------------------------------------------------------------------------
# Least-privilege IAM access for payment configuration consumers
# -----------------------------------------------------------------------------
resource "aws_iam_role" "payment_config_consumer" {
  name = "payment-config-consumer-role"
  tags = local.common_tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "payment_config_read" {
  name = "payment-config-consumer-read"
  tags = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListPaymentConfigPrefix"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.payment_config_bucket.arn
        Condition = {
          StringLike = {
            "s3:prefix" = "configs/*"
          }
        }
      },
      {
        Sid      = "ReadPaymentConfigObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "${aws_s3_bucket.payment_config_bucket.arn}/configs/*"
      },
      {
        Sid      = "ReadPaymentGatewaySecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = aws_secretsmanager_secret.payment_gateway.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "payment_config_read" {
  role       = aws_iam_role.payment_config_consumer.name
  policy_arn = aws_iam_policy.payment_config_read.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "payment_config_bucket_arn" {
  description = "ARN of the S3 bucket holding the payment configuration."
  value       = aws_s3_bucket.payment_config_bucket.arn
}

output "payment_config_object_key" {
  description = "S3 object key of the example payment configuration document."
  value       = aws_s3_object.payment_config.key
}

