      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    Environment = "dev"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

locals {
  bucket_name = "tf-unversioned-secure-${random_id.suffix.hex}"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "main" {
  bucket = local.bucket_name

  tags = var.tags

  # Versioning is intentionally left disabled per requirements (no
  # aws_s3_bucket_versioning resource is declared), so this lifecycle
  # guard is the only protection against accidental destruction.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.main]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (all defaulted so terraform apply runs unattended)
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used in resource names and tags (must be lowercase)."
  type        = string
  default     = "classroom"
}

variable "source_repo_url" {
  description = "GitHub repository containing the assignment/grader source that CodeBuild checks out."
  type        = string
  default     = "https://github.com/octocat/Hello-World.git"
}

variable "default_student_repo_url" {
  description = "Optional student submission repository to grade when a trigger does not supply one. Leave empty to grade the checked out assignment source."
  type        = string
  default     = ""
}

variable "github_token" {
  description = "GitHub access token stored in Secrets Manager so CodeBuild can clone private student repositories. Override with a real token in production; the default is only a placeholder."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_REAL_GITHUB_TOKEN"
}

variable "grading_schedule" {
  description = "EventBridge cron expression for scheduled batch grading runs."
  type        = string
  default     = "cron(0 6 * * ? *)"
}

# -----------------------------------------------------------------------------
# Static lookups and locals
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

locals {
  name_prefix         = "cs-autograder-${var.environment}"
  results_bucket_name = "${local.name_prefix}-results-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Project     = "cs-autograder"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# S3 results bucket (grading results, logs, and artifacts)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "autograder_results" {
  bucket = local.results_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  depends_on = [aws_s3_bucket_public_access_block.autograder_results]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })
}

# -----------------------------------------------------------------------------
# DynamoDB grades table (submission/grade metadata, idempotent re-runs)
# -----------------------------------------------------------------------------

resource "aws_dynamodb_table" "grades" {
  name         = "${local.name_prefix}-grades"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "submission_id"

  attribute {
    name = "submission_id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# GitHub access token secret
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "github_token" {
  name                    = "${local.name_prefix}-github-token"
  description             = "GitHub access token used by the autograder to clone private student repositories."
  recovery_window_in_days = 0
  tags                    = local.common_tags
}

resource "aws_secretsmanager_secret_version" "github_token" {
  secret_id     = aws_secretsmanager_secret.github_token.id
  secret_string = var.github_token
}

# -----------------------------------------------------------------------------
# CloudWatch log groups (auditable grading runs)
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = "/aws/codebuild/${local.name_prefix}-build"
  retention_in_days = 30
  tags              = local.common_tags
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${local.name_prefix}-start-grading"
  retention_in_days = 30
  tags              = local.common_tags
}

# -----------------------------------------------------------------------------
# IAM roles and least-privilege policies
# -----------------------------------------------------------------------------

resource "aws_iam_role" "codebuild_role" {
  name = "${local.name_prefix}-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codebuild_autograder" {
  name = "${local.name_prefix}-codebuild-policy"
  role = aws_iam_role.codebuild_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListResultsBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
        ]
        Resource = [
          aws_s3_bucket.autograder_results.arn,
        ]
      },
      {
        Sid    = "ReadWriteGradingResults"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
        ]
        Resource = [
          "${aws_s3_bucket.autograder_results.arn}/results/*",
        ]
      },
      {
        Sid    = "WriteBuildLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*",
        ]
      },
      {
        Sid    = "ReadGitHubToken"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
        ]
        Resource = [
          aws_secretsmanager_secret.github_token.arn,
        ]
      },
      {
        Sid    = "RecordGrades"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
        ]
        Resource = [
          aws_dynamodb_table.grades.arn,
        ]
      },
    ]
  })
}

resource "aws_iam_role" "lambda_role" {
  name = "${local.name_prefix}-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "lambda_start_grading" {
  name = "${local.name_prefix}-lambda-policy"
  role = aws_iam_role.lambda_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartAutograderBuild"
        Effect   = "Allow"
        Action   = ["codebuild:StartBuild"]
        Resource = [aws_codebuild_project.autograder.arn]
      },
      {
        Sid    = "WriteLambdaLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          "${aws_cloudwatch_log_group.lambda_logs.arn}:*",
        ]
      },
    ]
  })
}

# -----------------------------------------------------------------------------
# CodeBuild autograder project (AWS-managed environment, direct GitHub access)
# -----------------------------------------------------------------------------

resource "aws_codebuild_project" "autograder" {
  name           = "${local.name_prefix}-build"
  description    = "Runs student submissions through the CS class autograder and stores machine-readable results"
  service_role   = aws_iam_role.codebuild_role.arn
  build_timeout  = 30

  source {
    type            = "GITHUB"
    location        = var.source_repo_url
    git_clone_depth = 1
    buildspec       = <<-BUILDSPEC
      version: 0.2

      env:
        shell: bash

      phases:
        install:
          runtime-versions:
            python: 3.12
          commands:
            - echo "Installing the assignment grading toolchain"
            - python3 -m pip install --upgrade pip
            - python3 -m pip install pytest pytest-json-report

        pre_build:
          commands:
            - |
              git config --global credential.helper '!f() { echo username=x-access-token; echo password=$GITHUB_TOKEN; }; f'
            - echo "Grading source revision $CODEBUILD_RESOLVED_SOURCE_VERSION"
            - |
              if [ -n "$STUDENT_REPO_URL" ]; then
                echo "Cloning the private student submission repository"
                git clone --depth 1 "$STUDENT_REPO_URL" "$CODEBUILD_SRC_DIR/student_code"
              else
                echo "No student repository supplied - grading the checked out assignment source"
              fi

        build:
          commands:
            - echo "Executing the grader against the student code"
            - |
              set +e
              if [ -d "$CODEBUILD_SRC_DIR/student_code" ]; then
                (cd "$CODEBUILD_SRC_DIR/student_code" && python3 -m pytest --json-report --json-report-file="$CODEBUILD_SRC_DIR/results.json")
              else
                python3 -m pytest --json-report --json-report-file="$CODEBUILD_SRC_DIR/results.json"
              fi
              GRADER_EXIT_CODE=$?
              set -e
              if [ "$GRADER_EXIT_CODE" -eq 0 ]; then
                GRADE_STATUS="PASSED"
              else
                GRADE_STATUS="FAILED"
              fi
              echo "$GRADE_STATUS" > "$CODEBUILD_SRC_DIR/grade_status.txt"
              echo "$GRADER_EXIT_CODE" > "$CODEBUILD_SRC_DIR/grader_exit_code.txt"
              echo "Grader finished with status $GRADE_STATUS"

        post_build:
          commands:
            - GRADE_STATUS=$(cat "$CODEBUILD_SRC_DIR/grade_status.txt")
            - GRADER_EXIT_CODE=$(cat "$CODEBUILD_SRC_DIR/grader_exit_code.txt")
            - |
              if [ ! -f "$CODEBUILD_SRC_DIR/results.json" ]; then
                printf '{"submission_id": "%s", "status": "%s", "grader_exit_code": "%s"}' "$CODEBUILD_BUILD_ID" "$GRADE_STATUS" "$GRADER_EXIT_CODE" > "$CODEBUILD_SRC_DIR/results.json"
              fi
            - |
              printf '{"submission_id": {"S": "%s"}, "status": {"S": "%s"}, "build_id": {"S": "%s"}, "graded_at": {"S": "%s"}}' "$CODEBUILD_BUILD_ID" "$GRADE_STATUS" "$CODEBUILD_BUILD_ID" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$CODEBUILD_SRC_DIR/grade_record.json"
            - aws s3 cp "$CODEBUILD_SRC_DIR/results.json" "s3://$RESULTS_BUCKET/results/$CODEBUILD_BUILD_ID/results.json"
            - aws s3 cp "$CODEBUILD_SRC_DIR/grade_record.json" "s3://$RESULTS_BUCKET/results/$CODEBUILD_BUILD_ID/grade_record.json"
            - aws dynamodb put-item --table-name "$GRADES_TABLE" --item "file://$CODEBUILD_SRC_DIR/grade_record.json"
            - echo "Grading results uploaded for submission $CODEBUILD_BUILD_ID"

      artifacts:
        files:
          - results.json
          - grade_record.json
    BUILDSPEC
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "RESULTS_BUCKET"
      value = aws_s3_bucket.autograder_results.id
    }

    environment_variable {
      name  = "GRADES_TABLE"
      value = aws_dynamodb_table.grades.name
    }

    environment_variable {
      name  = "STUDENT_REPO_URL"
      value = var.default_student_repo_url
    }

    environment_variable {
      name  = "GITHUB_TOKEN"
      type  = "SECRETS_MANAGER"
      value = aws_secretsmanager_secret.github_token.arn
    }
  }

  artifacts {
    artifact_identifier = "GradingResults"
    type                = "S3"
    location            = aws_s3_bucket.autograder_results.id
    name                = "grading-results"
    path                = "results"
    namespace_type      = "BUILD_ID"
    packaging           = "NONE"
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Lambda trigger (codebuild:StartBuild)
# -----------------------------------------------------------------------------

data "archive_file" "start_grading_lambda" {
  type        = "zip"
  output_path = "${path.module}/build/start_grading_lambda.zip"

  source {
    filename = "main.py"
    content  = <<-PYTHON
    import json
    import os

    import boto3

    codebuild = boto3.client("codebuild")


    def build_overrides(repo_url):
        return [
            {
                "name": "RESULTS_BUCKET",
                "value": os.environ["RESULTS_BUCKET"],
                "type": "PLAINTEXT",
            },
            {
                "name": "GRADES_TABLE",
                "value": os.environ["GRADES_TABLE"],
                "type": "PLAINTEXT",
            },
            {
                "name": "GITHUB_TOKEN",
                "value": os.environ["GITHUB_TOKEN_SECRET_ARN"],
                "type": "SECRETS_MANAGER",
            },
            {
                "name": "STUDENT_REPO_URL",
                "value": repo_url,
                "type": "PLAINTEXT",
            },
        ]


    def handler(event, context):
        default_repo = os.environ.get("DEFAULT_STUDENT_REPO_URL", "")
        student_repo = default_repo
        source_version = None

        if isinstance(event, dict):
            detail = event.get("detail")
            if isinstance(detail, dict):
                student_repo = detail.get("student_repo_url") or student_repo
                source_version = detail.get("commit") or source_version

            body = event.get("body")
            if body:
                try:
                    payload = json.loads(body)
                except (TypeError, ValueError):
                    payload = {}
                if isinstance(payload, dict):
                    detail = payload.get("detail")
                    if isinstance(detail, dict):
                        student_repo = detail.get("student_repo_url") or student_repo
                        source_version = detail.get("commit") or source_version
                    student_repo = payload.get("student_repo_url") or student_repo
                    source_version = payload.get("commit") or source_version
                    repository = payload.get("repository")
                    if isinstance(repository, dict):
                        student_repo = (
                            repository.get("clone_url")
                            or repository.get("html_url")
                            or student_repo
                        )

        params = {
            "projectName": os.environ["CODEBUILD_PROJECT_NAME"],
            "environmentVariablesOverride": build_overrides(student_repo or ""),
        }
        if source_version:
            params["sourceVersion"] = str(source_version)

        response = codebuild.start_build(**params)
        build = response.get("build") or {}

        return {
            "statusCode": 202,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps(
                {
                    "buildId": build.get("id"),
                    "studentRepo": student_repo or None,
                    "message": "Autograder build started",
                }
            ),
        }
    PYTHON
  }
}

resource "aws_lambda_function" "start_grading" {
  function_name = "${local.name_prefix}-start-grading"
  description   = "Starts the autograder CodeBuild run for a submission"
  role          = aws_iam_role.lambda_role.arn
  handler       = "main.handler"
  runtime       = "python3.12"
  timeout       = 30
  memory_size   = 256

  filename         = data.archive_file.start_grading_lambda.output_path
  source_code_hash = data.archive_file.start_grading_lambda.output_base64sha256

  environment {
    variables = {
      CODEBUILD_PROJECT_NAME   = aws_codebuild_project.autograder.name
      DEFAULT_STUDENT_REPO_URL = var.default_student_repo_url
      RESULTS_BUCKET           = aws_s3_bucket.autograder_results.id
      GRADES_TABLE             = aws_dynamodb_table.grades.name
      GITHUB_TOKEN_SECRET_ARN  = aws_secretsmanager_secret.github_token.arn
    }
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# HTTP API on-demand trigger (POST /grade, GitHub webhook compatible)
# -----------------------------------------------------------------------------

resource "aws_apigatewayv2_api" "grading_api" {
  name          = "${local.name_prefix}-api"
  protocol_type = "HTTP"
  description   = "On-demand and GitHub webhook entry point for the CS class autograder"
  tags          = local.common_tags
}

resource "aws_apigatewayv2_integration" "start_grading" {
  api_id                 = aws_apigatewayv2_api.grading_api.id
  description            = "Proxy integration to the start_grading Lambda"
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.start_grading.invoke_arn
  integration_method     = "POST"
  payload_format_version = "2.0"
}

resource "aws_apigatewayv2_route" "grade" {
  api_id    = aws_apigatewayv2_api.grading_api.id
  route_key = "POST /grade"
  target    = "integrations/${aws_apigatewayv2_integration.start_grading.id}"
}

resource "aws_apigatewayv2_stage" "grading" {
  api_id      = aws_apigatewayv2_api.grading_api.id
  name        = "prod"
  auto_deploy = true
  tags        = local.common_tags
}

resource "aws_lambda_permission" "allow_api_gateway" {
  statement_id  = "AllowExecutionFromApiGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.start_grading.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.grading_api.execution_arn}/*/POST/grade"
}

# -----------------------------------------------------------------------------
# Scheduled batch trigger (EventBridge cron)
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "nightly_grading" {
  name                = "${local.name_prefix}-nightly-schedule"
  description         = "Scheduled batch grading runs for the CS class autograder"
  schedule_expression = var.grading_schedule
  tags                = local.common_tags
}

resource "aws_cloudwatch_event_target" "nightly_grading" {
  rule      = aws_cloudwatch_event_rule.nightly_grading.name
  target_id = "${local.name_prefix}-start-grading"
  arn       = aws_lambda_function.start_grading.arn
}

resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.start_grading.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.nightly_grading.arn
}

# -----------------------------------------------------------------------------
# Outputs for instructors
# -----------------------------------------------------------------------------

output "results_bucket_name" {
  description = "Name of the S3 bucket storing grading results, logs, and artifacts."
  value       = aws_s3_bucket.autograder_results.id
}

output "codebuild_project_name" {
  description = "Name of the CodeBuild project that runs the autograder."
  value       = aws_codebuild_project.autograder.name
}

output "grades_table_name" {
  description = "Name of the DynamoDB table tracking submission grades."
  value       = aws_dynamodb_table.grades.name
}

output "grading_api_invoke_url" {
  description = "Invoke URL of the grading API. Point the GitHub webhook at this URL plus /grade (POST) to trigger grading on push events."
  value       = aws_apigatewayv2_stage.grading.invoke_url
}

output "github_token_secret_arn" {
  description = "Secrets Manager ARN where the GitHub access token used to clone private student repositories is stored."
  value       = aws_secretsmanager_secret.github_token.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

variable "course_name" {
  description = "Course identifier used for resource naming and tagging (e.g. cs101)."
  type        = string
  default     = "cs101"
}

variable "github_repo_url" {
  description = "GitHub repository holding the student submissions (polled for the latest archive)."
  type        = string
  default     = "https://github.com/example-org/cs101-submissions"
}

variable "github_branch" {
  description = "Branch of the submission repository to poll."
  type        = string
  default     = "main"
}

variable "codebuild_image" {
  description = "Managed CodeBuild image used to execute student code inside the isolated VPC."
  type        = string
  default     = "aws/codebuild/standard:7.0"
}

variable "grading_schedule" {
  description = "EventBridge schedule expression that drives periodic grading runs."
  type        = string
  default     = "rate(15 minutes)"
}

locals {
  name_prefix            = substr(lower(replace(var.course_name, "/[^a-zA-Z0-9-]/", "-")), 0, 24)
  bucket_name            = "${local.name_prefix}-autograder-results-${data.aws_caller_identity.current.account_id}"
  codebuild_project_name = "${local.name_prefix}-autograder"
  codebuild_log_group    = "/aws/codebuild/${local.codebuild_project_name}"
  ingestion_lambda_name  = "${local.name_prefix}-github-ingestion"
  ingestion_log_group    = "/aws/lambda/${local.ingestion_lambda_name}"
  private_subnet_cidrs   = ["10.0.1.0/24", "10.0.2.0/24"]

  common_tags = {
    Course    = var.course_name
    Purpose   = "autograder"
    ManagedBy = "terraform"
  }

  # Inline buildspec (required for the S3 source): runs the instructor test
  # harness against the student code and copies all outcome files to
  # s3://<results-bucket>/results/<build-id>/ through the S3 gateway endpoint.
  autograder_buildspec = <<-BUILDSPEC
    version: 0.2

    phases:
      pre_build:
        commands:
          - echo "Autograder build $CODEBUILD_BUILD_ID starting at $(date -u '+%Y-%m-%dT%H:%M:%SZ')"
          - echo "Student submission contents:"
          - ls -la "$CODEBUILD_SRC_DIR"
          - mkdir -p results
      build:
        commands:
          - |
            if [ -f run_tests.sh ]; then
              echo "Executing instructor test harness (run_tests.sh)"
              bash run_tests.sh > results/test_output.txt 2>&1
              if [ $? -eq 0 ]; then
                echo "PASSED" > results/grade.txt
              else
                echo "FAILED" > results/grade.txt
              fi
            else
              echo "NO_HARNESS: no run_tests.sh found in the submission" > results/grade.txt
            fi
          - cat results/grade.txt
      post_build:
        commands:
          - echo "build_id=$CODEBUILD_BUILD_ID" > results/build_metadata.txt
          - echo "course=$COURSE_NAME" >> results/build_metadata.txt
          - echo "completed_at=$(date -u '+%Y-%m-%dT%H:%M:%SZ')" >> results/build_metadata.txt
          - echo "Uploading grading results to s3://$RESULTS_BUCKET/results/$CODEBUILD_BUILD_ID/"
          - aws s3 cp results/ "s3://$RESULTS_BUCKET/results/$CODEBUILD_BUILD_ID/" --recursive --sse AES256
  BUILDSPEC

  ingestion_lambda_source = <<-PYEOF
    """Ingestion Lambda for the course autograder.

    Runs OUTSIDE the isolated VPC because it needs internet access to reach
    GitHub. It downloads the latest student submission archive from the
    configured GitHub repository, stores it under the submissions/ prefix of
    the autograder bucket, and starts the isolated CodeBuild grading run.
    Network isolation applies only to the CodeBuild execution environment
    that runs student code.
    """

    import json
    import os
    import urllib.request

    import boto3

    S3_BUCKET = os.environ["RESULTS_BUCKET"]
    CODEBUILD_PROJECT = os.environ["CODEBUILD_PROJECT"]
    GITHUB_REPO_URL = os.environ["GITHUB_REPO_URL"]
    GITHUB_BRANCH = os.environ.get("GITHUB_BRANCH", "main")
    GITHUB_TOKEN_SECRET_ARN = os.environ.get("GITHUB_TOKEN_SECRET_ARN", "")
    SUBMISSIONS_KEY = "submissions/latest.zip"


    def _github_token():
        """Optionally read a GitHub token from Secrets Manager (private repos)."""
        if not GITHUB_TOKEN_SECRET_ARN:
            return None
        client = boto3.client("secretsmanager")
        try:
            response = client.get_secret_value(SecretId=GITHUB_TOKEN_SECRET_ARN)
        except client.exceptions.ResourceNotFoundException:
            return None
        return response.get("SecretString")


    def _download_submission_archive():
        """Download the zip archive of the configured repository branch."""
        repo_path = GITHUB_REPO_URL.rstrip("/").split("github.com/")[-1]
        archive_url = "https://github.com/{0}/archive/refs/heads/{1}.zip".format(repo_path, GITHUB_BRANCH)
        request = urllib.request.Request(archive_url)
        request.add_header("User-Agent", "cs-autograder-ingestion")
        token = _github_token()
        if token:
            request.add_header("Authorization", "Bearer {0}".format(token))
        with urllib.request.urlopen(request, timeout=60) as response:
            if response.getcode() != 200:
                raise RuntimeError("Unexpected HTTP status fetching submission archive: {0}".format(response.getcode()))
            return response.read()


    def handler(event, context):
        archive = _download_submission_archive()
        s3 = boto3.client("s3")
        s3.put_object(
            Bucket=S3_BUCKET,
            Key=SUBMISSIONS_KEY,
            Body=archive,
            ContentType="application/zip",
            ServerSideEncryption="AES256",
        )
        codebuild = boto3.client("codebuild")
        build = codebuild.start_build(projectName=CODEBUILD_PROJECT)
        result = {
            "message": "Submission ingested; grading build started",
            "bucket": S3_BUCKET,
            "key": SUBMISSIONS_KEY,
            "build_id": build["build"]["id"],
        }
        print(json.dumps(result))
        return {"statusCode": 200, "body": json.dumps(result)}
  PYEOF
}

# ---------------------------------------------------------------------------
# Static provider metadata / well-known lookups only
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_prefix_list" "s3" {
  filter {
    name   = "prefix-list-name"
    values = ["com.amazonaws.${data.aws_region.current.name}.s3"]
  }
}

# ---------------------------------------------------------------------------
# Network foundation: isolated VPC with private subnets only.
# Deliberately NO internet gateway, NAT gateway, or public subnet exists in
# this configuration, so there is zero network path to the internet.
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-autograder-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name          = "${local.name_prefix}-private-${count.index + 1}"
    NetworkAccess = "no-internet"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Dedicated route table for the isolated build network. It intentionally
# contains NO routes: only the implicit local VPC route exists. There is no
# 0.0.0.0/0 route to any gateway, so student code executed by CodeBuild can
# never reach the internet.
resource "aws_route_table" "private_isolated" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-isolated"
  })
}

resource "aws_route_table_association" "private_isolated" {
  count          = length(local.private_subnet_cidrs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_isolated.id
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "codebuild_enis" {
  name        = "${local.codebuild_project_name}-enis"
  description = "ENIs of isolated CodeBuild autograder builds. No ingress by design; egress limited to VPC endpoints and S3."
  vpc_id      = aws_vpc.main.id

  # No ingress rules are defined on purpose: nothing may initiate a
  # connection into the environment that runs student code.

  egress {
    description = "HTTPS to VPC-resident interface endpoints (CloudWatch Logs)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description     = "HTTPS to Amazon S3 through the gateway VPC endpoint"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [data.aws_prefix_list.s3.id]
  }

  egress {
    description = "DNS resolution via the VPC resolver"
    from_port   = 53
    to_port     = 53
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "DNS over TCP via the VPC resolver"
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.codebuild_project_name}-enis"
  })
}

# Interface endpoints must accept inbound HTTPS from the CodeBuild ENIs, while
# the CodeBuild group itself stays ingress-free. Both groups are attached to
# the endpoints; security group rules are additive and stateful, so responses
# flow back without any egress rules here.
resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpc-endpoints"
  description = "Accepts inbound HTTPS from the CodeBuild ENI security group to the interface VPC endpoints."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTPS from CodeBuild ENIs"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.codebuild_enis.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-endpoints"
  })
}

# ---------------------------------------------------------------------------
# VPC endpoints: the only network egress paths for the isolated build network
# ---------------------------------------------------------------------------

# S3 gateway endpoint attached to the private route table: lets CodeBuild
# fetch its S3 source and upload grading results without internet access.
# The endpoint policy permits access ONLY to the autograder results bucket.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private_isolated.id]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCodeBuildReadSubmissions"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.codebuild_autograder.arn] }
        Action    = ["s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket"]
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/submissions/*",
        ]
      },
      {
        Sid       = "AllowCodeBuildWriteResults"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.codebuild_autograder.arn] }
        Action    = ["s3:PutObject"]
        Resource  = ["${aws_s3_bucket.autograder_results.arn}/results/*"]
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-endpoint"
  })
}

# CloudWatch Logs interface endpoint with private DNS: lets builds stream
# logs from inside the isolated VPC.
resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [for s in aws_subnet.private : s.id]
  security_group_ids  = [aws_security_group.codebuild_enis.id, aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-logs-endpoint"
  })
}

# ---------------------------------------------------------------------------
# Results bucket: submissions/ (student code drop) and results/ (grades)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "autograder_results" {
  bucket = local.bucket_name

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "autograder_results" {
  bucket                  = aws_s3_bucket.autograder_results.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "AllowCodeBuildReadSubmissions"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.codebuild_autograder.arn] }
        Action    = ["s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket"]
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/submissions/*",
        ]
      },
      {
        Sid       = "AllowCodeBuildWriteResults"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.codebuild_autograder.arn] }
        Action    = ["s3:PutObject"]
        Resource  = ["${aws_s3_bucket.autograder_results.arn}/results/*"]
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.autograder_results]
}

# ---------------------------------------------------------------------------
# CloudWatch Logs (pre-created so the projects only need stream permissions)
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "autograder" {
  name              = local.codebuild_log_group
  retention_in_days = 30

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "github_ingestion" {
  name              = local.ingestion_log_group
  retention_in_days = 30

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# CodeBuild service role (least privilege)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "codebuild_autograder" {
  name = "${local.codebuild_project_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codebuild_autograder" {
  name = "${local.codebuild_project_name}-least-privilege"
  role = aws_iam_role.codebuild_autograder.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadStudentSubmissions"
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket"]
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/submissions/*",
        ]
      },
      {
        Sid      = "WriteGradingResults"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = ["${aws_s3_bucket.autograder_results.arn}/results/*"]
      },
      {
        Sid    = "WriteBuildLogs"
        Effect = "Allow"
        Action = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          aws_cloudwatch_log_group.autograder.arn,
          "${aws_cloudwatch_log_group.autograder.arn}:*",
        ]
      },
      {
        Sid  = "ManageCodeBuildNetworkInterfaces"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeVpcs",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Isolated CodeBuild autograder project
# ---------------------------------------------------------------------------

resource "aws_codebuild_project" "autograder" {
  name               = local.codebuild_project_name
  description        = "Isolated autograder: executes student submissions inside a VPC with no internet path."
  service_role       = aws_iam_role.codebuild_autograder.arn
  project_visibility = "PRIVATE"

  source {
    type     = "S3"
    location = "${aws_s3_bucket.autograder_results.bucket}/submissions/latest.zip"
    buildspec = local.autograder_buildspec
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = var.codebuild_image
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = false

    environment_variable {
      name  = "RESULTS_BUCKET"
      value = aws_s3_bucket.autograder_results.bucket
    }

    environment_variable {
      name  = "COURSE_NAME"
      value = var.course_name
    }
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.autograder.name
    }
  }

  # Student code runs exclusively inside the isolated VPC: private subnets
  # with a route table that has no internet route, and an ENI security group
  # with no ingress and no internet egress.
  vpc_config {
    vpc_id             = aws_vpc.main.id
    subnets            = [for s in aws_subnet.private : s.id]
    security_group_ids = [aws_security_group.codebuild_enis.id]
  }

  tags = merge(local.common_tags, {
    Name = local.codebuild_project_name
  })
}

# ---------------------------------------------------------------------------
# Optional GitHub token for private submission repositories.
# The secret value is managed out-of-band (never in Terraform); the ingestion
# Lambda references it by ARN only and falls back to anonymous access for
# public repositories.
# ---------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "github_token" {
  name        = "autograder/${local.name_prefix}/github-token"
  description = "Optional GitHub access token for private submission repositories. Value is set out-of-band and referenced by ARN only."

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# GitHub ingestion Lambda (NOT attached to the isolated VPC: it needs
# internet access to reach GitHub; isolation applies only to CodeBuild)
# ---------------------------------------------------------------------------

data "archive_file" "ingestion_lambda" {
  type        = "zip"
  output_path = "${path.module}/.archive/${local.ingestion_lambda_name}.zip"

  source {
    filename = "lambda_function.py"
    content  = local.ingestion_lambda_source
  }
}

resource "aws_iam_role" "github_ingestion" {
  name = "${local.ingestion_lambda_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "github_ingestion" {
  name = "${local.ingestion_lambda_name}-least-privilege"
  role = aws_iam_role.github_ingestion.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteIngestionLogs"
        Effect = "Allow"
        Action = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          aws_cloudwatch_log_group.github_ingestion.arn,
          "${aws_cloudwatch_log_group.github_ingestion.arn}:*",
        ]
      },
      {
        Sid      = "UploadSubmissions"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.autograder_results.arn}/submissions/*"
      },
      {
        Sid      = "StartGradingBuild"
        Effect   = "Allow"
        Action   = ["codebuild:StartBuild"]
        Resource = aws_codebuild_project.autograder.arn
      },
      {
        Sid      = "ReadGithubToken"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = aws_secretsmanager_secret.github_token.arn
      },
    ]
  })
}

resource "aws_lambda_function" "github_ingestion" {
  function_name = local.ingestion_lambda_name
  description   = "Fetches the latest submission archive from GitHub, stores it in S3, and starts the isolated grading build."
  role          = aws_iam_role.github_ingestion.arn
  runtime       = "python3.12"
  handler       = "lambda_function.handler"
  timeout       = 300
  memory_size   = 256

  filename         = data.archive_file.ingestion_lambda.output_path
  source_code_hash = data.archive_file.ingestion_lambda.output_base64sha256

  # Intentionally no vpc_config: this function must reach GitHub over the
  # internet. The isolated VPC is reserved for the CodeBuild execution
  # environment that runs student code.
  environment {
    variables = {
      RESULTS_BUCKET          = aws_s3_bucket.autograder_results.bucket
      CODEBUILD_PROJECT       = aws_codebuild_project.autograder.name
      GITHUB_REPO_URL         = var.github_repo_url
      GITHUB_BRANCH           = var.github_branch
      GITHUB_TOKEN_SECRET_ARN = aws_secretsmanager_secret.github_token.arn
    }
  }

  tags = local.common_tags

  depends_on = [aws_cloudwatch_log_group.github_ingestion]
}

# ---------------------------------------------------------------------------
# Trigger: periodic polling schedule, since the isolated build network cannot
# receive GitHub webhooks.
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "autograder_schedule" {
  name                = "${local.codebuild_project_name}-schedule"
  description         = "Periodically polls GitHub for new submissions and starts grading builds."
  schedule_expression = var.grading_schedule

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "github_ingestion" {
  rule = aws_cloudwatch_event_rule.autograder_schedule.name
  arn  = aws_lambda_function.github_ingestion.arn
}

resource "aws_lambda_permission" "eventbridge_invoke" {
  statement_id  = "AllowEventBridgeInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.github_ingestion.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.autograder_schedule.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for resource naming and tags."
  type        = string
  default     = "cat-pictures"
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name          = "${var.project}-${data.aws_caller_identity.current.account_id}"
  upload_function_name = "${var.project}-upload"
  random_function_name = "${var.project}-random-fetch"

  common_tags = {
    Project   = var.project
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Private S3 bucket that stores the cat pictures
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "cat_pictures" {
  bucket = local.bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_cors_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["PUT", "GET"]
    allowed_origins = ["*"]
    expose_headers  = ["etag"]
    max_age_seconds = 3000
  }
}

# ---------------------------------------------------------------------------
# IAM role for both Lambda functions
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${var.project}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "lambda_s3_access" {
  statement {
    sid       = "ListCatPicturesBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.cat_pictures.arn]
  }

  statement {
    sid       = "ReadWriteCatPictureObjects"
    effect    = "Allow"
    actions   = ["s3:PutObject", "s3:GetObject"]
    resources = ["${aws_s3_bucket.cat_pictures.arn}/*"]
  }
}

resource "aws_iam_role_policy" "lambda_s3_access" {
  name   = "${var.project}-lambda-s3-access"
  role   = aws_iam_role.lambda_exec.name
  policy = data.aws_iam_policy_document.lambda_s3_access.json
}

# ---------------------------------------------------------------------------
# Lambda source packages (zipped inline at plan time)
# ---------------------------------------------------------------------------

data "archive_file" "upload" {
  type        = "zip"
  output_path = "${path.module}/build/upload_lambda.zip"

  source {
    filename = "lambda_function.py"
    content  = <<-PY
      import json
      import os
      import uuid

      import boto3

      s3 = boto3.client("s3")
      BUCKET_NAME = os.environ["BUCKET_NAME"]
      URL_TTL_SECONDS = 300
      EXTENSIONS = {
          "image/jpeg": "jpg",
          "image/jpg": "jpg",
          "image/png": "png",
          "image/gif": "gif",
          "image/webp": "webp",
      }


      def lambda_handler(event, context):
          headers = {(key or "").lower(): value for key, value in (event.get("headers") or {}).items()}
          content_type = headers.get("content-type")
          if not content_type or not content_type.lower().startswith("image/"):
              return _json_response(
                  400,
                  {"error": "A Content-Type header of image/* is required to upload a cat picture."},
              )
          extension = EXTENSIONS.get(content_type.lower(), "bin")
          object_key = "uploads/{0}.{1}".format(uuid.uuid4(), extension)
          upload_url = s3.generate_presigned_url(
              "put_object",
              Params={"Bucket": BUCKET_NAME, "Key": object_key, "ContentType": content_type},
              ExpiresIn=URL_TTL_SECONDS,
          )
          return _json_response(
              200,
              {"upload_url": upload_url, "key": object_key, "expires_in": URL_TTL_SECONDS},
          )


      def _json_response(status_code, payload):
          return {
              "statusCode": status_code,
              "headers": {"Content-Type": "application/json"},
              "body": json.dumps(payload),
          }
    PY
  }
}

data "archive_file" "random_fetch" {
  type        = "zip"
  output_path = "${path.module}/build/random_fetch_lambda.zip"

  source {
    filename = "lambda_function.py"
    content  = <<-PY
      import json
      import os
      import random

      import boto3
      from botocore.exceptions import ClientError

      s3 = boto3.client("s3")
      BUCKET_NAME = os.environ["BUCKET_NAME"]
      URL_TTL_SECONDS = 300
      OBJECT_PREFIX = "uploads/"


      def lambda_handler(event, context):
          try:
              listed = s3.list_objects_v2(Bucket=BUCKET_NAME, Prefix=OBJECT_PREFIX)
          except ClientError as exc:
              return _json_response(
                  500,
                  {"error": "Unable to list cat pictures.", "detail": str(exc)},
              )
          objects = listed.get("Contents") or []
          if not objects:
              return _json_response(
                  404,
                  {"error": "No cat pictures available yet. Upload the first one!"},
              )
          chosen_key = random.choice(objects)["Key"]
          image_url = s3.generate_presigned_url(
              "get_object",
              Params={"Bucket": BUCKET_NAME, "Key": chosen_key},
              ExpiresIn=URL_TTL_SECONDS,
          )
          return _json_response(
              200,
              {"image_url": image_url, "key": chosen_key, "expires_in": URL_TTL_SECONDS},
          )


      def _json_response(status_code, payload):
          return {
              "statusCode": status_code,
              "headers": {"Content-Type": "application/json"},
              "body": json.dumps(payload),
          }
    PY
  }
}

# ---------------------------------------------------------------------------
# CloudWatch log groups (pre-created so retention is enforced)
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "upload" {
  name              = "/aws/lambda/${local.upload_function_name}"
  retention_in_days = 14
  tags              = local.common_tags
}

resource "aws_cloudwatch_log_group" "random_fetch" {
  name              = "/aws/lambda/${local.random_function_name}"
  retention_in_days = 14
  tags              = local.common_tags
}

# ---------------------------------------------------------------------------
# Lambda functions
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "upload" {
  function_name = local.upload_function_name
  description   = "Returns short-lived presigned PUT URLs for uploading cat pictures."
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"

  filename         = data.archive_file.upload.output_path
  source_code_hash = data.archive_file.upload.output_base64sha256

  timeout     = 10
  memory_size = 256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic,
    aws_iam_role_policy.lambda_s3_access,
    aws_cloudwatch_log_group.upload,
  ]
}

resource "aws_lambda_function" "random_fetch" {
  function_name = local.random_function_name
  description   = "Returns a presigned GET URL for a randomly selected cat picture."
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"

  filename         = data.archive_file.random_fetch.output_path
  source_code_hash = data.archive_file.random_fetch.output_base64sha256

  timeout     = 10
  memory_size = 256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic,
    aws_iam_role_policy.lambda_s3_access,
    aws_cloudwatch_log_group.random_fetch,
  ]
}

# ---------------------------------------------------------------------------
# API Gateway (HTTP API) routing to the Lambda functions
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_api" "cats" {
  name          = "${var.project}-api"
  protocol_type = "HTTP"

  cors_configuration {
    allow_origins     = ["*"]
    allow_methods     = ["POST", "GET", "OPTIONS"]
    allow_headers     = ["content-type"]
    allow_credentials = false
    max_age           = 300
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_integration" "upload" {
  api_id                 = aws_apigatewayv2_api.cats.id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.upload.invoke_arn
  payload_format_version = "2.0"
  timeout_milliseconds   = 10000
}

resource "aws_apigatewayv2_integration" "random_fetch" {
  api_id                 = aws_apigatewayv2_api.cats.id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.random_fetch.invoke_arn
  payload_format_version = "2.0"
  timeout_milliseconds   = 10000
}

resource "aws_apigatewayv2_route" "upload" {
  api_id    = aws_apigatewayv2_api.cats.id
  route_key = "POST /cats"
  target    = "integrations/${aws_apigatewayv2_integration.upload.id}"
}

resource "aws_apigatewayv2_route" "random_fetch" {
  api_id    = aws_apigatewayv2_api.cats.id
  route_key = "GET /cats/random"
  target    = "integrations/${aws_apigatewayv2_integration.random_fetch.id}"
}

resource "aws_apigatewayv2_stage" "default" {
  api_id      = aws_apigatewayv2_api.cats.id
  name        = "$default"
  auto_deploy = true

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Invoke permissions scoped to the API execution ARN
# ---------------------------------------------------------------------------

resource "aws_lambda_permission" "upload" {
  statement_id  = "AllowApiGatewayInvokeUpload"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.upload.function_name
  principal     = "apigatewayv2.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.cats.execution_arn}/*/POST/cats"
}

resource "aws_lambda_permission" "random_fetch" {
  statement_id  = "AllowApiGatewayInvokeRandomFetch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.random_fetch.function_name
  principal     = "apigatewayv2.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.cats.execution_arn}/*/GET/cats/random"
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "api_invoke_url" {
  description = "Invoke URL of the cat pictures API. POST /cats with an image/* Content-Type returns a presigned upload URL; GET /cats/random returns a presigned URL for a random cat picture."
  value       = aws_apigatewayv2_stage.default.invoke_url
}

output "s3_bucket_name" {
  description = "Name of the private S3 bucket that stores the uploaded cat pictures."
  value       = aws_s3_bucket.cat_pictures.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "ec2-daily-backup"
  environment = "dev"

  common_tags = {
    Project     = local.name_prefix
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Data sources (pure static lookups only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security group (egress-only; no inbound ports required for backup workflow)
# ---------------------------------------------------------------------------

resource "aws_security_group" "instance" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Egress-only security group for the backup-managed EC2 instance"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-sg"
  })
}

# ---------------------------------------------------------------------------
# EC2 instance
# ---------------------------------------------------------------------------

resource "aws_instance" "app" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 20
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name        = "${local.name_prefix}-app"
    Environment = local.environment
    Backup      = "daily"
  })
}

# ---------------------------------------------------------------------------
# KMS key and encrypted backup vault
# ---------------------------------------------------------------------------

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the daily EC2 backup vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backup-key"
  })
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.name_prefix}-backup"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "main" {
  name        = "${local.name_prefix}-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vault"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM role for AWS Backup
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup" {
  name               = "${local.name_prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backup-role"
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# ---------------------------------------------------------------------------
# AWS Backup plan and selection
# ---------------------------------------------------------------------------

resource "aws_backup_plan" "daily" {
  name = "${local.name_prefix}-daily-plan"

  rule {
    rule_name         = "daily_midnight"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 0 * * ? *)"
    start_window      = 60
    completion_window = 360

    lifecycle {
      delete_after = 35
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-daily-plan"
  })
}

resource "aws_backup_selection" "ec2_daily" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "ec2_daily"
  plan_id      = aws_backup_plan.daily.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "daily"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "instance_id" {
  description = "ID of the EC2 instance protected by the daily backup plan"
  value       = aws_instance.app.id
}

output "backup_vault_arn" {
  description = "ARN of the encrypted backup vault"
  value       = aws_backup_vault.main.arn
}

output "backup_plan_id" {
  description = "ID of the daily midnight backup plan"
  value       = aws_backup_plan.daily.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Environment = "prod"
    ManagedBy   = "terraform"
  }
}

locals {
  function_name  = "daily-job-7am-utc"
  rule_name      = "daily-job-7am-utc-schedule"
  target_id      = "daily-job-7am-utc-target"
  log_group_name = "/aws/lambda/${local.function_name}"
}

# Static provider/account metadata used to build least-privilege IAM resource ARNs.
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Lambda source code and deployment package
# ---------------------------------------------------------------------------

resource "local_file" "lambda_handler" {
  filename = "${path.module}/src/main.py"
  content = <<-EOT
    """Daily scheduled job invoked by EventBridge every day at 07:00 UTC."""
    import json
    import logging
    import os

    LOG_LEVEL = os.environ.get("LOG_LEVEL", "INFO")
    logging.basicConfig(level=LOG_LEVEL)
    logger = logging.getLogger(__name__)


    def lambda_handler(event, context):
        """Entry point executed once per day at 07:00 UTC."""
        logger.info(
            "Daily job started (job_name=%s)",
            os.environ.get("JOB_NAME", "daily-job"),
        )
        logger.info("Received event: %s", json.dumps(event, default=str))

        # Placeholder for the actual daily workload.
        logger.info("Daily job finished successfully")

        return {
            "statusCode": 200,
            "body": json.dumps({"message": "daily job completed"}),
        }
    EOT
  file_permission = "0644"
}

resource "archive_file" "daily_job_zip" {
  type        = "zip"
  source_file = local_file.lambda_handler.filename
  output_path = "${path.module}/build/${local.function_name}.zip"
}

# ---------------------------------------------------------------------------
# IAM: execution role with least-privilege CloudWatch Logs permissions
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "daily_job_exec" {
  name               = "${local.function_name}-exec"
  description        = "Execution role for the ${local.function_name} Lambda function."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = merge(var.tags, { Name = "${local.function_name}-exec" })
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}",
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}:*",
    ]
  }
}

resource "aws_iam_role_policy" "daily_job_logging_inline" {
  name   = "${local.function_name}-inline-logging"
  role   = aws_iam_role.daily_job_exec.id
  policy = data.aws_iam_policy_document.lambda_logging.json
}

resource "aws_iam_policy" "daily_job_logging" {
  name        = "${local.function_name}-logging"
  description = "Least-privilege CloudWatch Logs permissions for the daily job Lambda."
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = merge(var.tags, { Name = "${local.function_name}-logging" })
}

resource "aws_iam_role_policy_attachment" "daily_job_logging" {
  role       = aws_iam_role.daily_job_exec.name
  policy_arn = aws_iam_policy.daily_job_logging.arn
}

# ---------------------------------------------------------------------------
# CloudWatch Logs group created ahead of the function so Lambda never
# auto-creates an unmanaged log group.
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "daily_job" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = merge(var.tags, { Name = local.log_group_name })
}

# ---------------------------------------------------------------------------
# Lambda function
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "daily_job" {
  function_name    = local.function_name
  description      = "Daily job triggered by EventBridge every day at 07:00 UTC."
  role             = aws_iam_role.daily_job_exec.arn
  handler          = "main.lambda_handler"
  runtime          = "python3.12"
  filename         = archive_file.daily_job_zip.output_path
  source_code_hash = archive_file.daily_job_zip.output_base64sha256
  memory_size      = 128
  timeout          = 60

  environment {
    variables = {
      LOG_LEVEL = "INFO"
      JOB_NAME  = "daily-7am-utc-job"
    }
  }

  depends_on = [
    aws_cloudwatch_log_group.daily_job,
    aws_iam_role_policy.daily_job_logging_inline,
    aws_iam_role_policy_attachment.daily_job_logging,
  ]

  tags = merge(var.tags, { Name = local.function_name })
}

# ---------------------------------------------------------------------------
# EventBridge daily 07:00 UTC schedule
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "daily_schedule" {
  name                = local.rule_name
  description         = "Fires the daily job every day at 07:00 UTC."
  schedule_expression = "cron(0 7 * * ? *)"
  state               = "ENABLED"

  tags = merge(var.tags, { Name = local.rule_name })
}

resource "aws_cloudwatch_event_target" "daily_job" {
  rule      = aws_cloudwatch_event_rule.daily_schedule.name
  target_id = local.target_id
  arn       = aws_lambda_function.daily_job.arn
}

resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowEventBridgeInvokeDailyJob"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_job.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_schedule.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_exec" {
  name = "cron-lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_cloudwatch_event_rule" "cron" {
  name                = "cron"
  description         = "Triggers every day at 07:00 UTC"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_lambda_function" "cron" {
  function_name = "cron-lambda-function"
  filename      = "./supplement/lambda_func.zip"
  handler       = "lambda_func.lambda_handler"
  runtime       = "python3.12"
  role          = aws_iam_role.lambda_exec.arn

  depends_on = [aws_iam_role_policy_attachment.lambda_basic_execution]
}

resource "aws_cloudwatch_event_target" "cron" {
  rule      = aws_cloudwatch_event_rule.cron.name
  target_id = "cron-lambda-target"
  arn       = aws_lambda_function.cron.arn
}

resource "aws_lambda_permission" "cron" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  s3_origin_id = "s3_video_content_origin"
}

resource "aws_s3_bucket" "video_content" {
  bucket = "netflix-video-content-s3-origin"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_cloudfront_origin_access_control" "s3_oac" {
  name                              = "s3-video-content-origin-oac"
  description                       = "Origin access control for the S3 video content origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_cache_policy" "caching_optimized" {
  name        = "video-content-caching-optimized"
  comment     = "Caching policy for S3 video content (GET/HEAD)"
  min_ttl     = 1
  default_ttl = 86400
  max_ttl     = 31536000

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }

    headers_config {
      header_behavior = "none"
    }

    query_strings_config {
      query_string_behavior = "none"
    }

    enable_accept_encoding_brotli = true
    enable_accept_encoding_gzip   = true
  }
}

resource "aws_cloudfront_distribution" "s3_distribution" {
  enabled     = true
  price_class = "PriceClass_200"
  comment     = "CloudFront distribution serving video content from S3"

  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.s3_oac.id
    origin_id                = local.s3_origin_id
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = local.s3_origin_id
    cache_policy_id        = aws_cloudfront_cache_policy.caching_optimized.id
    viewer_protocol_policy = "allow-all"
    compress               = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name = "s3-video-content-distribution"
  }
}

resource "aws_s3_bucket_policy" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontServicePrincipalRead"
        Effect    = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.video_content.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.s3_distribution.arn
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.video_content]
}

resource "aws_route53_zone" "main" {
  name = "netflix.com"
}

resource "aws_route53_record" "apex" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "netflix.com"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.s3_distribution.domain_name
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "www" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.netflix.com"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.s3_distribution.domain_name
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  domain_name = "test-video-stream.com"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-video-stream-vpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-video-stream-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.5.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-video-stream-public-b"
  }
}

resource "aws_subnet" "public_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.6.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-video-stream-public-c"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-video-stream-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "test-video-stream-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_c" {
  subnet_id      = aws_subnet.public_c.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security
# ---------------------------------------------------------------------------

resource "aws_security_group" "main" {
  name        = "test-video-stream-sg"
  description = "Shared security group for the ALB and EC2 instance"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "test-video-stream-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "http_from_vpc" {
  security_group_id = aws_security_group.main.id
  description       = "Allow HTTP from the VPC CIDR range"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_egress_rule" "http_to_all" {
  security_group_id = aws_security_group.main.id
  description       = "Allow HTTP to any destination"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

# ---------------------------------------------------------------------------
# Compute
# ---------------------------------------------------------------------------

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "aws_instance" "app" {
  ami                    = data.aws_ami.ubuntu.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public_a.id
  vpc_security_group_ids = [aws_security_group.main.id]

  user_data = <<-EOF
    #!/bin/bash
    apt-get update -y
    apt-get install -y nginx
    systemctl enable nginx
    systemctl start nginx
  EOF

  tags = {
    Name = "test-video-stream-app"
  }
}

# ---------------------------------------------------------------------------
# Load balancing
# ---------------------------------------------------------------------------

resource "aws_lb" "main" {
  name               = "test-video-stream-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.main.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id, aws_subnet.public_c.id]

  tags = {
    Name = "test-video-stream-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name     = "test-video-stream-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    protocol = "HTTP"
    port     = "80"
    path     = "/"
    matcher  = "200"
  }

  tags = {
    Name = "test-video-stream-tg"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_target_group_attachment" "app" {
  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.app.id
  port             = 80
}

# ---------------------------------------------------------------------------
# DNS
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = local.domain_name

  tags = {
    Name = "test-video-stream-zone"
  }
}

resource "aws_route53_record" "lb_alias_a" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "lb.${local.domain_name}"
  type    = "A"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "lb_alias_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "lb.${local.domain_name}"
  type    = "AAAA"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "apex_alias_a" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.domain_name
  type    = "A"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "apex_alias_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.domain_name
  type    = "AAAA"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "main"
}

locals {
  common_tags = {
    Name        = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-igw"
    }
  )
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-public-a"
    }
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-public-b"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "db" {
  name        = "${var.project_name}-db-sg"
  description = "Restrict PostgreSQL access to TCP 5432 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from the VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "PostgreSQL traffic restricted to the VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-db-sg"
    }
  )
}

resource "aws_db_subnet_group" "main" {
  name        = "${var.project_name}-db-subnet-group"
  description = "Subnet group for the PostgreSQL instance spanning at least two AZs"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-db-subnet-group"
    }
  )
}

resource "aws_db_instance" "postgres" {
  identifier     = "${var.project_name}-postgres"
  engine         = "postgres"
  engine_version = "17.1"
  instance_class = "db.t3.micro"

  # RDS PostgreSQL enforces a 20 GiB minimum for allocated storage,
  # so the requested 5 GB capacity is provisioned at the supported floor.
  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "appdb"
  username = "dbadmin"

  # Master credentials are generated and rotated by AWS Secrets Manager;
  # no plaintext password exists anywhere in this configuration or state.
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  backup_retention_period    = 7
  copy_tags_to_snapshot      = true
  deletion_protection        = true
  multi_az                   = false
  auto_minor_version_upgrade = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.project_name}-postgres-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-postgres"
    }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  db_master_username = "dbadmin"

  common_tags = {
    Environment = "production"
    Project     = "secure-postgres"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC and private database subnets across two AZs
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-vpc"
    }
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "db_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-subnet-a"
      Tier = "database"
    }
  )
}

resource "aws_subnet" "db_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-subnet-b"
      Tier = "database"
    }
  )
}

resource "aws_db_subnet_group" "main" {
  name        = "postgres-prod-db-subnet-group"
  description = "Private subnets for the production PostgreSQL instance"

  subnet_ids = [
    aws_subnet.db_a.id,
    aws_subnet.db_b.id,
  ]

  tags = merge(
    local.common_tags,
    {
      Name = "postgres-prod-db-subnet-group"
    }
  )
}

# -----------------------------------------------------------------------------
# KMS encryption for the database storage and credentials secret
# -----------------------------------------------------------------------------
resource "aws_kms_key" "rds_key" {
  description             = "Customer managed key for RDS PostgreSQL storage encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-kms-key"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds_key" {
  name          = "alias/rds-postgres"
  target_key_id = aws_kms_key.rds_key.key_id
}

# -----------------------------------------------------------------------------
# Database security group (PostgreSQL access restricted to the VPC)
# -----------------------------------------------------------------------------
resource "aws_security_group" "rds" {
  name        = "rds-postgres-sg"
  description = "Allow PostgreSQL traffic only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-sg"
    }
  )
}

# -----------------------------------------------------------------------------
# Custom PostgreSQL 15 parameter group
# -----------------------------------------------------------------------------
resource "aws_db_parameter_group" "postgres" {
  name        = "postgres15-secure-parameters"
  family      = "postgres15"
  description = "Secure PostgreSQL 15 parameter settings"

  parameter {
    name  = "max_connections"
    value = "200"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = merge(
    local.common_tags,
    {
      Name = "postgres15-secure-parameters"
    }
  )
}

# -----------------------------------------------------------------------------
# Master credentials: generated, never plain-text, stored in Secrets Manager
# -----------------------------------------------------------------------------
resource "random_password" "master_password" {
  length           = 24
  special          = true
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_creds" {
  name        = "rds/postgres/prod/master-credentials"
  description = "Master credentials for the production PostgreSQL RDS instance"
  kms_key_id  = aws_kms_key.rds_key.arn

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-master-credentials"
    }
  )
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL instance
# -----------------------------------------------------------------------------
resource "aws_db_instance" "postgres" {
  identifier     = "postgres-prod-db"
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 200
  storage_type          = "gp3"

  db_name  = "appdb"
  username = local.db_master_username
  password = random_password.master_password.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  parameter_group_name   = aws_db_parameter_group.postgres.name

  multi_az            = true
  storage_encrypted   = true
  kms_key_id          = aws_kms_key.rds_key.arn
  publicly_accessible = false

  deletion_protection        = true
  skip_final_snapshot        = false
  final_snapshot_identifier  = "postgres-prod-db-final"
  backup_retention_period    = 14
  backup_window              = "03:00-04:00"
  maintenance_window         = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  tags = merge(
    local.common_tags,
    {
      Name = "postgres-prod-db"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# JSON credential payload in Secrets Manager (created after the instance so
# connection details can be included; the password is never plain-text)
# -----------------------------------------------------------------------------
resource "aws_secretsmanager_secret_version" "db_creds" {
  secret_id = aws_secretsmanager_secret.db_creds.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.master_password.result
    engine   = "postgres"
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = aws_db_instance.postgres.db_name
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "db_endpoint" {
  description = "Connection endpoint (host:port) of the PostgreSQL instance."
  value       = aws_db_instance.postgres.endpoint
}

output "db_address" {
  description = "Hostname of the PostgreSQL instance."
  value       = aws_db_instance.postgres.address
}

output "db_instance_arn" {
  description = "ARN of the PostgreSQL RDS instance."
  value       = aws_db_instance.postgres.arn
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.db_creds.arn
}

###############################################################################
# Airbyte Connector Test Harness - PostgreSQL 15 on AWS RDS
#
# Greenfield configuration: every dependency (VPC, subnets, routing, security
# group, DB subnet group, and master credentials) is created in this file.
# No data lookups against pre-existing infrastructure are used.
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (non-infrastructure metadata only, defaulted for unattended apply)
###############################################################################

variable "environment" {
  description = "Environment tag applied to all resources. Pure metadata; defaulted so terraform apply runs unattended."
  type        = string
  default     = "test"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_cidr        = "10.0.0.0/16"
  master_username = "airbyte_admin"

  # Two distinct AZs resolved from live provider metadata (never hardcoded).
  public_subnet_azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]

  common_tags = {
    Environment = var.environment
    Project     = "airbyte-connector-tests"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Network foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "airbyte-test-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "airbyte-test-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "airbyte-test-public-rt"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = local.public_subnet_azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "airbyte-test-public-subnet-${count.index + 1}"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# RDS subnet group and security group
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "airbyte-test-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "airbyte-test-db-subnet-group"
  })
}

resource "aws_security_group" "rds" {
  name        = "airbyte-test-rds-sg"
  description = "PostgreSQL access restricted to the Airbyte test VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL 5432/tcp from within the Airbyte test VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "airbyte-test-rds-sg"
  })
}

###############################################################################
# Master credentials (generated, stored in Secrets Manager - no plaintext)
###############################################################################

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "rds_master" {
  name        = "airbyte-test/postgres/master"
  description = "Master credentials for the Airbyte connector test PostgreSQL instance"

  tags = merge(local.common_tags, {
    Name = "airbyte-test-postgres-master-secret"
  })
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id = aws_secretsmanager_secret.rds_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.master.result
  })
}

###############################################################################
# RDS PostgreSQL 15 instance
###############################################################################

resource "aws_db_instance" "airbyte_postgres" {
  identifier     = "airbyte-test-postgres"
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"

  # IMPORTANT - USER-SPECIFIED VALUE RETAINED AS-IS:
  # allocated_storage = 5 is kept exactly as requested. Note that AWS RDS
  # enforces a minimum of 20 GiB allocated storage for the PostgreSQL engine;
  # the RDS API will reject 5 GB at apply time. This constraint is surfaced
  # here rather than silently changed - raise to 20 if deployment is required.
  allocated_storage = 5

  db_name  = "airbyte_test"
  username = local.master_username
  password = random_password.master.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true

  # Managed, low-maintenance settings (provider schema argument names:
  # backup_window and maintenance_window, valid top-level arguments of
  # aws_db_instance; backup_window is meaningful given
  # backup_retention_period = 7, and the two windows do not overlap).
  auto_minor_version_upgrade   = true
  backup_retention_period      = 7
  backup_window                = "03:00-04:00"
  maintenance_window           = "sun:05:00-sun:06:00"
  apply_immediately            = false
  multi_az                     = false
  storage_encrypted            = true

  # Disposable test context: no final snapshot on destruction, but the stateful
  # instance itself is still guarded against accidental terraform destroy.
  skip_final_snapshot = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "airbyte-test-postgres"
  })
}

###############################################################################
# Outputs for Airbyte connector test tooling (password is never exposed)
###############################################################################

output "rds_endpoint_address" {
  description = "Connection endpoint (host) of the Airbyte connector test PostgreSQL instance."
  value       = aws_db_instance.airbyte_postgres.address
}

output "rds_port" {
  description = "Port on which the PostgreSQL instance listens."
  value       = aws_db_instance.airbyte_postgres.port
}

output "rds_database_name" {
  description = "Name of the Airbyte test database."
  value       = aws_db_instance.airbyte_postgres.db_name
}

output "rds_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.rds_master.arn
}

# Terraform settings
# NOTE: The `provider "aws"` block (intended region: us-east-1) is intentionally
# omitted — the deployment harness injects the provider configuration externally.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

###############################################################################
# Input variables
###############################################################################

variable "trusted_office_cidr" {
  description = "Explicitly trusted office/VPN CIDR block allowed to reach MySQL (3306). The database is publicly reachable, so this scope must stay narrow; open CIDRs are rejected."
  type        = string
  default     = "10.20.0.0/24"

  validation {
    condition     = can(cidrhost(var.trusted_office_cidr, 0))
    error_message = "trusted_office_cidr must be a valid CIDR block, e.g. 10.20.0.0/24."
  }

  validation {
    condition     = var.trusted_office_cidr != "0.0.0.0/0" && var.trusted_office_cidr != "::/0"
    error_message = "trusted_office_cidr must be an explicit trusted range; 0.0.0.0/0 is not permitted for a publicly accessible database."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "main"
  environment = "production"

  db_name            = "maindb"
  db_master_username = "dbadmin"

  common_tags = {
    Project     = "main"
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking — VPC, public subnets, internet gateway, routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-subnet-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-subnet-b" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# RDS supporting resources — DB subnet group, security group, KMS, credentials
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict MySQL (3306) ingress to the trusted office/VPN CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from trusted office/VPN CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.trusted_office_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-sg" })
}

resource "aws_kms_key" "rds" {
  description             = "Customer-managed key for main MySQL RDS storage and credential secret"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rds-kms" })
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}-mysql-master-credentials"
  description             = "Master credentials for the main MySQL RDS instance"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-mysql-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
    engine   = "mysql"
    port     = 3306
    dbname   = local.db_name
  })
}

###############################################################################
# RDS MySQL instance
###############################################################################

resource "aws_db_instance" "main" {
  identifier     = "${local.name_prefix}-mysql"
  engine         = "mysql"
  engine_version = "5.7.44" # NOTE: MySQL 5.7 is legacy; 5.7.44 is the final 5.7 patch — never omit the patch version.
  instance_class = "db.t3.medium"

  allocated_storage = 500
  storage_type      = "gp3"
  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  db_name = local.db_name

  # Credentials are sourced exclusively from Secrets Manager — never inlined.
  # Schema-valid argument names for aws_db_instance (provider v5): username / password.
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = true # Public endpoint is intentional; ingress is tightly restricted via the db security group.

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true # Copies resource tags onto automated and final snapshots for traceability/recoverability.

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-mysql-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-mysql" })
}

###############################################################################
# Outputs
###############################################################################

output "rds_endpoint" {
  description = "Full connection endpoint (host:port) of the main MySQL RDS instance."
  value       = aws_db_instance.main.endpoint
}

output "rds_address" {
  description = "DNS hostname of the main MySQL RDS instance."
  value       = aws_db_instance.main.address
}

output "rds_port" {
  description = "Port the main MySQL RDS instance listens on."
  value       = aws_db_instance.main.port
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "allowed_ingress_cidr" {
  description = "CIDR block permitted to reach MySQL on TCP 3306. Defaults to 0.0.0.0/0 because a publicly accessible MySQL instance was explicitly requested; restrict this in production."
  type        = string
  default     = "0.0.0.0/0"
}

locals {
  name = "rds-mysql-public"

  master_username = "admin"
  database_name   = "appdb"

  common_tags = {
    Project   = "rds-mysql-public"
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Greenfield networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# RDS subnet group (requires subnets in at least two AZs)
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "${local.name}-subnets"
  description = "Subnet group spanning two AZs for the public MySQL RDS instance."
  subnet_ids  = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnets"
  })
}

# ---------------------------------------------------------------------------
# Master credentials (randomly generated, stored in Secrets Manager)
# ---------------------------------------------------------------------------

resource "random_password" "rds_master" {
  length           = 20
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "random_id" "final_snapshot_suffix" {
  byte_length = 4
}

resource "aws_secretsmanager_secret" "rds_master" {
  name        = "${local.name}-master-password"
  description = "Master credentials for the ${local.name} MySQL RDS instance."

  tags = merge(local.common_tags, {
    Name = "${local.name}-master-password"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id = aws_secretsmanager_secret.rds_master.id
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = local.database_name
    username = local.master_username
    password = random_password.rds_master.result
  })
}

# ---------------------------------------------------------------------------
# Security group
# ---------------------------------------------------------------------------

# INTENTIONAL EXPOSURE: the user explicitly requested a publicly accessible
# MySQL instance, so TCP 3306 ingress is opened to the world (0.0.0.0/0) by
# default via var.allowed_ingress_cidr. Restrict the variable for production.
resource "aws_security_group" "rds" {
  name        = "${local.name}-sg"
  description = "Public MySQL access on TCP 3306 (intentionally open per requirements)."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from allowed CIDR (default 0.0.0.0/0 - explicitly requested public access)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ingress_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-sg"
  })
}

# ---------------------------------------------------------------------------
# RDS MySQL instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "mysql" {
  identifier     = local.name
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.database_name
  username = local.master_username
  password = random_password.rds_master.result
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true
  multi_az               = false

  backup_retention_period    = 7
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name}-final-${random_id.final_snapshot_suffix.hex}"

  tags = merge(local.common_tags, {
    Name = local.name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs (never expose the plaintext password)
# ---------------------------------------------------------------------------

output "rds_endpoint" {
  description = "Connection endpoint (host:port) of the MySQL RDS instance."
  value       = aws_db_instance.mysql.endpoint
}

output "rds_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials. Retrieve the password via AWS CLI/console (e.g. aws secretsmanager get-secret-value --secret-id <arn>); it is never printed by Terraform."
  value       = aws_secretsmanager_secret.rds_master.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "pg-${var.environment}"
}

# Static provider metadata: discover available AZs for subnet placement.
data "aws_availability_zones" "available" {
  state = "available"
}

# Unique suffix so secret and final snapshot names never collide on recreation.
resource "random_string" "suffix" {
  length  = 8
  upper   = false
  special = false
}

# Generated master password — never a plaintext literal.
resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}"
  min_lower        = 2
  min_upper        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = var.environment
  }
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-private-a"
    Environment = var.environment
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-private-b"
    Environment = var.environment
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Private subnets across two AZs for the PostgreSQL instance"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = {
    Name        = "${local.name_prefix}-db-subnet-group"
    Environment = var.environment
  }
}

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Restrict PostgreSQL access to the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic limited to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-rds-sg"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.name_prefix}/db-credentials-${random_string.suffix.result}"
  description = "Master credentials for the ${local.name_prefix} PostgreSQL instance"

  tags = {
    Name        = "${local.name_prefix}-db-credentials"
    Environment = var.environment
  }
}

resource "aws_db_parameter_group" "postgres" {
  name        = "${local.name_prefix}-postgres15-params"
  family      = "postgres15"
  description = "Custom engine parameters for PostgreSQL 15"

  parameter {
    name         = "log_min_duration_statement"
    value        = "5000"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_disconnections"
    value        = "1"
    apply_method = "immediate"
  }

  tags = {
    Name        = "${local.name_prefix}-postgres15-params"
    Environment = var.environment
  }
}

resource "aws_db_instance" "postgres_db" {
  identifier     = "${local.name_prefix}-postgres-db"
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = "appdb"
  username = "appadmin"
  password = random_password.db_master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.postgres.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  multi_az            = true
  publicly_accessible = false

  backup_retention_period = 5
  backup_window           = "03:00-06:00"
  maintenance_window      = "sun:06:30-sun:07:30"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "pg-final-snapshot-${random_string.suffix.result}"
  copy_tags_to_snapshot     = true

  auto_minor_version_upgrade = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "${local.name_prefix}-postgres-db"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.postgres_db.address
    port     = aws_db_instance.postgres_db.port
    dbname   = aws_db_instance.postgres_db.db_name
    username = aws_db_instance.postgres_db.username
    password = random_password.db_master.result
  })
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the PostgreSQL master credentials. Consumers must read the secret by this ARN, never inline the value."
  value       = aws_secretsmanager_secret.db_credentials.arn
}

output "db_instance_endpoint" {
  description = "Connection endpoint of the PostgreSQL instance."
  value       = aws_db_instance.postgres_db.address
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

variable "environment" {
  description = "Environment classification applied as a tag to all resources (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

locals {
  option_group_name = "option-group-pike"
  iam_role_name     = "rds-sqlserver-audit-cloudwatch-logs"
  iam_policy_name   = "rds-sqlserver-audit-cloudwatch-logs-policy"

  rds_log_group_arn_prefix = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/rds/*"

  common_tags = {
    Name        = local.option_group_name
    Environment = var.environment
  }
}

resource "aws_db_option_group" "pike" {
  name                     = local.option_group_name
  option_group_description = "SQL Server Enterprise Edition (major version 11.00) option group enabling Transparent Data Encryption (TDE) and SQL Server audit with CloudWatch Logs export."
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11.00"

  option {
    option_name = "TDE"
  }

  option {
    option_name = "SQLSERVER_AUDIT"

    option_settings {
      name  = "cloudwatch_logs_export"
      value = "true"
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "rds_audit_assume_role" {
  statement {
    sid     = "RDSServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_audit" {
  name               = local.iam_role_name
  description        = "Role assumed by Amazon RDS to publish SQL Server audit logs to Amazon CloudWatch Logs."
  assume_role_policy = data.aws_iam_policy_document.rds_audit_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "rds_audit_cloudwatch_logs" {
  statement {
    sid    = "RDSAuditLogDelivery"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      local.rds_log_group_arn_prefix,
      "${local.rds_log_group_arn_prefix}:*",
    ]
  }
}

resource "aws_iam_role_policy" "rds_audit_cloudwatch_logs" {
  name   = local.iam_policy_name
  role   = aws_iam_role.rds_audit.name
  policy = data.aws_iam_policy_document.rds_audit_cloudwatch_logs.json
}

output "option_group_id" {
  description = "ID of the RDS option group (reference this as option_group_name on a future aws_db_instance)."
  value       = aws_db_option_group.pike.id
}

output "option_group_arn" {
  description = "ARN of the RDS option group."
  value       = aws_db_option_group.pike.arn
}

output "audit_role_arn" {
  description = "ARN of the IAM role assumed by RDS to deliver SQL Server audit logs to CloudWatch Logs."
  value       = aws_iam_role.rds_audit.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# =============================================================================
# Static, well-known lookups only (no pre-existing infrastructure is assumed)
# =============================================================================
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# =============================================================================
# Locals
# =============================================================================
locals {
  project            = "aurora-mysql"
  environment        = "production"
  vpc_cidr           = "10.0.0.0/16"
  db_master_username = "dbadmin"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# =============================================================================
# Networking: VPC, private database subnets, and DB subnet group
# =============================================================================
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-subnet-${count.index + 1}"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.project}-db-subnet-group"
  description = "Private subnets hosting the Aurora MySQL database tier"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-subnet-group"
  })
}

# =============================================================================
# Security groups
# =============================================================================
resource "aws_security_group" "rds_proxy" {
  name        = "${local.project}-proxy-sg"
  description = "RDS Proxy ingress: MySQL 3306 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound to the Aurora cluster and the Secrets Manager endpoint inside the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-proxy-sg"
  })
}

resource "aws_security_group" "aurora" {
  name        = "${local.project}-aurora-sg"
  description = "Aurora cluster ingress: MySQL 3306 from the RDS Proxy security group only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from the RDS Proxy security group"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.rds_proxy.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-aurora-sg"
  })
}

resource "aws_security_group" "secretsmanager_endpoint" {
  name        = "${local.project}-secrets-endpoint-sg"
  description = "HTTPS access to the Secrets Manager interface VPC endpoint"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-secretsmanager-endpoint-sg"
  })
}

# Interface VPC endpoint so the RDS Proxy can reach Secrets Manager from a
# VPC that has no internet access.
resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.secretsmanager_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-secretsmanager-endpoint"
  })
}

# =============================================================================
# KMS encryption, generated credentials, and Secrets Manager
# =============================================================================
resource "aws_kms_key" "db_credentials" {
  description             = "Customer managed key encrypting the Aurora MySQL database credentials secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-credentials-key"
  })
}

resource "aws_kms_alias" "db_credentials" {
  name          = "alias/${local.project}-db-credentials"
  target_key_id = aws_kms_key.db_credentials.key_id
}

resource "random_password" "db_master_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.project}/db/credentials"
  description = "Master credentials for the Aurora MySQL cluster"
  kms_key_id  = aws_kms_key.db_credentials.arn

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master_password.result
  })
}

# =============================================================================
# IAM for the RDS Proxy
# =============================================================================
data "aws_iam_policy_document" "rds_proxy_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_proxy" {
  name               = "${local.project}-proxy-role"
  description        = "Assumed by RDS Proxy to read database credentials"
  assume_role_policy = data.aws_iam_policy_document.rds_proxy_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.project}-proxy-role"
  })
}

data "aws_iam_policy_document" "rds_proxy_secret_access" {
  statement {
    sid       = "ReadDatabaseCredentialsSecret"
    effect    = "Allow"
    actions   = ["secretsmanager:DescribeSecret", "secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.db_credentials.arn]
  }

  statement {
    sid       = "DecryptDatabaseCredentialsSecret"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.db_credentials.arn]
  }
}

resource "aws_iam_role_policy" "rds_proxy_secret_access" {
  name   = "${local.project}-proxy-secret-access"
  role   = aws_iam_role.rds_proxy.name
  policy = data.aws_iam_policy_document.rds_proxy_secret_access.json
}

resource "aws_iam_policy" "rds_proxy_secret_access" {
  name        = "${local.project}-proxy-secret-access"
  description = "Least-privilege access for the RDS Proxy to the database credentials secret"
  policy      = data.aws_iam_policy_document.rds_proxy_secret_access.json

  tags = merge(local.common_tags, {
    Name = "${local.project}-proxy-secret-access-policy"
  })
}

resource "aws_iam_role_policy_attachment" "rds_proxy_secret_access" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = aws_iam_policy.rds_proxy_secret_access.arn
}

# =============================================================================
# Aurora MySQL cluster and instances
# =============================================================================
resource "aws_rds_cluster_parameter_group" "main" {
  name        = "${local.project}-cluster-parameter-group"
  family      = "aurora-mysql8.0"
  description = "Cluster parameters for the Aurora MySQL cluster"

  parameter {
    name  = "slow_query_log"
    value = "1"
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-cluster-parameter-group"
  })
}

resource "aws_rds_cluster" "main" {
  cluster_identifier = "${local.project}-cluster"
  engine             = "aurora-mysql"
  engine_mode        = "provisioned"
  database_name      = "appdb"
  master_username    = local.db_master_username

  # Master credentials are managed by RDS in Secrets Manager; the RDS-created
  # master user secret is encrypted with the dedicated customer-managed KMS key.
  manage_master_user_password   = true
  master_user_secret_kms_key_id = aws_kms_key.db_credentials.arn

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.aurora.id]

  backup_retention_period      = 5
  preferred_backup_window      = "07:00-09:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"

  storage_encrypted         = true
  kms_key_id                = aws_kms_key.db_credentials.arn
  deletion_protection       = true
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.project}-final-snapshot"

  enabled_cloudwatch_logs_exports = ["error", "slowquery"]
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.main.name

  tags = merge(local.common_tags, {
    Name = "${local.project}-aurora-cluster"
  })

  depends_on = [aws_secretsmanager_secret_version.db_credentials]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "main" {
  count = 2

  identifier         = "${local.project}-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.main.id
  engine             = "aurora-mysql"
  engine_version     = aws_rds_cluster.main.engine_version
  instance_class     = "db.r6g.large"

  availability_zone = data.aws_availability_zones.available.names[count.index]

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.db_credentials.arn

  tags = merge(local.common_tags, {
    Name = "${local.project}-aurora-instance-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# RDS Proxy and target wiring
# =============================================================================
resource "aws_db_proxy" "main" {
  name                   = "${local.project}-proxy"
  debug_logging          = false
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  require_tls            = true
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_security_group_ids = [aws_security_group.rds_proxy.id]
  vpc_subnet_ids         = aws_subnet.private[*].id

  auth {
    auth_scheme = "SECRETS"
    description = "Database credentials stored in Secrets Manager"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-proxy"
  })

  depends_on = [
    aws_iam_role_policy.rds_proxy_secret_access,
    aws_iam_role_policy_attachment.rds_proxy_secret_access,
    aws_secretsmanager_secret_version.db_credentials,
  ]
}

resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

# The target type (TRACKED_CLUSTER) is computed automatically by the provider
# from db_cluster_identifier and must not be set explicitly.
resource "aws_db_proxy_target" "main" {
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.id

  depends_on = [aws_db_proxy_default_target_group.main]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "instance_name_prefix" {
  description = "Prefix used to name Lightsail resources in this configuration."
  type        = string
  default     = "lightsail"
}

variable "environment" {
  description = "Value applied to the Environment tag on Lightsail resources."
  type        = string
  default     = "dev"
}

variable "bundle_id" {
  description = "Lightsail bundle (instance size) for the web server."
  type        = string
  default     = "nano_3_0"
}

variable "admin_ssh_cidr" {
  description = "CIDR block permitted to reach TCP/22 (SSH) on the instance. Must not be 0.0.0.0/0."
  type        = string
  default     = "203.0.113.0/24"

  validation {
    condition     = can(cidrnetmask(var.admin_ssh_cidr)) && var.admin_ssh_cidr != "0.0.0.0/0"
    error_message = "admin_ssh_cidr must be a valid IPv4 CIDR and must not be 0.0.0.0/0 (SSH must stay restricted)."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  instance_name = "${var.instance_name_prefix}-web"
}

resource "aws_lightsail_key_pair" "main" {
  name = "${var.instance_name_prefix}-key"
}

resource "aws_lightsail_instance" "main" {
  name              = local.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = {
    Name        = local.instance_name
    Environment = var.environment
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail

    dnf update -y

    dnf install -y nginx

    cat > /usr/share/nginx/html/index.html <<'HTML'
    <!DOCTYPE html>
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <title>Lightsail Web Server</title>
      </head>
      <body>
        <h1>Hello from Amazon Lightsail</h1>
        <p>This landing page was provisioned by Terraform user_data at first boot.</p>
      </body>
    </html>
    HTML

    systemctl enable nginx
    systemctl start nginx
  EOF

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_instance_public_ports" "main" {
  instance_name = aws_lightsail_instance.main.name

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = [var.admin_ssh_cidr]
  }
}

output "instance_public_ip_address" {
  description = "Public IPv4 address of the Lightsail web instance."
  value       = aws_lightsail_instance.main.public_ip_address
}

output "instance_arn" {
  description = "ARN of the Lightsail web instance."
  value       = aws_lightsail_instance.main.arn
}

output "key_pair_name" {
  description = "Name of the Lightsail key pair attached to the instance."
  value       = aws_lightsail_key_pair.main.name
}

output "key_pair_private_key" {
  description = "Private key for the Lightsail key pair. Retrieve once to seed your SSH agent; do not commit or distribute."
  value       = aws_lightsail_key_pair.main.private_key
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (user-controlled, non-infrastructure values with safe defaults)
# ---------------------------------------------------------------------------

variable "instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "web-instance"
}

variable "blueprint_id" {
  description = "Lightsail blueprint ID (OS image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "bundle_id" {
  description = "Lightsail bundle ID (instance size) for the instance."
  type        = string
  default     = "nano_3_0"
}

variable "tags" {
  description = "Tags applied to Lightsail resources that support tagging."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# SSH access credentials
# ---------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "lightsail_key_pair" {
  name = "${var.instance_name}-key-pair"
}

# ---------------------------------------------------------------------------
# Lightsail instance
# ---------------------------------------------------------------------------

resource "aws_lightsail_instance" "web_instance" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.lightsail_key_pair.name

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
  EOF

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Static IPv4 address (independent resource so it survives instance replacement)
# ---------------------------------------------------------------------------

resource "aws_lightsail_static_ip" "static_ip" {
  name = "${var.instance_name}-static-ip"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_static_ip_attachment" "static_ip_attachment" {
  static_ip_name = aws_lightsail_static_ip.static_ip.name
  instance_name  = aws_lightsail_instance.web_instance.name
}

# ---------------------------------------------------------------------------
# Firewall: only the required ports/protocols are opened
# ---------------------------------------------------------------------------

resource "aws_lightsail_instance_public_ports" "web_instance_ports" {
  instance_name = aws_lightsail_instance.web_instance.name

  port_info {
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    protocol   = "tcp"
    from_port  = 80
    to_port    = 80
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    protocol   = "tcp"
    from_port  = 443
    to_port    = 443
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "static_ip_address" {
  description = "Allocated static IPv4 address attached to the Lightsail instance."
  value       = aws_lightsail_static_ip.static_ip.ip_address
}

output "instance_public_ip_address" {
  description = "Public IPv4 address of the Lightsail instance."
  value       = aws_lightsail_instance.web_instance.public_ip_address
}

output "instance_name" {
  description = "Name of the Lightsail instance."
  value       = aws_lightsail_instance.web_instance.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources. Non-secret value with a safe default so terraform apply runs unattended."
  type        = string
  default     = "dev"
}

locals {
  project_name = "mysql-app"

  common_tags = {
    Project     = local.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Database master password generated in-config (never hardcoded, never in a
# variable default). Lightsail forbids '/', '"', and '@' in master passwords,
# so override_special excludes them.
# -----------------------------------------------------------------------------

resource "random_password" "mysql_db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

# -----------------------------------------------------------------------------
# Lightsail compute
# -----------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "mysql_app_server" {
  name = "mysql-app-server-key"
  tags = local.common_tags
}

resource "aws_lightsail_instance" "mysql_app_server" {
  name              = "mysql-app-server"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "micro"
  key_pair_name     = aws_lightsail_key_pair.mysql_app_server.name
  tags              = local.common_tags
}

# Only SSH, HTTP, and HTTPS are exposed publicly. Port 3306 is intentionally
# never opened: Lightsail public ports are all-or-nothing per port, so the
# database port stays closed and the DB remains reachable only over the
# Lightsail internal network.
resource "aws_lightsail_instance_public_ports" "mysql_app_server" {
  instance_name = aws_lightsail_instance.mysql_app_server.name

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }
}

# -----------------------------------------------------------------------------
# Lightsail managed MySQL database
# The MySQL engine (version 8.0) is selected via blueprint_id = "mysql_8_0";
# engine/engine_version are provider-computed attributes and are not
# configurable in the aws provider v5 schema.
# -----------------------------------------------------------------------------

resource "aws_lightsail_database" "mysql_db" {
  relational_database_name     = "mysql-db"
  availability_zone            = data.aws_availability_zones.available.names[0]
  blueprint_id                 = "mysql_8_0"
  bundle_id                    = "micro_ha"
  master_database_name         = "appdb"
  master_username              = "dbadmin"
  master_password              = random_password.mysql_db_master.result
  publicly_accessible          = false
  backup_retention_enabled     = true
  preferred_backup_window      = "03:15-03:45"
  preferred_maintenance_window = "mon:05:00-mon:05:30"
  apply_immediately            = true
  final_snapshot_name          = "mysql-db-final-snapshot"
  tags                         = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Secrets Manager (no plaintext secrets in configuration; the master password
# is the sensitive managed attribute of random_password, the same value fed to
# the database's master_password, and never a literal or variable default)
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "mysql_db_master_password" {
  name        = "mysql-app/mysql-db-master-password"
  description = "Master credentials for the Lightsail MySQL database (aws_lightsail_database.mysql_db)."
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "mysql_db_master_password" {
  secret_id = aws_secretsmanager_secret.mysql_db_master_password.id
  secret_string = jsonencode({
    engine   = aws_lightsail_database.mysql_db.engine
    host     = aws_lightsail_database.mysql_db.master_endpoint_address
    port     = 3306
    dbname   = aws_lightsail_database.mysql_db.master_database_name
    username = aws_lightsail_database.mysql_db.master_username
    password = random_password.mysql_db_master.result
  })
}

resource "aws_secretsmanager_secret" "mysql_app_server_ssh_key" {
  name        = "mysql-app/mysql-app-server-ssh-key"
  description = "SSH private key generated for the Lightsail key pair (aws_lightsail_key_pair.mysql_app_server)."
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "mysql_app_server_ssh_key" {
  secret_id     = aws_secretsmanager_secret.mysql_app_server_ssh_key.id
  secret_string = aws_lightsail_key_pair.mysql_app_server.private_key
}

# -----------------------------------------------------------------------------
# IAM: least-privilege access to the database credentials secret only
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "mysql_app_assume_role" {
  statement {
    sid     = "AllowAssumeByApplicationWorkload"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "mysql_app_server" {
  name               = "mysql-app-server-role"
  description        = "Workload role for the application server; may read only the MySQL database credentials secret."
  assume_role_policy = data.aws_iam_policy_document.mysql_app_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "mysql_db_secret_read" {
  statement {
    sid = "ReadMysqlDbMasterSecret"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = [aws_secretsmanager_secret.mysql_db_master_password.arn]
  }
}

resource "aws_iam_policy" "mysql_db_secret_read" {
  name        = "mysql-app-mysql-db-secret-read"
  description = "Least-privilege read access to the Lightsail MySQL master credentials secret."
  policy      = data.aws_iam_policy_document.mysql_db_secret_read.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "mysql_db_secret_read" {
  role       = aws_iam_role.mysql_app_server.name
  policy_arn = aws_iam_policy.mysql_db_secret_read.arn
}

# -----------------------------------------------------------------------------
# Outputs (references ARNs and non-sensitive endpoints only, never secret values)
# -----------------------------------------------------------------------------

output "mysql_app_server_public_ip" {
  description = "Public IP address of the Lightsail application server instance."
  value       = aws_lightsail_instance.mysql_app_server.public_ip_address
}

output "mysql_db_master_endpoint" {
  description = "Lightsail internal-network endpoint of the MySQL database (not reachable from the internet)."
  value       = aws_lightsail_database.mysql_db.master_endpoint_address
}

output "mysql_db_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials. Reference this ARN instead of the secret value."
  value       = aws_secretsmanager_secret.mysql_db_master_password.arn
}

output "mysql_app_server_ssh_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Lightsail instance SSH private key."
  value       = aws_secretsmanager_secret.mysql_app_server_ssh_key.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "disk_name" {
  description = "Name of the Lightsail disk (also used for the Name tag)"
  type        = string
  default     = "main-data-disk"

  validation {
    condition     = can(regex("^[a-zA-Z0-9]([a-zA-Z0-9\\-_\\.]{1,253}[a-zA-Z0-9])?$", var.disk_name))
    error_message = "Disk name must be 2-255 characters using letters, numbers, hyphens, underscores, or periods."
  }
}

variable "disk_size_gb" {
  description = "Size of the Lightsail disk in GB"
  type        = number
  default     = 32

  validation {
    condition     = var.disk_size_gb >= 8 && var.disk_size_gb <= 16384
    error_message = "Lightsail disk size must be between 8 and 16384 GB."
  }
}

variable "environment" {
  description = "Environment tag applied to the Lightsail disk"
  type        = string
  default     = "production"
}

locals {
  tags = {
    Name        = var.disk_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_lightsail_disk" "main" {
  name              = var.disk_name
  size_in_gb        = var.disk_size_gb
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Terraform + Provider
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Data sources (static lookups only — greenfield account, nothing pre-existing)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Variables (all defaulted so terraform apply runs non-interactively)
###############################################################################

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "bucket_name" {
  description = "Globally-unique, lowercase name for the Lightsail bucket."
  type        = string
  default     = "tf-lightsail-app-bucket-a1b2c3d4"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-.]{1,61}[a-z0-9]$", var.bucket_name))
    error_message = "Bucket name must be 3-63 characters of lowercase letters, numbers, periods, or hyphens."
  }
}

variable "bucket_bundle_id" {
  description = "Lightsail object storage bundle for the bucket."
  type        = string
  default     = "small_1_0"
}

variable "instance_blueprint_id" {
  description = "Lightsail blueprint (OS image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "instance_bundle_id" {
  description = "Lightsail instance bundle (instance size)."
  type        = string
  default     = "nano_3_0"
}

variable "admin_cidr" {
  description = "CIDR block permitted to reach SSH (TCP 22). Keep it narrow; never 0.0.0.0/0."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.admin_cidr)) && var.admin_cidr != "0.0.0.0/0"
    error_message = "admin_cidr must be a valid CIDR block and must not be 0.0.0.0/0."
  }
}

variable "tags" {
  description = "Additional tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "lightsail-bucket-access"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(var.tags, {
    Environment = var.environment
  })
}

###############################################################################
# Lightsail key pair — SSH keys fully Terraform-managed, never the account
# default key pair
###############################################################################

resource "aws_lightsail_key_pair" "app" {
  name = "app_server_key"
  tags = local.common_tags
}

###############################################################################
# Lightsail bucket — private by default (no public access configured), no
# force_destroy, and protected from destruction. Access is granted exclusively
# through the Lightsail resource access grant below.
###############################################################################

resource "aws_lightsail_bucket" "main" {
  name      = var.bucket_name
  bundle_id = var.bucket_bundle_id

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Lightsail instance
###############################################################################

resource "aws_lightsail_instance" "app" {
  name              = "app_server"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.instance_blueprint_id
  bundle_id         = var.instance_bundle_id
  key_pair_name     = aws_lightsail_key_pair.app.name

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    dnf install -y nginx
    systemctl enable --now nginx
    echo "<h1>Lightsail app server</h1>" > /usr/share/nginx/html/index.html
  EOF

  tags = local.common_tags
}

###############################################################################
# Firewall — authoritative port configuration: only SSH from the admin CIDR
# and web ports are open; every other port remains closed.
###############################################################################

resource "aws_lightsail_instance_public_ports" "app" {
  instance_name = aws_lightsail_instance.app.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = [var.admin_cidr]
  }

  port_info {
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidrs     = ["0.0.0.0/0"]
  }
}

###############################################################################
# Least-privilege grant — only this instance may access only this bucket.
# No wildcard resources, no "*" anywhere.
###############################################################################

resource "aws_lightsail_bucket_resource_access" "app_to_bucket" {
  bucket_name   = aws_lightsail_bucket.main.name
  resource_name = aws_lightsail_instance.app.id
}

###############################################################################
# Outputs
###############################################################################

output "bucket_name" {
  description = "Name of the Lightsail bucket."
  value       = aws_lightsail_bucket.main.name
}

output "bucket_url" {
  description = "URL of the Lightsail bucket."
  value       = aws_lightsail_bucket.main.url
}

output "bucket_arn" {
  description = "ARN of the Lightsail bucket."
  value       = aws_lightsail_bucket.main.arn
}

output "instance_public_ip" {
  description = "Public IP address of the Lightsail instance."
  value       = aws_lightsail_instance.app.public_ip_address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used to derive the globally unique archive bucket name."
  type        = string
  default     = "org-archive"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,31}$", var.name_prefix))
    error_message = "name_prefix must be 2-32 lowercase alphanumeric characters or hyphens."
  }
}

variable "environment" {
  description = "Environment identifier (e.g. dev, staging, prod) used in resource names and tags."
  type        = string
  default     = "prod"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,11}$", var.environment))
    error_message = "environment must be 1-12 lowercase alphanumeric characters or hyphens."
  }
}

variable "object_lock_retention_days" {
  description = "Default COMPLIANCE-mode S3 Object Lock retention period in days."
  type        = number
  default     = 365

  validation {
    condition     = var.object_lock_retention_days > 0
    error_message = "Object lock retention must be at least 1 day."
  }
}

variable "noncurrent_version_retention_days" {
  description = "Days after a version becomes noncurrent before it is expired (default 7 years)."
  type        = number
  default     = 2555

  validation {
    condition     = var.noncurrent_version_retention_days > 0
    error_message = "Noncurrent version retention must be at least 1 day."
  }
}

locals {
  bucket_name = "${lower(var.name_prefix)}-${lower(var.environment)}-${random_id.archive_suffix.hex}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Purpose     = "long-term-archive"
  }
}

resource "random_id" "archive_suffix" {
  byte_length = 4
}

resource "aws_kms_key" "archive" {
  description             = "SSE-KMS encryption key for the long-term S3 archive bucket"
  is_enabled              = true
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "glacier_archive" {
  bucket              = local.bucket_name
  object_lock_enabled = true

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.archive.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.glacier_archive.arn,
          "${aws_s3_bucket.glacier_archive.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyPutObjectWithoutKmsEncryption"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.glacier_archive.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.glacier_archive]
}

resource "aws_s3_bucket_lifecycle_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  depends_on = [aws_s3_bucket_versioning.glacier_archive]

  rule {
    id     = "glacier-tiering-and-retention"
    status = "Enabled"

    filter {}

    transition {
      days          = 90
      storage_class = "GLACIER"
    }

    transition {
      days          = 365
      storage_class = "DEEP_ARCHIVE"
    }

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = var.object_lock_retention_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.glacier_archive]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "archive_operator" {
  name        = "${lower(var.name_prefix)}-${lower(var.environment)}-archive-operator"
  description = "Role assumed by archive operators for S3 Glacier ingest and retrieval"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAssumeFromEc2"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "archive_access" {
  name        = "${lower(var.name_prefix)}-${lower(var.environment)}-archive-access"
  description = "Least-privilege access to the S3 archive bucket and its KMS encryption key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListArchiveBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.glacier_archive.arn
      },
      {
        Sid    = "ArchiveObjectActions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:RestoreObject",
        ]
        Resource = "${aws_s3_bucket.glacier_archive.arn}/*"
      },
      {
        Sid    = "ArchiveKmsKeyUsage"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = aws_kms_key.archive.arn
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "archive_operator" {
  role       = aws_iam_role.archive_operator.name
  policy_arn = aws_iam_policy.archive_access.arn
}

output "archive_bucket_id" {
  description = "Name (ID) of the long-term archive bucket."
  value       = aws_s3_bucket.glacier_archive.id
}

output "archive_bucket_arn" {
  description = "ARN of the long-term archive bucket."
  value       = aws_s3_bucket.glacier_archive.arn
}

output "archive_kms_key_arn" {
  description = "ARN of the KMS key used to encrypt archive objects."
  value       = aws_kms_key.archive.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "notification_email" {
  description = "Email endpoint subscribed to the Glacier vault notification SNS topic. The recipient must confirm the SNS subscription email."
  type        = string
  default     = "glacier-ops@example.com"
}

locals {
  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

# Customer managed key used to encrypt the SNS notification topic at rest.
resource "aws_kms_key" "sns" {
  description             = "KMS key for the Glacier vault notification SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
      },
      {
        Sid    = "AllowSNSToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "glacier_vault_notifications_key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic" "glacier_notifications" {
  name              = "glacier_vault_notifications"
  kms_master_key_id = aws_kms_key.sns.arn

  tags = merge(local.common_tags, { Name = "glacier_vault_notifications" })
}

# Note: S3 Glacier automatically encrypts all vault contents at rest with
# AWS-managed AES-256; there is no provider resource for vault-level
# customer-managed key encryption. Recorded below as a tag for traceability.
resource "aws_glacier_vault" "main" {
  name = "glacier_archive_vault"

  notification {
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
    sns_topic = aws_sns_topic.glacier_notifications.arn
  }

  tags = merge(local.common_tags, {
    Name       = "glacier_archive_vault"
    Encryption = "aws-managed-aes256"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege topic policy: Glacier may only publish to this topic and
# only for events originating from the vault declared in this configuration.
resource "aws_sns_topic_policy" "glacier_publish" {
  arn = aws_sns_topic.glacier_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGlacierVaultPublish"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.glacier_notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_glacier_vault.main.arn
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "glacier_notifications_email" {
  topic_arn = aws_sns_topic.glacier_notifications.arn
  protocol  = "email"
  endpoint  = var.notification_email
}

output "glacier_vault_name" {
  description = "Name of the S3 Glacier vault."
  value       = aws_glacier_vault.main.name
}

output "glacier_vault_arn" {
  description = "ARN of the S3 Glacier vault."
  value       = aws_glacier_vault.main.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic receiving Glacier vault event notifications."
  value       = aws_sns_topic.glacier_notifications.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "environment" {
  description = "Environment name applied to all resource tags."
  type        = string
  default     = "production"
}

variable "notification_email" {
  description = "Email address subscribed to Glacier vault archive-retrieval notifications. Non-secret default keeps terraform apply unattended."
  type        = string
  default     = "cloud-ops@example.com"
}

# ------------------------------------------------------------------------------
# Data sources (static lookups only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  vault_name = "archive_vault"
  topic_name = "glacier-notifications"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# KMS key used for server-side encryption of the notification SNS topic
# ------------------------------------------------------------------------------

resource "aws_kms_key" "glacier_notifications" {
  description             = "Customer managed key for server-side encryption of the Glacier vault notification SNS topic."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowGlacierToEncryptNotifications"
        Effect    = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.topic_name}-key"
  })
}

# ------------------------------------------------------------------------------
# SNS topic receiving Glacier vault event notifications
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "glacier_notifications" {
  name              = local.topic_name
  display_name      = "GlacierVaultNotifications"
  kms_master_key_id = aws_kms_key.glacier_notifications.key_id

  tags = merge(local.common_tags, {
    Name = local.topic_name
  })
}

resource "aws_sns_topic_policy" "glacier_notifications" {
  arn = aws_sns_topic.glacier_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGlacierVaultPublish"
        Effect    = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.glacier_notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_glacier_vault.archive_vault.arn
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Glacier vault with archive-retrieval-completed notification wiring
# ------------------------------------------------------------------------------

resource "aws_glacier_vault" "archive_vault" {
  name = local.vault_name

  notification {
    events    = ["ArchiveRetrievalCompleted"]
    sns_topic = aws_sns_topic.glacier_notifications.arn
  }

  tags = merge(local.common_tags, {
    Name = local.vault_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_subscription" "archive_retrieval_email" {
  topic_arn = aws_sns_topic.glacier_notifications.arn
  protocol  = "email"
  endpoint  = var.notification_email
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_type" {
  description = "EC2 instance type for the NLB target instances"
  type        = string
  default     = "t3.micro"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  az_count     = 2
  selected_azs = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Component   = "network-load-balancer"
    }
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc-${var.environment}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw-${var.environment}"
  })
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.selected_azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "public-${local.selected_azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-rt-${var.environment}"
  })
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "targets" {
  name        = "nlb-targets-${var.environment}"
  description = "Allow HTTP traffic to the NLB target instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (application port 80 only)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP health checks from NLB nodes within the VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "nlb-targets-sg-${var.environment}"
  })
}

resource "aws_launch_template" "target" {
  name          = "nlb-target-lt-${var.environment}"
  description   = "Launch template for NLB target instances"
  image_id      = data.aws_ami.al2023.id
  instance_type = var.instance_type

  vpc_security_group_ids = [aws_security_group.targets.id]

  update_default_version = true

  user_data = base64encode(<<-EOT
    #!/bin/bash
    dnf install -y nginx
    systemctl enable nginx
    systemctl start nginx
  EOT
  )

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 8
      volume_type = "gp3"
      encrypted   = true
    }
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name = "nlb-target-${var.environment}"
    })
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(local.common_tags, {
      Name = "nlb-target-${var.environment}"
    })
  }

  tags = merge(local.common_tags, {
    Name = "nlb-target-lt-${var.environment}"
  })
}

resource "aws_autoscaling_group" "targets" {
  name                      = "nlb-targets-asg-${var.environment}"
  min_size                  = local.az_count
  max_size                  = local.az_count
  desired_capacity          = local.az_count
  vpc_zone_identifier       = aws_subnet.public[*].id
  target_group_arns         = [aws_lb_target_group.main.arn]
  health_check_type         = "ELB"
  health_check_grace_period = 60

  launch_template {
    id      = aws_launch_template.target.id
    version = aws_launch_template.target.latest_version
  }

  instance_refresh {
    strategy = "Rolling"

    preferences {
      min_healthy_percentage = 100
    }
  }

  dynamic "tag" {
    for_each = local.common_tags

    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }
}

resource "aws_lb" "main" {
  name                             = "main-nlb-${var.environment}"
  load_balancer_type               = "network"
  internal                         = false
  ip_address_type                  = "ipv4"
  enable_cross_zone_load_balancing = true
  enable_deletion_protection       = true

  subnets = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "main-nlb-${var.environment}"
  })
}

resource "aws_lb_target_group" "main" {
  name                 = "main-tg-${var.environment}"
  port                 = 80
  protocol             = "TCP"
  vpc_id               = aws_vpc.main.id
  target_type          = "instance"
  deregistration_delay = 30

  health_check {
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    port                = "traffic-port"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "main-tg-${var.environment}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "main-listener-${var.environment}"
  })
}

output "nlb_dns_name" {
  description = "Public DNS name of the Network Load Balancer"
  value       = aws_lb.main.dns_name
}

output "target_group_arn" {
  description = "ARN of the NLB target group"
  value       = aws_lb_target_group.main.arn
}

output "asg_name" {
  description = "Name of the Auto Scaling Group serving as NLB targets"
  value       = aws_autoscaling_group.targets.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "alb-nlb-chain"

  # Static, plan-time-deterministic private IPs for the internal NLB,
  # derived from each subnet's literal CIDR block (single source of truth).
  nlb_private_ip_a = cidrhost(aws_subnet.public_a.cidr_block, 10)
  nlb_private_ip_b = cidrhost(aws_subnet.public_b.cidr_block, 10)

  common_tags = {
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# Availability zone lookup (static provider metadata)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Network foundation
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# AMI lookup - Amazon Linux 2023 (public/well-known AMI lookup)
# ---------------------------------------------------------------------------
data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------
resource "aws_security_group" "alb_sg" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Front-tier ALB security group: inbound HTTP/HTTPS from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

resource "aws_security_group" "instance_sg" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Backend instance security group: inbound HTTP only from the ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the front-tier ALB security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-sg"
  })
}

# ---------------------------------------------------------------------------
# Front-tier: internet-facing Application Load Balancer
# ---------------------------------------------------------------------------
resource "aws_lb" "front" {
  name               = "${local.name_prefix}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_lb_target_group" "alb_front" {
  name        = "${local.name_prefix}-alb-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "HTTP"
    path                = "/"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-tg"
  })
}

# ALB -> NLB chaining: register the NLB's static private IPs as IP targets
resource "aws_lb_target_group_attachment" "nlb_ip_a" {
  target_group_arn = aws_lb_target_group.alb_front.arn
  target_id        = local.nlb_private_ip_a
  port             = 80

  depends_on = [aws_lb_listener.nlb_tcp_80]
}

resource "aws_lb_target_group_attachment" "nlb_ip_b" {
  target_group_arn = aws_lb_target_group.alb_front.arn
  target_id        = local.nlb_private_ip_b
  port             = 80

  depends_on = [aws_lb_listener.nlb_tcp_80]
}

resource "aws_lb_listener" "alb_http_80" {
  load_balancer_arn = aws_lb.front.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb_front.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-listener-80"
  })
}

# ---------------------------------------------------------------------------
# Back-tier: internal Network Load Balancer with static private IPs
# ---------------------------------------------------------------------------
resource "aws_lb" "internal_nlb" {
  name               = "${local.name_prefix}-nlb"
  internal           = true
  load_balancer_type = "network"

  subnet_mapping {
    subnet_id            = aws_subnet.public_a.id
    private_ipv4_address = local.nlb_private_ip_a
  }

  subnet_mapping {
    subnet_id            = aws_subnet.public_b.id
    private_ipv4_address = local.nlb_private_ip_b
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nlb"
  })
}

resource "aws_lb_target_group" "nlb_backend" {
  name        = "${local.name_prefix}-nlb-tg"
  port        = 80
  protocol    = "TCP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "80"
    interval            = 30
    timeout             = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nlb-tg"
  })
}

resource "aws_lb_listener" "nlb_tcp_80" {
  load_balancer_arn = aws_lb.internal_nlb.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_backend.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nlb-listener-80"
  })
}

# ---------------------------------------------------------------------------
# Backend tier: EC2 instances (chain terminus)
# ---------------------------------------------------------------------------
resource "aws_instance" "backend_a" {
  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public_a.id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  root_block_device {
    encrypted   = true
    volume_size = 8
    volume_type = "gp3"
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<h1>Backend node: $(hostname -f)</h1>" > /var/www/html/index.html
  EOF

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backend-a"
  })
}

resource "aws_instance" "backend_b" {
  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public_b.id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  root_block_device {
    encrypted   = true
    volume_size = 8
    volume_type = "gp3"
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<h1>Backend node: $(hostname -f)</h1>" > /var/www/html/index.html
  EOF

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backend-b"
  })
}

# Register both instances into the NLB backend target group
resource "aws_lb_target_group_attachment" "backend_a" {
  target_group_arn = aws_lb_target_group.nlb_backend.arn
  target_id        = aws_instance.backend_a.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "backend_b" {
  target_group_arn = aws_lb_target_group.nlb_backend.arn
  target_id        = aws_instance.backend_b.id
  port             = 80
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "alb_dns_name" {
  description = "Public DNS name of the front-tier Application Load Balancer."
  value       = aws_lb.front.dns_name
}

output "nlb_dns_name" {
  description = "Private DNS name of the internal Network Load Balancer."
  value       = aws_lb.internal_nlb.dns_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (all defaulted — terraform apply runs fully non-interactive)
###############################################################################

variable "environment" {
  description = "Environment name used for tagging and resource naming."
  type        = string
  default     = "dev"
}

variable "domain_name" {
  description = "Public domain name for the ALB HTTPS listener certificate."
  type        = string
  default     = "app.example.com"
}

variable "oidc_issuer" {
  description = "OIDC issuer identifier of the identity provider."
  type        = string
  default     = "https://accounts.google.com"
}

variable "oidc_authorization_endpoint" {
  description = "OIDC authorization endpoint of the identity provider."
  type        = string
  default     = "https://accounts.google.com/o/oauth2/v2/auth"
}

variable "oidc_token_endpoint" {
  description = "OIDC token endpoint of the identity provider."
  type        = string
  default     = "https://oauth2.googleapis.com/token"
}

variable "oidc_user_info_endpoint" {
  description = "OIDC user info endpoint of the identity provider."
  type        = string
  default     = "https://openidconnect.googleapis.com/v1/userinfo"
}

variable "oidc_client_id" {
  description = "OIDC client ID issued by the identity provider."
  type        = string
  default     = "replace-with-your-oidc-client-id"
}

variable "application_port" {
  description = "Port the backend targets listen on."
  type        = number
  default     = 80
}

variable "health_check_path" {
  description = "Health check path for the target group."
  type        = string
  default     = "/"
}

variable "tags" {
  description = "Tags applied to every resource (merged with per-resource Name tags)."
  type        = map(string)
  default = {
    Project   = "alb-oidc"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Data sources (static lookups only) and locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  azs             = slice(data.aws_availability_zones.available.names, 0, 2)
  log_prefix      = "alb-access-logs"
  log_bucket_name = "alb-oidc-logs-${data.aws_caller_identity.current.account_id}-${var.environment}"
  common_tags     = merge(var.tags, { Environment = var.environment })
}

###############################################################################
# Networking (built from scratch)
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "alb-oidc-vpc-${var.environment}" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "alb-oidc-igw-${var.environment}" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "public-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 11)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "private-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "public-rt-${var.environment}" })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 2

  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "nat-eip-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_nat_gateway" "main" {
  count = 2

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "nat-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.common_tags, { Name = "private-rt-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "alb-sg-${var.environment}"
  description = "ALB ingress: HTTPS and HTTP from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP from anywhere (redirected to HTTPS)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound to targets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "alb-sg-${var.environment}" })
}

resource "aws_security_group" "targets" {
  name        = "app-sg-${var.environment}"
  description = "Application targets: application port from the ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application port from the ALB security group"
    from_port       = var.application_port
    to_port         = var.application_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "All outbound (software updates via NAT)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "app-sg-${var.environment}" })
}

###############################################################################
# Backend targets (private instances)
###############################################################################

resource "aws_instance" "app" {
  count = 2

  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.private[count.index].id
  vpc_security_group_ids      = [aws_security_group.targets.id]
  associate_public_ip_address = false

  user_data = <<-EOT
    #!/bin/bash
    set -euo pipefail
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<h1>Healthy - backend instance ${count.index}</h1>" > /var/www/html/index.html
  EOT

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 8
  }

  tags = merge(local.common_tags, { Name = "app-${local.azs[count.index]}-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Target group and registration
###############################################################################

resource "aws_lb_target_group" "main" {
  name                 = "tg-oidc-${var.environment}"
  port                 = var.application_port
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = var.health_check_path
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, { Name = "tg-oidc-${var.environment}" })
}

resource "aws_lb_target_group_attachment" "app" {
  count = 2

  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.app[count.index].id
  port             = var.application_port
}

###############################################################################
# ALB access-log S3 bucket
###############################################################################

resource "aws_s3_bucket" "alb_logs" {
  bucket = local.log_bucket_name

  tags = merge(local.common_tags, { Name = local.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBAccessLogDelivery"
        Effect    = "Allow"
        Principal = { Service = "logdelivery.elasticloadbalancing.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.alb_logs.arn}/${local.log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.alb_logs]
}

###############################################################################
# TLS certificate and Application Load Balancer
###############################################################################

resource "aws_acm_certificate" "alb" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  tags = merge(local.common_tags, { Name = "alb-cert-${var.environment}" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb" "main" {
  name               = "alb-oidc-${var.environment}"
  load_balancer_type = "application"
  internal           = false
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = local.log_prefix
    enabled = true
  }

  tags = merge(local.common_tags, { Name = "alb-oidc-${var.environment}" })

  depends_on = [aws_s3_bucket_policy.alb_logs]
}

###############################################################################
# OIDC client secret: generated at apply time (no plaintext anywhere in code)
# and durably persisted in Secrets Manager
###############################################################################

resource "random_password" "oidc_client_secret" {
  length           = 32
  special          = true
  override_special = "-_.~"
}

resource "aws_secretsmanager_secret" "oidc_client_secret" {
  name        = "alb-oidc/client-secret-${var.environment}"
  description = "OIDC client secret used by the ALB authenticate-oidc listener."

  tags = merge(local.common_tags, { Name = "alb-oidc-client-secret-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "oidc_client_secret" {
  secret_id     = aws_secretsmanager_secret.oidc_client_secret.id
  secret_string = random_password.oidc_client_secret.result
}

data "aws_secretsmanager_secret_version" "oidc_client_secret" {
  secret_id = aws_secretsmanager_secret.oidc_client_secret.id

  depends_on = [aws_secretsmanager_secret_version.oidc_client_secret]
}

###############################################################################
# Listeners
###############################################################################

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint     = var.oidc_authorization_endpoint
      token_endpoint             = var.oidc_token_endpoint
      user_info_endpoint         = var.oidc_user_info_endpoint
      issuer                     = var.oidc_issuer
      client_id                  = var.oidc_client_id
      client_secret              = data.aws_secretsmanager_secret_version.oidc_client_secret.secret_string
      session_cookie_name        = "AWSELBAuthSessionCookie-1"
      scope                      = "openid"
      on_unauthenticated_request = "authenticate"
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Project/environment name used for resource naming and tagging."
  type        = string
  default     = "demo"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,20}$", var.environment))
    error_message = "The environment name must be 1-21 lowercase alphanumeric characters or hyphens, starting with a letter."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  account_id           = data.aws_caller_identity.current.account_id
  log_bucket_name      = "${var.environment}-alb-access-logs-${local.account_id}"
  log_prefix           = "${var.environment}/alb-access-logs"
  lambda_function_name = "${var.environment}-alb-lambda"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking foundation
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.environment}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.environment}-igw" })
}

resource "aws_subnet" "public" {
  for_each                = { for idx, az in data.aws_availability_zones.available.names : az => idx }
  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${var.environment}-public-${each.key}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.environment}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each       = aws_subnet.public
  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# ALB security group (HTTP only from the internet)
# ---------------------------------------------------------------------------
resource "aws_security_group" "alb" {
  name        = "${var.environment}-alb-sg"
  description = "Public ALB security group: HTTP from anywhere, all egress allowed"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-alb-sg" })
}

# ---------------------------------------------------------------------------
# Dedicated S3 bucket for ALB access logs
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "alb_logs" {
  bucket = local.log_bucket_name

  tags = merge(local.common_tags, { Name = local.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket                  = aws_s3_bucket.alb_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "alb_logs" {
  statement {
    sid    = "AllowELBLogDeliveryPutObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "arn:aws:s3:::${aws_s3_bucket.alb_logs.id}/${local.log_prefix}/AWSLogs/${local.account_id}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id
  policy = data.aws_iam_policy_document.alb_logs.json

  depends_on = [
    aws_s3_bucket_public_access_block.alb_logs,
    aws_s3_bucket_ownership_controls.alb_logs,
  ]
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------
resource "aws_lb" "main" {
  name               = "${var.environment}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [for subnet in aws_subnet.public : subnet.id]

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = local.log_prefix
    enabled = true
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-alb" })

  depends_on = [aws_s3_bucket_policy.alb_logs]
}

# ---------------------------------------------------------------------------
# Lambda target group
# ---------------------------------------------------------------------------
resource "aws_lb_target_group" "lambda" {
  name                               = "${var.environment}-lambda-tg"
  target_type                        = "lambda"
  lambda_multi_value_headers_enabled = true

  tags = merge(local.common_tags, { Name = "${var.environment}-lambda-tg" })
}

# ---------------------------------------------------------------------------
# Lambda execution role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  name = "${var.environment}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.environment}-lambda-exec-role" })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# ---------------------------------------------------------------------------
# CloudWatch log group with explicit retention
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/${local.lambda_function_name}"
  retention_in_days = 14

  tags = merge(local.common_tags, { Name = "${local.lambda_function_name}-logs" })
}

# ---------------------------------------------------------------------------
# Lambda function (package built in-file from inline handler source)
# ---------------------------------------------------------------------------
data "archive_file" "lambda" {
  type        = "zip"
  output_path = "${path.module}/lambda_payload.zip"

  source {
    content = <<-EOT
      import json


      def lambda_handler(event, context):
          """Handle an ALB request and return a valid ALB Lambda response."""
          return {
              "statusCode": 200,
              "statusDescription": "200 OK",
              "isBase64Encoded": False,
              "headers": {
                  "Content-Type": "text/html; charset=utf-8"
              },
              "body": "<html><body><h1>Hello from Lambda behind an ALB</h1><p>Environment: ${var.environment}</p></body></html>"
          }
      EOT
    filename = "lambda_function.py"
  }
}

resource "aws_lambda_function" "main" {
  function_name    = local.lambda_function_name
  description      = "Lambda target registered in the ${var.environment} application load balancer target group"
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  tags = merge(local.common_tags, { Name = local.lambda_function_name })

  depends_on = [
    aws_cloudwatch_log_group.lambda,
    aws_iam_role_policy_attachment.lambda_basic_execution,
  ]
}

# ---------------------------------------------------------------------------
# ALB invoke permission and target registration
# ---------------------------------------------------------------------------
resource "aws_lambda_permission" "from_alb" {
  statement_id  = "AllowExecutionFromALB"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.main.function_name
  principal     = "elasticloadbalancing.amazonaws.com"
  source_arn    = aws_lb_target_group.lambda.arn
}

resource "aws_lb_target_group_attachment" "lambda" {
  target_group_arn = aws_lb_target_group.lambda.arn
  target_id        = aws_lambda_function.main.arn

  depends_on = [aws_lambda_permission.from_alb]
}

# ---------------------------------------------------------------------------
# HTTP listener forwarding to the Lambda target group
# ---------------------------------------------------------------------------
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda.arn
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "lambda_target_group_arn" {
  description = "ARN of the Lambda target group."
  value       = aws_lb_target_group.lambda.arn
}

output "lambda_function_name" {
  description = "Name of the Lambda function registered as the ALB target."
  value       = aws_lambda_function.main.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function registered as the ALB target."
  value       = aws_lambda_function.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project         = "mysql-db"
  environment     = "production"
  master_username = "admin"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
    Project     = local.project
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-vpc"
  })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "mysql" {
  name        = "${local.project}-sg"
  description = "Allow inbound MySQL from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL to within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.project}-subnet-group"
  description = "Subnet group for the MySQL RDS instance"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.project}-subnet-group"
  })
}

resource "random_password" "master_password" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:"
}

resource "aws_db_instance" "mysql" {
  identifier     = "${local.project}-instance"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t4g.micro"

  db_name  = "appdb"
  username = local.master_username
  password = random_password.master_password.result

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.mysql.id]
  port                   = 3306
  publicly_accessible    = false
  multi_az               = false

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.project}-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.project}-instance"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "master_credentials" {
  name = "${local.project}-master-credentials"

  tags = merge(local.common_tags, {
    Name = "${local.project}-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "master_credentials" {
  secret_id = aws_secretsmanager_secret.master_credentials.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.master_password.result
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
  })
}

output "db_instance_address" {
  description = "DNS address of the RDS MySQL instance"
  value       = aws_db_instance.mysql.address
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the RDS master credentials"
  value       = aws_secretsmanager_secret.master_credentials.arn
}

