}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc"
    },
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "main-igw"
    },
  )
}

resource "aws_subnet" "nat" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-public-subnet"
    },
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "main-public-rt"
    },
  )
}

resource "aws_route_table_association" "nat" {
  subnet_id      = aws_subnet.nat.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = merge(
    local.common_tags,
    {
      Name = "main-nat-eip"
    },
  )
}

resource "aws_nat_gateway" "main" {
  allocation_id     = aws_eip.nat.allocation_id
  subnet_id         = aws_subnet.nat.id
  connectivity_type = "public"

  tags = merge(
    local.common_tags,
    {
      Name = "main-nat-gw"
    },
  )
}

###############################################################################
# main.tf
#
# Default Network ACL with intentionally unrestricted ingress and egress.
#
# SECURITY POSTURE (intentional and explicitly requested):
# The user request explicitly authorizes allow-all (unrestricted) ingress and
# egress rules on the VPC's default network ACL: all protocols, all ports,
# from and to any IPv4 source/destination (0.0.0.0/0) and any IPv6
# source/destination (::/0). This is a documented deviation from the
# least-privilege ingress baseline and is flagged via the
# "NetworkPosture = allow-all" tag.
#
# No subnets, security groups, or other resources are defined in this
# configuration, so nothing silently relies on this permissive default NACL.
# Future workloads should tighten these rules or scope traffic via dedicated
# network ACLs and security groups.
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a consistent tag to all managed resources."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment    = var.environment
    ManagedBy      = "terraform"
    NetworkPosture = "allow-all"
  }
}

# Stateful root networking resource. The default network ACL below must belong
# to this VPC, so the VPC is protected from accidental destruction.
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Manages the VPC's DEFAULT network ACL, adopted via the VPC's
# default_network_acl_id attribute (not a data source and not a separate
# aws_network_acl resource).
#
# NOTE: When Terraform first adopts the default network ACL it removes all
# pre-existing rules, so every desired rule must be declared here. The default
# NACL automatically applies to every subnet in the VPC that has no explicit
# NACL association, so no association resources are declared.
resource "aws_default_network_acl" "main" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  # Ingress rule 100: ALLOW ALL traffic (all protocols/ports) from any IPv4
  # source. Explicitly requested unrestricted ingress posture.
  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Ingress rule 110: ALLOW ALL traffic (all protocols/ports) from any IPv6
  # source, mirroring the IPv4 posture for the second address family.
  ingress {
    rule_no         = 110
    protocol        = "-1"
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  # Egress rule 100: ALLOW ALL traffic (all protocols/ports) to any IPv4
  # destination.
  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Egress rule 110: ALLOW ALL traffic (all protocols/ports) to any IPv6
  # destination.
  egress {
    rule_no         = 110
    protocol        = "-1"
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  tags = merge(
    local.common_tags,
    {
      Name = "main-default-network-acl"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_default_network_acl_id" {
  description = "ID of the VPC's default network ACL as reported by the VPC."
  value       = aws_vpc.main.default_network_acl_id
}

output "default_network_acl_id" {
  description = "ID of the Terraform-managed default network ACL."
  value       = aws_default_network_acl.main.id
}
